INSERT INTO `tbl_language_labels` ( `label_lang_id`, `label_key`, `label_caption`) VALUES
(1, 'LBL_ARE_YOU_SURE_YOU_WANT_TO_SUBMIT_THE_UPDATES?', 'Are you sure you want to perform the final submission for the updates done? After submission, the edit access will be removed.'),
(2, 'LBL_ARE_YOU_SURE_YOU_WANT_TO_SUBMIT_THE_UPDATES?', 'هل أنت متأكد من رغبتك في إجراء الإرسال النهائي للتحديثات التي تم إجراؤها؟ بعد الإرسال، ستتم إزالة حق الوصول للتعديل.'),
(3, 'LBL_ARE_YOU_SURE_YOU_WANT_TO_SUBMIT_THE_UPDATES?', '¿Está seguro de que desea realizar el envío final de las actualizaciones realizadas? Después del envío, se eliminará el acceso de edición.');
INSERT INTO `tbl_language_labels` ( `label_lang_id`, `label_key`, `label_caption`) VALUES
(1, 'LBL_COURSE_EDIT_ACCESS_FOR_LIMITED_DURATION', 'Editing will be allowed for a limited time period. More details will be shared via email.'),
(2, 'LBL_COURSE_EDIT_ACCESS_FOR_LIMITED_DURATION', 'سيُسمح بالتعديل لفترة زمنية محدودة. سيتم مشاركة المزيد من التفاصيل عبر البريد الإلكتروني.'),
(3, 'LBL_COURSE_EDIT_ACCESS_FOR_LIMITED_DURATION', 'Se permitirá la edición por un período de tiempo limitado. Se compartirán más detalles por correo electrónico.');
INSERT INTO `tbl_language_labels` ( `label_lang_id`, `label_key`, `label_caption`) VALUES
(1, 'LBL_COURSE_CHANGES_WILL_VISIBLE_TO_THE_USERS', 'Your updates will be instantly visible to learners on their tutorial page, so please make changes carefully.'),
(2, 'LBL_COURSE_CHANGES_WILL_VISIBLE_TO_THE_USERS', 'ستكون تحديثاتك مرئية فورًا للمتعلمين على صفحة البرنامج التعليمي الخاصة بهم، لذا يرجى إجراء التغييرات بعناية.'),
(3, 'LBL_COURSE_CHANGES_WILL_VISIBLE_TO_THE_USERS', 'Tus actualizaciones serán visibles de inmediato para los alumnos en su página del tutorial, así que realiza los cambios con cuidado.');
INSERT INTO `tbl_language_labels` ( `label_lang_id`, `label_key`, `label_caption`) VALUES
(1, 'LBL_AFTER_DURATION_COURSE_WILL_BE_PUBLISHED_AUTOMATICALLY', 'If the updates are not submited within the allowed time, they will be automatically published after the deadline.'),
(2, 'LBL_AFTER_DURATION_COURSE_WILL_BE_PUBLISHED_AUTOMATICALLY', 'إذا لم يتم تقديم التحديثات في الوقت المسموح به، فسيتم نشرها تلقائيًا بعد انتهاء الموعد النهائي.'),
(3, 'LBL_AFTER_DURATION_COURSE_WILL_BE_PUBLISHED_AUTOMATICALLY', 'Si las actualizaciones no se envían dentro del tiempo permitido, se publicarán automáticamente después de la fecha límite.');
