INSERT INTO `tbl_language_labels` ( `label_lang_id`, `label_key`, `label_caption`) VALUES
(1, 'htmlAfterField_COURSE_EDIT_DURATION_TEXT', 'Number of days for which the course can be edited once the edit request is approved by the admin.'),
