(2, 'LBL_COURSE_EDITING_IN_PROGRESS_UNTIL_{request_date}', 'الدورة قيد التعديل، وسيتم الانتهاء من التغييرات بحلول {request_date}'),
(3, 'LBL_COURSE_EDITING_IN_PROGRESS_UNTIL_{request_date}', 'El curso está en proceso de modificación y los cambios se finalizarán para el {request_date}.');
