INSERT INTO `tbl_extra_pages` (`epage_id`, `epage_identifier`, `epage_block_type`, `epage_type`, `epage_editable`, `epage_active`, `epage_default_content`, `epage_order`) VALUES ('22', 'Creating A Community Section', '22', '1', '1', '1', '<section class=\"section\">\r\n            <div class=\"container container--xxl\">\r\n                <div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n                    <h2>Creating A Community Of Life Long Learners.</h2>\r\n                </div>\r\n                <div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n                    <div class=\"stats-wrapper\">\r\n                        <div class=\"stats-listing\">\r\n                            <div class=\"stats\">\r\n                                <span class=\"stats__number\"><span data-target=\"500\">0</span><i>+</i></span>\r\n                                <span class=\"stats__label\">Learners & counting</span>\r\n                            </div>\r\n                            <div class=\"stats\">\r\n                                <span class=\"stats__number\"><span data-target=\"800\">0</span><i>+</i></span>\r\n                                <span class=\"stats__label\">Courses & Videos</span>\r\n                            </div>\r\n                            <div class=\"stats\">\r\n                                <span class=\"stats__number\"><span data-target=\"1000\">0</span><i>+</i></span>\r\n                                <span class=\"stats__label\">Certified Students</span>\r\n                            </div>\r\n                            <div class=\"stats\">\r\n                                <span class=\"stats__number\"><span data-target=\"100\">0</span><i>+</i></span>\r\n                                <span class=\"stats__label\">Registered Enrolls</span>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </section>', '8');
INSERT INTO `tbl_extra_pages_lang` (`epagelang_epage_id`, `epagelang_lang_id`, `epage_label`, `epage_content`) VALUES
(22, 1, 'Creating a Community', '\r\n<section class=\"section\">            \r\n	<div class=\"container container--xxl\">                \r\n		<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n			<h2>Creating A Community Of Life Long Learners.</h2>                </div>                \r\n		<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n			<div class=\"stats-wrapper\">                        \r\n				<div class=\"stats-listing\">                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"500\">0</span><i>+</i></span>                                <span class=\"stats__label\">Learners &amp; counting</span>                            </div>                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"800\">0</span><i>+</i></span>                                <span class=\"stats__label\">Courses & Videos</span>                            </div>                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"1000\">0</span><i>+</i></span>                                <span class=\"stats__label\">Certified Students</span>                            </div>                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"100\">0</span><i>+</i></span>                                <span class=\"stats__label\">Registered Enrolls</span>                            </div>                        </div>                    </div>                </div>            </div></section>'),
(22, 2, 'إنشاء مجتمع', '\r\n<section class=\"section\">            \r\n	<div class=\"container container--xxl\">                \r\n		<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n			<h2>خلق مجتمع من المتعلمين مدى الحياة.</h2>                </div>                \r\n		<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n			<div class=\"stats-wrapper\">                        \r\n				<div class=\"stats-listing\">                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"500\">0</span><i>+</i></span> <span class=\"stats__label\">المتعلمون والعد</span>                                                            </div>                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"800\">0</span><i>+</i></span>                                <span class=\"stats__label\">Courses & Videos</span>                            </div>                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"1000\">0</span><i>+</i></span>                                <span class=\"stats__label\">الطلبة المعتمدين</span>                            </div>                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"100\">0</span><i>+</i></span>                                <span class=\"stats__label\">المسجلين المسجلين</span>                            </div>                        </div>                    </div>                </div>            </div></section>'),
(22, 3, 'Crear una comunidad', '\r\n<section class=\"section\">            \r\n	<div class=\"container container--xxl\">                \r\n		<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n			<h2>Creando una comunidad de aprendices de por vida.</h2>                </div>                \r\n		<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n			<div class=\"stats-wrapper\">                        \r\n				<div class=\"stats-listing\">                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"500\">0</span><i>+</i></span>                                <span class=\"stats__label\">Aprendices y contando</span>                            </div>                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"800\">0</span><i>+</i></span>                                <span class=\"stats__label\">Courses & Videos</span>                            </div>                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"1000\">0</span><i>+</i></span>                                <span class=\"stats__label\">Estudiantes Certificados</span>                            </div>                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"100\">0</span><i>+</i></span>                                <span class=\"stats__label\">Inscripciones registradas</span>                            </div>                        </div>                    </div>                </div>            </div></section>');
INSERT INTO `tbl_extra_pages_lang` (`epagelang_epage_id`, `epagelang_lang_id`, `epage_label`, `epage_content`) VALUES
(18, 1, 'How To Start Learning?', '    \r\n<section class=\"section section--HowItWorks\">            \r\n	<div class=\"container container--xxl\">                \r\n		<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n			<h2>How w3mentors Works</h2>                </div>                \r\n		<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n			<nav class=\"inline-tabs\">                        \r\n				<ul class=\"js-tab\">                            \r\n					<li><a href=\"#tab__1\" class=\"current\">Choose Your Tutor </a></li>                            \r\n					<li><a href=\"#tab__2\" class=\"\">Become an Expert </a> </li>                            \r\n					<li><a href=\"#tab__3\" class=\"\">Book Your FREE Lesson </a> </li>                        \r\n				</ul>                    </nav>                    \r\n			<div class=\"flex-layout-wrapper\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                        \r\n				<div class=\"tab-container visible\" id=\"tab__1\">                            \r\n					<div class=\"flex-layout\">                                \r\n						<div class=\"flex-layout__media\">                                    <img src=\"/images/choose-your-tutor.png\" alt=\"\" />                                </div>                                \r\n						<div class=\"flex-layout__content\">                                    \r\n							<div class=\"content\">                                        \r\n								<h2>Choose Your Tutor</h2>                                        \r\n								<p class=\"p-large\">We\'ll connect you with a tutor who will motivate, challenge, and inspire you.</p>                                        \r\n								<ul class=\"list list--circle\">                                            \r\n									<li>Certificate Available along-with courses. </li>                                            \r\n									<li>Full Practice Exam with Explanations included! </li>                                            \r\n									<li>Downloadable Assets available in the course </li>                                            \r\n									<li>24x7 teacher\'s support available</li>                                        \r\n								</ul>                                    </div>                                </div>                            </div>                        </div>                        \r\n				<div class=\"tab-container\" id=\"tab__2\">                            \r\n					<div class=\"flex-layout\">                                \r\n						<div class=\"flex-layout__media\">                                    <img src=\"/images/become-an-expert.png\" alt=\"\" />                                </div>                                \r\n						<div class=\"flex-layout__content\">                                    \r\n							<div class=\"content\">                                        \r\n								<h2>Become an Expert</h2>                                        \r\n								<p class=\"p-large\">We\'ll connect you with a tutor who will motivate, challenge, and inspire you.</p>                                        \r\n								<ul class=\"list list--circle\">                                            \r\n									<li>Certificate Available along-with courses. </li>                                            \r\n									<li>Full Practice Exam with Explanations included! </li>                                            \r\n									<li>Downloadable Assets available in the course </li>                                            \r\n									<li>24x7 teacher\'s support available</li>                                        \r\n								</ul>                                    </div>                                </div>                            </div>                        </div>                        \r\n				<div class=\"tab-container\" id=\"tab__3\">                            \r\n					<div class=\"flex-layout\">                                \r\n						<div class=\"flex-layout__media\">                                    <img src=\"/images/book-your-free-lesson.png\" alt=\"\" />                                </div>                                \r\n						<div class=\"flex-layout__content\">                                    \r\n							<div class=\"content\">                                        \r\n								<h2>Book Your FREE Lesson</h2>                                        \r\n								<p class=\"p-large\">We\'ll connect you with a tutor who will motivate, challenge, and inspire you.</p>                                        \r\n								<ul class=\"list list--circle\">                                            \r\n									<li>Certificate Available along-with courses. </li>                                            \r\n									<li>Full Practice Exam with Explanations included! </li>                                            \r\n									<li>Downloadable Assets available in the course </li>                                            \r\n									<li>24x7 teacher\'s support available</li>                                        \r\n								</ul>                                    </div>                                </div>                            </div>                        </div>                    </div>                </div>            </div>        </section>'),
(18, 2, 'كيف تبدأ التعلم؟', '    \r\n<section class=\"section section--HowItWorks\">            \r\n	<div class=\"container container--xxl\">                \r\n		<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n			<h2>كيف يو! أعمال المدرب</h2>                </div>                \r\n		<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n			<nav class=\"inline-tabs\">                        \r\n				<ul class=\"js-tab\">                            \r\n					<li><a href=\"#tab__1\" class=\"current\">اختر مدرسك </a></li>                            \r\n					<li><a href=\"#tab__2\" class=\"\">كن خبيرا </a> </li>                            \r\n					<li><a href=\"#tab__3\" class=\"\">احجز درسك المجاني </a> </li>                        \r\n				</ul>                    </nav>                    \r\n			<div class=\"flex-layout-wrapper\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                        \r\n				<div class=\"tab-container visible\" id=\"tab__1\">                            \r\n					<div class=\"flex-layout\">                                \r\n						<div class=\"flex-layout__media\">                                    <img src=\"/images/choose-your-tutor.png\" alt=\"\" />                                </div>                                \r\n						<div class=\"flex-layout__content\">                                    \r\n							<div class=\"content\">                                        \r\n								<h2>اختر مدرسك</h2>                                        \r\n								<p class=\"p-large\">سنقوم بتوصيلك بمعلم يحفزك ويتحداك ويلهمك.</p>                                        \r\n								<ul class=\"list list--circle\">                                            \r\n									<li>الشهادة متوفرة مع الدورات. </li>                                            \r\n									<li>اختبار تدريبي كامل مع شروح متضمنة! </li>                                            \r\n									<li>الأصول القابلة للتنزيل المتوفرة في الدورة التدريبية </li>                                            \r\n									<li>يتوفر دعم المعلم على مدار 24 ساعة طوال أيام الأسبوع</li>                                        \r\n								</ul>                                    </div>                                </div>                            </div>                        </div>                        \r\n				<div class=\"tab-container\" id=\"tab__2\">                            \r\n					<div class=\"flex-layout\">                                \r\n						<div class=\"flex-layout__media\">                                    <img src=\"/images/become-an-expert.png\" alt=\"\" />                                </div>                                \r\n						<div class=\"flex-layout__content\">                                    \r\n							<div class=\"content\">                                        \r\n								<h2>كن خبيرا</h2>                                        \r\n								<p class=\"p-large\">سنقوم بتوصيلك بمعلم يحفزك ويتحداك ويلهمك.</p>                                        \r\n								<ul class=\"list list--circle\">                                            \r\n									<li>الشهادة متوفرة مع الدورات. </li>                                            \r\n									<li>اختبار تدريبي كامل مع شروح متضمنة! </li>                                            \r\n									<li>الأصول القابلة للتنزيل المتوفرة في الدورة التدريبية </li>                                            \r\n									<li>يتوفر دعم المعلم على مدار 24 ساعة طوال أيام الأسبوع</li>                                        \r\n								</ul>                                    </div>                                </div>                            </div>                        </div>                        \r\n				<div class=\"tab-container\" id=\"tab__3\">                            \r\n					<div class=\"flex-layout\">                                \r\n						<div class=\"flex-layout__media\">                                    <img src=\"/images/book-your-free-lesson.png\" alt=\"\" />                                </div>                                \r\n						<div class=\"flex-layout__content\">                                    \r\n							<div class=\"content\">                                        \r\n								<h2>احجز درسك المجاني</h2>                                        \r\n								<p class=\"p-large\">سنقوم بتوصيلك بمعلم يحفزك ويتحداك ويلهمك.</p>                                        \r\n								<ul class=\"list list--circle\">                                            \r\n									<li>الشهادة متوفرة مع الدورات. </li>                                            \r\n									<li>اختبار تدريبي كامل مع شروح متضمنة! </li>                                            \r\n									<li>الأصول القابلة للتنزيل المتوفرة في الدورة التدريبية </li>                                            \r\n									<li>يتوفر دعم المعلم على مدار 24 ساعة طوال أيام الأسبوع</li>                                        \r\n								</ul>                                    </div>                                </div>                            </div>                        </div>                    </div>                </div>            </div>        </section>'),
(18, 3, '¿Cómo empezar a aprender?', '    \r\n<section class=\"section section--HowItWorks\">            \r\n	<div class=\"container container--xxl\">                \r\n		<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n			<h2>¡Cómo Yo! Trabajos de autocar</h2>                </div>                \r\n		<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n			<nav class=\"inline-tabs\">                        \r\n				<ul class=\"js-tab\">                            \r\n					<li><a href=\"#tab__1\" class=\"current\">Elige a tu tutor </a></li>                            \r\n					<li><a href=\"#tab__2\" class=\"\">Convi&eacute;rtete en un experto </a> </li>                            \r\n					<li><a href=\"#tab__3\" class=\"\">Reserva tu clase GRATIS </a> </li>                        \r\n				</ul>                    </nav>                    \r\n			<div class=\"flex-layout-wrapper\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                        \r\n				<div class=\"tab-container visible\" id=\"tab__1\">                            \r\n					<div class=\"flex-layout\">                                \r\n						<div class=\"flex-layout__media\">                                    <img src=\"/images/choose-your-tutor.png\" alt=\"\" />                                </div>                                \r\n						<div class=\"flex-layout__content\">                                    \r\n							<div class=\"content\">                                        \r\n								<h2>Elige a tu tutor</h2>                                        \r\n								<p class=\"p-large\">Te pondremos en contacto con un tutor que te motivará, te desafiará y te inspirará.</p>                                        \r\n								<ul class=\"list list--circle\">                                            \r\n									<li>Certificado Disponible junto con los cursos. </li>                                            \r\n									<li>¡Examen de práctica completo con explicaciones incluidas! </li>                                            \r\n									<li>Recursos descargables disponibles en el curso </li>                                            \r\n									<li>Soporte del maestro disponible las 24 horas del día, los 7 días de la semana</li>                                        \r\n								</ul>                                    </div>                                </div>                            </div>                        </div>                        \r\n				<div class=\"tab-container\" id=\"tab__2\">                            \r\n					<div class=\"flex-layout\">                                \r\n						<div class=\"flex-layout__media\">                                    <img src=\"/images/become-an-expert.png\" alt=\"\" />                                </div>                                \r\n						<div class=\"flex-layout__content\">                                    \r\n							<div class=\"content\">                                        \r\n								<h2>Convi&eacute;rtete en un experto</h2>                                        \r\n								<p class=\"p-large\">Te pondremos en contacto con un tutor que te motivará, te desafiará y te inspirará.</p>                                        \r\n								<ul class=\"list list--circle\">                                            \r\n									<li>Certificado Disponible junto con los cursos. </li>                                            \r\n									<li>¡Examen de práctica completo con explicaciones incluidas! </li>                                            \r\n									<li>Recursos descargables disponibles en el curso </li>                                            \r\n									<li>Soporte del maestro disponible las 24 horas del día, los 7 días de la semana</li>                                        \r\n								</ul>                                    </div>                                </div>                            </div>                        </div>                        \r\n				<div class=\"tab-container\" id=\"tab__3\">                            \r\n					<div class=\"flex-layout\">                                \r\n						<div class=\"flex-layout__media\">                                    <img src=\"/images/book-your-free-lesson.png\" alt=\"\" />                                </div>                                \r\n						<div class=\"flex-layout__content\">                                    \r\n							<div class=\"content\">                                        \r\n								<h2>Reserva tu clase GRATIS</h2>                                        \r\n								<p class=\"p-large\">Te pondremos en contacto con un tutor que te motivará, te desafiará y te inspirará.</p>                                        \r\n								<ul class=\"list list--circle\">                                            \r\n									<li>Certificado Disponible junto con los cursos. </li>                                            \r\n									<li>¡Examen de práctica completo con explicaciones incluidas! </li>                                            \r\n									<li>Recursos descargables disponibles en el curso </li>                                            \r\n									<li>Soporte del maestro disponible las 24 horas del día, los 7 días de la semana</li>                                        \r\n								</ul>                                    </div>                                </div>                            </div>                        </div>                    </div>                </div>            </div>        </section>');
