INSERT INTO `tbl_extra_pages` (`epage_id`, `epage_identifier`, `epage_block_type`, `epage_type`, `epage_editable`, `epage_active`, `epage_default_content`, `epage_order`) VALUES
(1, 'Teacher Profile info bar', 1, 5, 1, 1, '<div class=\"infobar__list-content\">\r\n										<ol>\r\n											<li>Profile needs to be 80% completed</li>\r\n											<li>You have to complete lorem ipsum dolar summit text</li>\r\n											<li>After verify all the details you have to mark availbility in calendar section.</li>\r\n										</ol>\r\n									</div>', 0),
(2, 'We make language learning easy & simpler', 2, 1, 1, 1, '<div class=\"container container--xxl\">\n                <div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n                    <h2>We Make Language Learning Easy & Simpler</h2>\n                </div>\n                <div class=\"section__body\">\n                    <div class=\"grid-blocks\">\n                        <div class=\"cms-block\" data-aos=\"fade-right\" data-aos-duration=\"1000\">\n                            <div class=\"cms-block__media\">\n                                <div class=\"media ratio ratio--4by3\">\n                                    <img src=\"/images/cms-block-img__1.png\" alt=\"\">\n                                </div>\n                            </div>\n                            <div class=\"cms-block__content\">\n                                <h3>Professional Tutors</h3>\n                                <p>Choose from over a myriad of professional & experienced teachers to be fluent in any language.</p>\n                            </div>\n                        </div>\n                        <div class=\"cms-block\" data-aos=\"fade-up\" data-aos-duration=\"600\">\n                            <div class=\"cms-block__media\">\n                                <div class=\"media ratio ratio--4by3\">\n                                    <img src=\"/images/cms-block-img__2.png\" alt=\"\">\n                                </div>\n                            </div>\n                            <div class=\"cms-block__content\">\n                                <h3>1-on-1 Live sessions</h3>\n                                <p>Connect with your teachers via 1-on-1 live chat sessions and build a deeper understanding of a language.</p>\n                            </div>\n                        </div>\n                        <div class=\"cms-block\" data-aos=\"fade-left\" data-aos-duration=\"1000\">\n                            <div class=\"cms-block__media\">\n                                <div class=\"media ratio ratio--4by3\">\n                                    <img src=\"/images/cms-block-img__3.png\" alt=\"\">\n                                </div>\n                            </div>\n                            <div class=\"cms-block__content\">\n                                <h3>Group Classes</h3>\n                                <p>Choose from over a myriad of professional & experienced teachers to be fluent in any language.</p>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>', 7),
(3, 'Browse teacher section', 3, 1, 1, 1, '<section class=\"section\">\r\n <div class=\"container container--xxl\">\r\n <div class=\"section--cta\" style=\"background-image:url(/image/editor-image/1600x514.jpg);\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n <div class=\"cta-content\">\r\n <h6></h6>\r\n <h2>Learn any Subject with the help of professional teachers</h2>\r\n <a class=\"btn btn--primary btn--large\" href=\"courses\">Browse Teachers</a>\r\n </div>\r\n </div>\r\n </div>\r\n</section>', 2),
(4, 'Contact Banner', 4, 3, 1, 1, '<div class=\"intro-head\">\n <h6 class=\"small-title\">Contact Us</h6>\n <h1>Want to get in touch?<br />\n We would love to hear from you.</h1></div>\n<div class=\"about-media\">\n <div class=\"media\"><img src=\"images/contact_hero.png\" alt=\"\" /></div></div>', 0),
(5, 'Contact left section', 5, 3, 1, 1, '<div class=\"col-md-5 col-lg-4\">    \r\n	<div class=\"contact-info\">        \r\n		<div class=\"contact-info__row\">            \r\n			<div class=\"contact__icon\">                \r\n				<svg class=\"icon icon--address\">                    \r\n					<use xlink:href=\"images/sprite.svg#address\"></use>                </svg>            </div>            \r\n			<div class=\"contact__content\">                \r\n				<h6>Address</h6>                \r\n				<p>Company Pvt. Ltd.<br />\r\n					                    ITC 3, Sector 67, Sahibzada Ajit Singh Nagar,<br />\r\n					                    Mohali, Punjab</p>            </div>        </div>        \r\n		<div class=\"contact-info__row\">            \r\n			<div class=\"contact__icon\">                \r\n				<svg class=\"icon icon--mail\">                    \r\n					<use xlink:href=\"images/sprite.svg#mail\"></use>                </svg>            </div>            \r\n			<div class=\"contact__content\">                \r\n				<h6>Email</h6>                \r\n				<p>sales@fatbit.com <br />\r\n					                    sales@fatbit.com</p>            </div>        </div>        \r\n		<div class=\"contact-info__row\">            \r\n			<div class=\"contact__icon\">                \r\n				<svg class=\"icon icon--telephone\">                    \r\n					<use xlink:href=\"images/sprite.svg#telephone\"></use>                </svg>            </div>            \r\n			<div class=\"contact__content\">                \r\n				<h6>Phone no.</h6>                \r\n				<p> +1 469 844 3346  <br />\r\n					                     +1 469 844 3346  <br />\r\n					                    +1 469 844 3346 </p>            </div>        </div>    </div></div>', 0),
(6, 'Benefits section', 6, 2, 1, 1, '<section class=\"section section--services\">        \r\n	<div class=\"container container--narrow\">            \r\n		<div class=\"section__head\">                \r\n			<h2>Benefits to become a tutor on w3mentors?</h2>            </div>            \r\n		<div class=\"section__body\">                \r\n			<div class=\"row\">                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n                      \r\n						<div class=\"service__media\">                                <img src=\"/images/55x55_1.png\" />                            </div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Earn Money Online</h3>                                \r\n							<p>Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.</p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n                      \r\n						<div class=\"service__media\">                                <img src=\"/images/55x55_2.png\" />                            </div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Work Anywhere, Anytime</h3>                                \r\n							<p>Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur.</p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n                      \r\n						<div class=\"service__media\">                                <img src=\"/images/55x55_3.png\" />                            </div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Teach on Your Schedule.</h3>                                \r\n							<p>Excepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum</p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n                      \r\n						<div class=\"service__media\">                                <img src=\"/images/55x55_4.png\" />                            </div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Manage Your Students</h3>                                \r\n							<p>Nam libero tempore, cum soluta nobis est eligendi optio cumque nihil impedit quo minus id quod maxime placeat facere possimus,</p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n						<div class=\"service__media\">                                <img src=\"/images/55x55_5.png\" />                            </div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Find More Students</h3>                                \r\n							<p>Excepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum</p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-6\">                