(7, 'Apply to teach features section', 7, 2, 1, 1, '\r\n<section class=\"section \" id=\"how-it-works\" style=\"background-color: var(--color-gray-100);\">        \r\n	<div class=\"container container--narrow\">            \r\n		<div class=\"row justify-content-between\">                \r\n			<div class=\"col-xl-4 col-lg-4 col-md-6\">                    \r\n				<div class=\"section__head align-left margin-bottom-5\">                        \r\n					<h2>Teach students from over 180 countries</h2>                    </div>                    \r\n				<ul class=\"list-group list-group--line margin-bottom-5\">                        \r\n					<li class=\"list-group--item\">Steady stream of new students</li>                        \r\n					<li class=\"list-group--item\">Smart calendar</li>                        \r\n					<li class=\"list-group--item\">Interactive classroom</li>                        \r\n					<li class=\"list-group--item\">Convenient payment methods</li>                        \r\n					<li class=\"list-group--item\">Training webinars</li>                        \r\n					<li class=\"list-group--item\">Supportive tutor community</li>                    \r\n				</ul>                    \r\n				<button class=\"btn btn--secondary applytoteach\">Apply to Teach</button></div>                \r\n			<div class=\"col-xl-6 col-lg-6 col-md-6\">                    \r\n				<div class=\"media_group\">                        \r\n					<div class=\"media_group--item\">                            \r\n                      \r\n						<div class=\"ratio ratio--4by3\">                                <img src=\"/image/editor-image/1650023574-apply43.png\" alt=\"Image\" />                            </div>                        </div>                        \r\n					<div class=\"media_group--item media_group--item-small\">                            \r\n                      \r\n						<div class=\"ratio ratio--4by3\">                                <img src=\"/image/editor-image/1650023662-apply2.png\" alt=\"Image\" />                            </div>                        </div>                    </div>                </div>            </div>        </div>    </section>', 0),
(8, 'Apply to Teach Become a tutor', 8, 2, 1, 1, '<div class=\"container container--narrow\">        \r\n	<div class=\"section__head \">            \r\n		<h2>How to Become a Teacher on the Platform?</h2>        </div>        \r\n	<div class=\"section__body\">            \r\n		<div class=\"service--wrapper\">                \r\n			<div class=\"row\">                    \r\n				<div class=\"col-lg-4\">                        \r\n					<div class=\"service service--vertical\">                            \r\n						<div class=\"service__media\"> <img src=\"/image/editor-image/register.png\" alt=\"\" style=\"float: none; margin: 0px; width: 45px; height: 45px;\" /> </div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Register on Platform</h3>                                \r\n							<p><span style=\"font-family: Georgia; font-size: 16px; white-space: pre-wrap;\">Register as a teacher on Platform and start filling in the required information.</span></p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-4\">                        \r\n					<div class=\"service service--vertical\">                            \r\n						<div class=\"service__media\"> <img src=\"/image/editor-image/completeprofile.png\" alt=\"\" style=\"float: none; margin: 0px; width: 40px; height: 45px;\" /> </div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Complete Profile</h3>                                \r\n							<p><span style=\"font-family: Georgia; font-size: 16px; white-space: pre-wrap;\">Complete the profile by adding qualifications, experience, and skills.</span></p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-4\">                        \r\n					<div class=\"service service--vertical\">                            \r\n						<div class=\"service__media\"> <img src=\"/image/editor-image/online-learning.png\" alt=\"\" style=\"float: none; margin: 0px; width: 50px; height: 39px;\" /> </div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Start Teaching</h3>                                \r\n							<p><span style=\"font-family: Georgia; font-size: 16px; white-space: pre-wrap;\">Accept session requests and start taking online classes.</span></p>                            </div>                        </div>                    </div>                </div>            </div>        </div>    </div>   ', 0),
(9, 'Apply to teach static banner section', 9, 2, 1, 1, '\n<section class=\"section section--cta\" style=\"background-image:url(images/cta_2.jpg);\">        \n	<div class=\"container container--narrow\">            \n		<div class=\"cta-content\">                \n			<h2 class=\"margin-bottom-5\">Do you want to become a teacher on w3mentors?</h2>                \n			<p class=\"margin-bottom-5\">Connect with thousands of learners around the world and teach from your living room</p>                <a class=\"btn btn--secondary btn--large applytoteach\">Apply Now</a>            </div>        </div>    </section>', 0),
