(18, 'How To Start Learning?', 18, 1, 1, 1, '<section class=\"section section--HowItWorks\">\n            <div class=\"container container--xxl\">\n                <div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n                    <h2>How w3mentors Works</h2>\n                </div>\n                <div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n                    <nav class=\"inline-tabs\">\n                        <ul class=\"js-tab\">\n                            <li><a href=\"#tab__1\" class=\"current\">Choose Your Tutor </a></li>\n                            <li><a href=\"#tab__2\" class=\"\">Become an Expert </a> </li>\n                            <li><a href=\"#tab__3\" class=\"\">Book Your FREE Lesson </a> </li>\n                        </ul>\n                    </nav>\n                    <div class=\"flex-layout-wrapper\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n                        <div class=\"tab-container visible\" id=\"tab__1\">\n                            <div class=\"flex-layout\">\n                                <div class=\"flex-layout__media\">\n                                    <img src=\"/images/choose-your-tutor.png\" alt=\"\">\n                                </div>\n                                <div class=\"flex-layout__content\">\n                                    <div class=\"content\">\n                                        <h2>Choose Your Tutor</h2>\n                                        <p class=\"p-large\">We\'ll connect you with a tutor who will motivate, challenge, and inspire you.</p>\n                                        <ul class=\"list list--circle\">\n                                            <li>Certificate Available along-with courses. </li>\n                                            <li>Full Practice Exam with Explanations included! </li>\n                                            <li>Downloadable Assets available in the course </li>\n                                            <li>24x7 teacher\'s support available</li>\n                                        </ul>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                        <div class=\"tab-container\" id=\"tab__2\">\n                            <div class=\"flex-layout\">\n                                <div class=\"flex-layout__media\">\n                                    <img src=\"/images/become-an-expert.png\" alt=\"\">\n                                </div>\n                                <div class=\"flex-layout__content\">\n                                    <div class=\"content\">\n                                        <h2>Become an Expert</h2>\n                                        <p class=\"p-large\">We\'ll connect you with a tutor who will motivate, challenge, and inspire you.</p>\n                                        <ul class=\"list list--circle\">\n                                            <li>Certificate Available along-with courses. </li>\n                                            <li>Full Practice Exam with Explanations included! </li>\n                                            <li>Downloadable Assets available in the course </li>\n                                            <li>24x7 teacher\'s support available</li>\n                                        </ul>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                        <div class=\"tab-container\" id=\"tab__3\">\n                            <div class=\"flex-layout\">\n                                <div class=\"flex-layout__media\">\n                                    <img src=\"/images/book-your-free-lesson.png\" alt=\"\">\n                                </div>\n                                <div class=\"flex-layout__content\">\n                                    <div class=\"content\">\n                                        <h2>Book Your FREE Lesson</h2>\n                                        <p class=\"p-large\">We\'ll connect you with a tutor who will motivate, challenge, and inspire you.</p>\n                                        <ul class=\"list list--circle\">\n                                            <li>Certificate Available along-with courses. </li>\n                                            <li>Full Practice Exam with Explanations included! </li>\n                                            <li>Downloadable Assets available in the course </li>\n                                            <li>24x7 teacher\'s support available</li>\n                                        </ul>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </section>', 5),
(19, 'Affiliate Register banner section', 19, 6, 1, 1, '<h3><span style=\\\"font-size: 36pt;\\\">Make Money with Our Affiliate Program!</span></h3>\\r\\n<ul>\\r\\n	<li> <span style=\\\"font-size: 14pt;\\\">Joining our affiliate program is simple and free! You can earn revenue by referring potential customers to our website. </span></li>\\r\\n	<li><span style=\\\"font-size: 14pt;\\\">  Whether you\\\'re a big content network, active on social media, or an experienced blogger, you can earn commissions on referred purchases and sign-ups. </span></li>\\r\\n	<li><span style=\\\"font-size: 14pt;\\\">For more information, please visit our FAQ page, and don\\\'t forget to read our Terms &amp; Conditions!</span></li>\\r\\n</ul>', 4),
(20, 'Popular Subjects', 20, 1, 0, 1, '', 1),
(21, 'Browse Courses section', 21, 1, 1, 0, '<section class=\"section\">\r\n <div class=\"container container--xxl\">\r\n <div class=\"section--cta\" style=\"background-image:url(/image/editor-image/1600x514.jpg);\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n <div class=\"cta-content\">\r\n <h6>Premium learning experience</h6>\r\n <h2>Providing Amazing Online Courses.</h2>\r\n <a class=\"btn btn--primary btn--large\" href=\"courses\">View Courses</a>\r\n </div>\r\n </div>\r\n </div>\r\n</section>', 12),
(22, 'Creating A Community Section', 22, 1, 1, 1, '<section class=\"section\">\r\n            <div class=\"container container--xxl\">\r\n                <div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n                    <h2>Creating A Community Of Life Long Learners.</h2>\r\n                </div>\r\n                <div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n                    <div class=\"stats-wrapper\">\r\n                        <div class=\"stats-listing\">\r\n                            <div class=\"stats\">\r\n                                <span class=\"stats__number\"><span data-target=\"500\">0</span><i>+</i></span>\r\n                                <span class=\"stats__label\">Learners & counting</span>\r\n                            </div>\r\n                            <div class=\"stats\">\r\n                                <span class=\"stats__number\"><span data-target=\"800\">0</span><i>+</i></span>\r\n                                <span class=\"stats__label\">Courses & Videos</span>\r\n                            </div>\r\n                            <div class=\"stats\">\r\n                                <span class=\"stats__number\"><span data-target=\"1000\">0</span><i>+</i></span>\r\n                                <span class=\"stats__label\">Certified Students</span>\r\n                            </div>\r\n                            <div class=\"stats\">\r\n                                <span class=\"stats__number\"><span data-target=\"100\">0</span><i>+</i></span>\r\n                                <span class=\"stats__label\">Registered Enrolls</span>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </section>', 4),
(23, 'Courses with Categories', 23, 1, 0, 0, '', 13),
(24, 'Join Now Section', 24, 1, 1, 1, '<section class=\"section\">\r\n    <div class=\"container container--xxl\">\r\n        <div class=\"grid-layout\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n            <div class=\"grid-layout__item\">\r\n                <div class=\"cta-card\">\r\n                    <div class=\"cta-card__media\">\r\n                        <img src=\"/images/cta__student-img.png\" alt=\"\">\r\n                    </div>\r\n                    <div class=\"cta-card__content\">\r\n                        <h2>Join now to start learning</h2>\r\n                        <p>Learn from our quality instructors!</p>\r\n                        <a href=\"guest-user/registration-form\" class=\"btn btn--primary btn--large\">Get Started</a>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n            <div class=\"grid-layout__item\">\r\n                <div class=\"cta-card\">\r\n                    <div class=\"cta-card__media\">\r\n                        <img src=\"/images/cta__student-img-2.png\" alt=\"\">\r\n                    </div>\r\n                    <div class=\"cta-card__content\">\r\n                        <h2>Become a new instructor</h2>\r\n                        <p>Teach thousands of students and earn money!</p>\r\n                        <a href=\"teacher-request\" class=\"btn btn--primary btn--large\">Get Started</a>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>', 9),
(25, 'Subscription Plans', 25, 1, 0, 0, '', 15);
INSERT INTO `tbl_extra_pages_lang` (`epagelang_epage_id`, `epagelang_lang_id`, `epage_label`, `epage_content`) VALUES
(1, 1, 'Teacher Profile info bar', '<div class=\"infobar__list-content\">\r\n										<ol>\r\n											<li>Profile needs to be 80% completed</li>\r\n											<li>You have to complete lorem ipsum dolar summit text</li>\r\n											<li>After verify all the details you have to mark availbility in calendar section.</li>\r\n										</ol>\r\n									</div>'),
(1, 2, 'شريط معلومات الملف الشخصي للمعلم', '\r\n<div class=\"infobar__list-content\">\r\n	<ol>\r\n		<li>يجب أن يكتمل الملف الشخصي بنسبة 80٪</li>\r\n		<li>يجب عليك إكمال نص قمة lorem ipsum dolar</li>\r\n		<li>بعد التحقق من جميع التفاصيل ، يجب عليك تحديد مدى التوفر في قسم التقويم.</li>\r\n	</ol></div> '),
(1, 3, 'Barra de información del perfil del profesor', '\r\n<div class=\"infobar__list-content\">\r\n	<ol>\r\n		<li>El perfil debe completarse en un 80%</li>\r\n		<li>Tienes que completar el texto de la cumbre lorem ipsum dolar</li>\r\n		<li>Despu&eacute;s de verificar todos los detalles, debe marcar la disponibilidad en la sección del calendario.</li>\r\n	</ol></div>'),
(2, 1, 'Why Us Block', '\r\n<div class=\"container container--xxl\">                \r\n	<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n		<h2>We Make Language Learning Easy &amp; Simpler</h2>                </div>                \r\n	<div class=\"section__body\">                    \r\n		<div class=\"grid-blocks\">                        \r\n			<div class=\"cms-block\" data-aos=\"fade-right\" data-aos-duration=\"1000\">                            \r\n				<div class=\"cms-block__media\">                                \r\n					<div class=\"media ratio ratio--4by3\">                                    <img src=\"/image/editor-image/cms-block-img__1.png\" alt=\"\" />                                </div>                            </div>                            \r\n				<div class=\"cms-block__content\">                                \r\n					<h3>Professional Tutors</h3>                                \r\n					<p>Choose from over a myriad of professional &amp; experienced teachers to be fluent in any language.</p>                            </div>                        </div>                        \r\n			<div class=\"cms-block\" data-aos=\"fade-up\" data-aos-duration=\"600\">                            \r\n				<div class=\"cms-block__media\">                                \r\n					<div class=\"media ratio ratio--4by3\">                                    <img src=\"/image/editor-image/cms-block-img__2.png\" alt=\"\" />                                </div>                            </div>                            \r\n				<div class=\"cms-block__content\">                                \r\n					<h3>1-on-1 Live sessions</h3>                                \r\n					<p>Connect with your teachers via 1-on-1 live chat sessions and build a deeper understanding of a language.</p>                            </div>                        </div>                        \r\n			<div class=\"cms-block\" data-aos=\"fade-left\" data-aos-duration=\"1000\">                            \r\n				<div class=\"cms-block__media\">                                \r\n					<div class=\"media ratio ratio--4by3\">                                    <img src=\"/image/editor-image/cms-block-img__3.png\" alt=\"\" />                                </div>                            </div>                            \r\n				<div class=\"cms-block__content\">                                \r\n					<h3>Group Classes</h3>                                \r\n					<p>Choose from over a myriad of professional &amp; experienced teachers to be fluent in any language.</p>                            </div>                        </div>                    </div>                </div>            </div>'),
(2, 2, 'لماذا نحن الحظر', '\r\n<div class=\"container container--xxl\">                \r\n	<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n		<h2>نجعل تعلم اللغة سهلا وأبسط</h2>                </div>                \r\n	<div class=\"section__body\">                    \r\n		<div class=\"grid-blocks\">                        \r\n			<div class=\"cms-block\" data-aos=\"fade-right\" data-aos-duration=\"1000\">                            \r\n				<div class=\"cms-block__media\">                                \r\n					<div class=\"media ratio ratio--4by3\">                                    <img src=\"/image/editor-image/cms-block-img__1.png\" alt=\"\" />                                </div>                            </div>                            \r\n				<div class=\"cms-block__content\">                                \r\n					<h3>مدرسون محترفون</h3>                                \r\n					<p>اختر من بين عدد لا يحصى من المعلمين المحترفين وذوي الخبرة لتكون بطلاقة في أي لغة.</p>                            </div>                        </div>                        \r\n			<div class=\"cms-block\" data-aos=\"fade-up\" data-aos-duration=\"600\">                            \r\n				<div class=\"cms-block__media\">                                \r\n					<div class=\"media ratio ratio--4by3\">                                    <img src=\"/image/editor-image/cms-block-img__2.png\" alt=\"\" />                                </div>                            </div>                            \r\n				<div class=\"cms-block__content\">                                \r\n					<h3>جلسات مباشرة 1 على 1</h3>                                \r\n					<p>تواصل مع معلميك عبر جلسات الدردشة المباشرة الفردية وقم ببناء فهم أعمق للغة.</p>                            </div>                        </div>                        \r\n			<div class=\"cms-block\" data-aos=\"fade-left\" data-aos-duration=\"1000\">                            \r\n				<div class=\"cms-block__media\">                                \r\n					<div class=\"media ratio ratio--4by3\">                                    <img src=\"/image/editor-image/cms-block-img__3.png\" alt=\"\" />                                </div>                            </div>                            \r\n				<div class=\"cms-block__content\">                                \r\n					<h3>فصول جماعية</h3>                                \r\n					<p>اختر من بين عدد لا يحصى من المعلمين المحترفين وذوي الخبرة لتكون بطلاقة في أي لغة.</p>                            </div>                        </div>                    </div>                </div>            </div>'),
(2, 3, '¿Por qué bloqueamos?', '\r\n<div class=\"container container--xxl\">                \r\n	<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n		<h2>Hacemos que el aprendizaje de idiomas sea fácil y sencillo</h2>                </div>                \r\n	<div class=\"section__body\">                    \r\n		<div class=\"grid-blocks\">                        \r\n			<div class=\"cms-block\" data-aos=\"fade-right\" data-aos-duration=\"1000\">                            \r\n				<div class=\"cms-block__media\">                                \r\n					<div class=\"media ratio ratio--4by3\">                                    <img src=\"/image/editor-image/cms-block-img__1.png\" alt=\"\" />                                </div>                            </div>                            \r\n				<div class=\"cms-block__content\">                                \r\n					<h3>Tutores Profesionales</h3>                                \r\n					<p>Elija entre una gran cantidad de profesores profesionales y experimentados para hablar con fluidez cualquier idioma.</p>                            </div>                        </div>                        \r\n			<div class=\"cms-block\" data-aos=\"fade-up\" data-aos-duration=\"600\">                            \r\n				<div class=\"cms-block__media\">                                \r\n					<div class=\"media ratio ratio--4by3\">                                    <img src=\"/image/editor-image/cms-block-img__2.png\" alt=\"\" />                                </div>                            </div>                            \r\n				<div class=\"cms-block__content\">                                \r\n					<h3>Sesiones en vivo 1 a 1</h3>                                \r\n					<p>Conéctate con tus profesores a través de sesiones de chat en vivo 1 a 1 y desarrolla una comprensión más profunda de un idioma.</p>                            </div>                        </div>                        \r\n			<div class=\"cms-block\" data-aos=\"fade-left\" data-aos-duration=\"1000\">                            \r\n				<div class=\"cms-block__media\">                                \r\n					<div class=\"media ratio ratio--4by3\">                                    <img src=\"/image/editor-image/cms-block-img__3.png\" alt=\"\" />                                </div>                            </div>                            \r\n				<div class=\"cms-block__content\">                                \r\n					<h3>Clases Grupales</h3>                                \r\n					<p>Elija entre una gran cantidad de profesores profesionales y experimentados para hablar con fluidez cualquier idioma.</p>                            </div>                        </div>                    </div>                </div>            </div>'),
(3, 1, 'Browse Teacher', '\r\n<section class=\"section\"> \r\n	<div class=\"container container--xxl\"> \r\n		<div class=\"section--cta\" style=\"background-image:url(/image/editor-image/1600x514.jpg);\" data-aos=\"fade-up\" data-aos-duration=\"1000\"> \r\n			<div class=\"cta-content\"> \r\n				<h6></h6> \r\n				<h2>Learn any Subject with the help of professional teachers</h2> <a class=\"btn btn--primary btn--large\" href=\"teachers\">Browse Teachers</a> </div> </div> </div></section> '),
