(5, 3, 'Contacto Sección Izquierda', '\r\n<div class=\"col-md-5 col-lg-4\">    \r\n	<div class=\"contact-info\">        \r\n		<div class=\"contact-info__row\">            \r\n			<div class=\"contact__icon\">                \r\n				<svg class=\"icon icon--address\">                    \r\n					<use xlink:href=\"images/sprite.svg#address\"></use>                </svg>            </div>            \r\n			<div class=\"contact__content\">                \r\n				<h6>Dirección</h6>                \r\n				<p>CIC 3, Sector 67,<br />Sahibzada Ajit Singh Nagar,<br />Punjab 160062</p>            </div>        </div>        \r\n		<div class=\"contact-info__row\">            \r\n			<div class=\"contact__icon\">                \r\n				<svg class=\"icon icon--mail\">                    \r\n					<use xlink:href=\"images/sprite.svg#mail\"></use>                </svg>            </div>            \r\n			<div class=\"contact__content\">                \r\n				<h6>Correo electrónico</h6>                \r\n				<p>sales@fatbit.com <br />sales@fatbit.com</p>            </div>        </div>        \r\n		<div class=\"contact-info__row\">            \r\n			<div class=\"contact__icon\">                \r\n				<svg class=\"icon icon--telephone\">                    \r\n					<use xlink:href=\"images/sprite.svg#telephone\"></use>                </svg>            </div>            \r\n			<div class=\"contact__content\">                \r\n				<h6>Nº de teléfono</h6>                \r\n				<p>+1 469 844 3346 <br />+1 469 844 3346 <br />+1 469 844 3346</p>            </div>        </div>    </div></div>'),
(6, 1, 'Benefits of becoming a teacher', '\r\n<section class=\"section section--services\">        \r\n	<div class=\"container container--narrow\">            \r\n		<div class=\"section__head\">                \r\n			<h2>Benefits of becoming a teacher on Yo! Coach?</h2>            </div>            \r\n		<div class=\"section__body\">                \r\n			<div class=\"row\">                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n                      \r\n						<div class=\"service__media\"><img src=\"https://teach.w3mentors.com/images/55x55_1.png\" alt=\"Earn Money Online\" /><br />\r\n							</div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Make money online</h3>                                \r\n							<p>Opportunity to make money online from working from home<br />\r\n								</p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n                      \r\n						<div class=\"service__media\"><img src=\"https://teach.w3mentors.com/images/55x55_2.png\" alt=\"Work Anywhere, Anytime\" /><br />\r\n							</div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Work anywhere, anytime</h3>                                \r\n							<p>Flexibility to teach at home without wasting productive time.</p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n                      \r\n						<div class=\"service__media\"><img src=\"https://teach.w3mentors.com/images/55x55_3.png\" alt=\"Teach on Your Schedule\" /><br />\r\n							</div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Mark on your schedule.</h3>                                \r\n							<p>The ability to perform your educational duties at your convenience.</p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n                      \r\n						<div class=\"service__media\"><img src=\"https://teach.w3mentors.com/images/55x55_4.png\" alt=\"Manage Your Students\" /><br />\r\n							</div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Manage your students</h3>                                \r\n							<p>Teach as many students as possible or as few students as you like.</p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n						<div class=\"service__media\"><img src=\"https://teach.w3mentors.com/images/55x55_5.png\" alt=\"Find More Students\" /><br />\r\n							</div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Find more students</h3>                                \r\n							<p>Ability to teach students from all over the world without traveling.</p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n                      \r\n						<div class=\"service__media\"><img src=\"https://teach.w3mentors.com/images/55x55_6.png\" alt=\"Safety and Security\" /><br />\r\n							</div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Safety &amp; Security</h3>                                \r\n							<p>Considering all the benefits, you will be professionally satisfied.</p>                            </div>                        </div>                    </div>                </div>            </div>        </div>    </section>   '),
(6, 2, 'فوائد لتصبح مدرسا', '\r\n<section class=\"section section--services\">        \r\n	<div class=\"container container--narrow\">            \r\n		<div class=\"section__head\">                \r\n			<h2>فوائد لتصبح مدرسا على Yo! مدرب؟</h2>            </div>            \r\n		<div class=\"section__body\">                \r\n			<div class=\"row\">                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n                      \r\n						<div class=\"service__media\"><img src=\"https://teach.w3mentors.com/images/55x55_1.png\" alt=\"Earn Money Online\" /><br />\r\n							</div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>كسب المال عبر الإنترنت</h3>                                \r\n							<p>فرصة لكسب المال عبر الإنترنت من العمل من المنزل<br />\r\n								</p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n                      \r\n						<div class=\"service__media\"><img src=\"https://teach.w3mentors.com/images/55x55_2.png\" alt=\"Work Anywhere, Anytime\" /><br />\r\n							</div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>العمل في أي مكان وفي أي وقت</h3>                                \r\n							<p>المرونة في التدريس في المنزل دون إضاعة الوقت الإنتاجي.</p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n                      \r\n						<div class=\"service__media\"><img src=\"https://teach.w3mentors.com/images/55x55_3.png\" alt=\"Teach on Your Schedule\" /><br />\r\n							</div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>علم على جدولك الزمني.</h3>                                \r\n							<p>القدرة على أداء واجباتك التعليمية على راحتك.</p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n                      \r\n						<div class=\"service__media\"><img src=\"https://teach.w3mentors.com/images/55x55_4.png\" alt=\"Manage Your Students\" /><br />\r\n							</div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>إدارة طلابك</h3>                                \r\n							<p>قم بتدريس أكبر عدد ممكن أو أقل عدد ممكن من الطلاب حسب راحتك.</p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n						<div class=\"service__media\"><img src=\"https://teach.w3mentors.com/images/55x55_5.png\" alt=\"Find More Students\" /><br />\r\n							</div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>البحث عن المزيد من الطلاب</h3>                                \r\n							<p>القدرة على تعليم الطلاب من جميع أنحاء العالم دون السفر.</p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n                      \r\n						<div class=\"service__media\"><img src=\"https://teach.w3mentors.com/images/55x55_6.png\" alt=\"Safety and Security\" /><br />\r\n							</div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>السلامة والأمن</h3>                                \r\n							<p>بالنظر إلى جميع الفوائد ، سوف تكون راضيا مهنيا.</p>                            </div>                        </div>                    </div>                </div>            </div>        </div>    </section>   '),
(6, 3, 'Beneficios de convertirse en profesor', '\r\n<section class=\"section section--services\">        \r\n	<div class=\"container container--narrow\">            \r\n		<div class=\"section__head\">                \r\n			<h2>Beneficios de convertirse en profesor en Yo! ¿Coche?</h2>            </div>            \r\n		<div class=\"section__body\">                \r\n			<div class=\"row\">                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n                      \r\n						<div class=\"service__media\"><img src=\"https://teach.w3mentors.com/images/55x55_1.png\" alt=\"Earn Money Online\" /><br />\r\n							</div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Ganar dinero en línea</h3>                                \r\n							<p>Oportunidad de ganar dinero en línea trabajando desde casa<br />\r\n								</p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n                      \r\n						<div class=\"service__media\"><img src=\"https://teach.w3mentors.com/images/55x55_2.png\" alt=\"Work Anywhere, Anytime\" /><br />\r\n							</div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Trabaje en cualquier lugar y en cualquier momento</h3>                                \r\n							<p>Flexibilidad para enseñar en casa sin perder tiempo productivo.</p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n                      \r\n						<div class=\"service__media\"><img src=\"https://teach.w3mentors.com/images/55x55_3.png\" alt=\"Teach on Your Schedule\" /><br />\r\n							</div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Márcalo en tu horario.</h3>                                \r\n							<p>La capacidad de realizar sus deberes educativos a su conveniencia.</p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n                      \r\n						<div class=\"service__media\"><img src=\"https://teach.w3mentors.com/images/55x55_4.png\" alt=\"Manage Your Students\" /><br />\r\n							</div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Gestiona a tus alumnos</h3>                                \r\n							<p>Enseñe a tantos estudiantes como sea posible o a tantos estudiantes como desee.</p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n						<div class=\"service__media\"><img src=\"https://teach.w3mentors.com/images/55x55_5.png\" alt=\"Find More Students\" /><br />\r\n							</div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Buscar más estudiantes</h3>                                \r\n							<p>Capacidad para enseñar a estudiantes de todo el mundo sin viajar.</p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-6\">                        \r\n					<div class=\"service service--horizontal\">                            \r\n                      \r\n						<div class=\"service__media\"><img src=\"https://teach.w3mentors.com/images/55x55_6.png\" alt=\"Safety and Security\" /><br />\r\n							</div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Seguridad y protección</h3>                                \r\n							<p>Teniendo en cuenta todos los beneficios, quedará satisfecho profesionalmente.</p>                            </div>                        </div>                    </div>                </div>            </div>        </div>    </section>   '),
(7, 1, 'Apply to teach features section', '\r\n<section class=\"section \" id=\"how-it-works\" style=\"background-color: var(--color-gray-100);\">        \r\n	<div class=\"container container--narrow\">            \r\n		<div class=\"row justify-content-between\">                \r\n			<div class=\"col-xl-4 col-lg-4 col-md-6\">                    \r\n				<div class=\"section__head align-left margin-bottom-5\">                        \r\n					<h2>Teach students from over 180 countries</h2>                    </div>                    \r\n				<ul class=\"list-group list-group--line margin-bottom-5\">                        \r\n					<li class=\"list-group--item\">Steady stream of new students</li>                        \r\n					<li class=\"list-group--item\">Smart calendar</li>                        \r\n					<li class=\"list-group--item\">Interactive classroom</li>                        \r\n					<li class=\"list-group--item\">Convenient payment methods</li>                        \r\n					<li class=\"list-group--item\">Training webinars</li>                        \r\n					<li class=\"list-group--item\">Supportive tutor community</li>                    \r\n				</ul>                    \r\n				<button class=\"btn btn--secondary applytoteach\">Apply to Teach</button></div>                \r\n			<div class=\"col-xl-6 col-lg-6 col-md-6\">                    \r\n				<div class=\"media_group\">                        \r\n					<div class=\"media_group--item\">                            \r\n                      \r\n						<div class=\"ratio ratio--4by3\">                                <img src=\"/image/editor-image/1650023574-apply43.png\" alt=\"Image\" />                            </div>                        </div>                        \r\n					<div class=\"media_group--item media_group--item-small\">                            \r\n                      \r\n						<div class=\"ratio ratio--4by3\">                                <img src=\"/image/editor-image/1650023662-apply2.png\" alt=\"Image\" />                            </div>                        </div>                    </div>                </div>            </div>        </div>    </section>'),
(7, 2, 'تطبيق على قسم ميزات التدريس', '\r\n<section class=\"section \" id=\"how-it-works\" style=\"background-color: var(--color-gray-100);\">        \r\n	<div class=\"container container--narrow\">            \r\n		<div class=\"row justify-content-between\">                \r\n			<div class=\"col-xl-4 col-lg-4 col-md-6\">                    \r\n				<div class=\"section__head align-left margin-bottom-5\">                        \r\n					<h2>تعليم الطلاب من أكثر من 180 دولة</h2>                    </div>                    \r\n				<ul class=\"list-group list-group--line margin-bottom-5\">                        \r\n					<li class=\"list-group--item\">تدفق مستمر من الطلاب الجدد</li>                        \r\n					<li class=\"list-group--item\">التقويم الذكي</li>                        \r\n					<li class=\"list-group--item\">الفصول الدراسية التفاعلية</li>                        \r\n					<li class=\"list-group--item\">طرق دفع مريحة</li>                        \r\n					<li class=\"list-group--item\">ندوات تدريبية عبر الإنترنت</li>                        \r\n					<li class=\"list-group--item\">مجتمع المعلم الداعم</li>                    \r\n				</ul>                    \r\n				<button class=\"btn btn--secondary applytoteach\">تقدم بطلب للتدريس</button></div>                \r\n			<div class=\"col-xl-6 col-lg-6 col-md-6\">                    \r\n				<div class=\"media_group\">                        \r\n					<div class=\"media_group--item\">                            \r\n                      \r\n						<div class=\"ratio ratio--4by3\">                                <img src=\"/image/editor-image/1650023574-apply43.png\" alt=\"Image\" />                            </div>                        </div>                        \r\n					<div class=\"media_group--item media_group--item-small\">                            \r\n                      \r\n						<div class=\"ratio ratio--4by3\">                                <img src=\"/image/editor-image/1650023662-apply2.png\" alt=\"Image\" />                            </div>                        </div>                    </div>                </div>            </div>        </div>    </section>'),
(7, 3, 'Aplicar a la sección de características de enseñanza', '\r\n<section class=\"section \" id=\"how-it-works\" style=\"background-color: var(--color-gray-100);\">        \r\n	<div class=\"container container--narrow\">            \r\n		<div class=\"row justify-content-between\">                \r\n			<div class=\"col-xl-4 col-lg-4 col-md-6\">                    \r\n				<div class=\"section__head align-left margin-bottom-5\">                        \r\n					<h2>Enseña a estudiantes de más de 180 países</h2>                    </div>                    \r\n				<ul class=\"list-group list-group--line margin-bottom-5\">                        \r\n					<li class=\"list-group--item\">Flujo constante de nuevos estudiantes</li>                        \r\n					<li class=\"list-group--item\">Calendario inteligente</li>                        \r\n					<li class=\"list-group--item\">Aula interactiva</li>                        \r\n					<li class=\"list-group--item\">Métodos de pago convenientes</li>                        \r\n					<li class=\"list-group--item\">Seminarios web de formación</li>                        \r\n					<li class=\"list-group--item\">Comunidad de tutores de apoyo</li>                    \r\n				</ul>                    \r\n				<button class=\"btn btn--secondary applytoteach\">Aplicar para enseñar</button></div>                \r\n			<div class=\"col-xl-6 col-lg-6 col-md-6\">                    \r\n				<div class=\"media_group\">                        \r\n					<div class=\"media_group--item\">                            \r\n                      \r\n						<div class=\"ratio ratio--4by3\">                                <img src=\"/image/editor-image/1650023574-apply43.png\" alt=\"Image\" />                            </div>                        </div>                        \r\n					<div class=\"media_group--item media_group--item-small\">                            \r\n                      \r\n						<div class=\"ratio ratio--4by3\">                                <img src=\"/image/editor-image/1650023662-apply2.png\" alt=\"Image\" />                            </div>                        </div>                    </div>                </div>            </div>        </div>    </section>'),
(8, 1, 'Apply to teach Become a teacher', '<div class=\"container container--narrow\">        \r\n	<div class=\"section__head \">            \r\n		<h2>How to Become a Teacher on the Platform?</h2>        </div>        \r\n	<div class=\"section__body\">            \r\n		<div class=\"service--wrapper\">                \r\n			<div class=\"row\">                    \r\n				<div class=\"col-lg-4\">                        \r\n					<div class=\"service service--vertical\">                            \r\n						<div class=\"service__media\"> <img src=\"/image/editor-image/register.png\" alt=\"\" style=\"float: none; margin: 0px; width: 45px; height: 45px;\" /> </div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Register on Platform</h3>                                \r\n							<p><span style=\"font-family: Georgia; font-size: 16px; white-space: pre-wrap;\">Register as a teacher on Platform and start filling in the required information.</span></p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-4\">                        \r\n					<div class=\"service service--vertical\">                            \r\n						<div class=\"service__media\"> <img src=\"/image/editor-image/completeprofile.png\" alt=\"\" style=\"float: none; margin: 0px; width: 40px; height: 45px;\" /> </div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Complete Profile</h3>                                \r\n							<p><span style=\"font-family: Georgia; font-size: 16px; white-space: pre-wrap;\">Complete the profile by adding qualifications, experience, and skills.</span></p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-4\">                        \r\n					<div class=\"service service--vertical\">                            \r\n						<div class=\"service__media\"> <img src=\"/image/editor-image/online-learning.png\" alt=\"\" style=\"float: none; margin: 0px; width: 50px; height: 39px;\" /> </div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Start Teaching</h3>                                \r\n							<p><span style=\"font-family: Georgia; font-size: 16px; white-space: pre-wrap;\">Accept session requests and start taking online classes.</span></p>                            </div>                        </div>                    </div>                </div>            </div>        </div>    </div>   '),
(8, 2, 'تقدم بطلب للتدريس كن مدرسا', '<div class=\"container container--narrow\">        \r\n	<div class=\"section__head \">            \r\n		<h2>كيف تصبح مدرسا على المنصة؟</h2>        </div>        \r\n	<div class=\"section__body\">            \r\n		<div class=\"service--wrapper\">                \r\n			<div class=\"row\">                    \r\n				<div class=\"col-lg-4\">                        \r\n					<div class=\"service service--vertical\">                            \r\n						<div class=\"service__media\"><img src=\"/image/editor-image/register.png\" alt=\"\" style=\"float: none; margin: 0px; width: 45px; height: 45px;\" /> </div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>التسجيل على المنصة</h3>                                \r\n							<p><span style=\"font-family: Georgia; font-size: 16px; white-space: pre-wrap;\">سجل كمدرس على المنصة وابدأ في ملء المعلومات المطلوبة.</span></p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-4\">                        \r\n					<div class=\"service service--vertical\">                            \r\n						<div class=\"service__media\"><img src=\"/image/editor-image/completeprofile.png\" alt=\"\" style=\"float: none; margin: 0px; width: 40px; height: 45px;\" /> </div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>الملف الشخصي الكامل</h3>                                \r\n							<p><span style=\"font-family: Georgia; font-size: 16px; white-space: pre-wrap;\">أكمل الملف الشخصي بإضافة المؤهلات والخبرات والمهارات.</span></p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-4\">                        \r\n					<div class=\"service service--vertical\">                            \r\n						<div class=\"service__media\"><img src=\"/image/editor-image/online-learning.png\" alt=\"\" style=\"float: none; margin: 0px; width: 50px; height: 39px;\" /> </div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>ابدأ التدريس</h3>                                \r\n							<p><span style=\"font-family: Georgia; font-size: 16px; white-space: pre-wrap;\">اقبل طلبات الجلسة وابدأ في أخذ دروس عبر الإنترنت.</span></p>                            </div>                        </div>                    </div>                </div>            </div>        </div>    </div>   '),
(8, 3, 'Aplicar para enseñar Conviértete en profesor', '\r\n<div class=\"container container--narrow\">        \r\n	<div class=\"section__head \">            \r\n		<h2>¿Cómo convertirse en profesor en la plataforma?</h2>        </div>        \r\n	<div class=\"section__body\">            \r\n		<div class=\"service--wrapper\">                \r\n			<div class=\"row\">                    \r\n				<div class=\"col-lg-4\">                        \r\n					<div class=\"service service--vertical\">                            \r\n						<div class=\"service__media\"><img src=\"/image/editor-image/register.png\" alt=\"\" style=\"float: none; margin: 0px; width: 45px; height: 45px;\" /> </div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Regístrese en la plataforma</h3>                                \r\n							<p><span style=\"font-family: Georgia; font-size: 16px; white-space: pre-wrap;\">Regístrate como profesor en la plataforma y comienza a completar la información requerida.</span></p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-4\">                        \r\n					<div class=\"service service--vertical\">                            \r\n						<div class=\"service__media\"><img src=\"/image/editor-image/completeprofile.png\" alt=\"\" style=\"float: none; margin: 0px; width: 40px; height: 45px;\" /> </div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Perfil completo</h3>                                \r\n							<p><span style=\"font-family: Georgia; font-size: 16px; white-space: pre-wrap;\">Complete el perfil agregando calificaciones, experiencia y habilidades.</span></p>                            </div>                        </div>                    </div>                    \r\n				<div class=\"col-lg-4\">                        \r\n					<div class=\"service service--vertical\">                            \r\n						<div class=\"service__media\"><img src=\"/image/editor-image/online-learning.png\" alt=\"\" style=\"float: none; margin: 0px; width: 50px; height: 39px;\" /> </div>                            \r\n						<div class=\"service__content\">                                \r\n							<h3>Empezar a enseñar</h3>                                \r\n							<p><span style=\"font-family: Georgia; font-size: 16px; white-space: pre-wrap;\">Acepte solicitudes de sesión y comience a tomar clases en línea.</span></p>                            </div>                        </div>                    </div>                </div>            </div>        </div>    </div>   '),
(9, 1, 'Apply to teach static banner section', '\r\n<section class=\"section section--cta\" style=\"background-image:url(image/editor-image/1650429510-background.png);\">        \r\n	<div class=\"container container--narrow\">            \r\n		<div class=\"cta-content\">                \r\n			<h2 class=\"margin-bottom-5\">Do you want to become a teacher on w3mentors?</h2>                \r\n			<p class=\"margin-bottom-5\">Connect with thousands of learners around the world and teach from your living room</p>                <a class=\"btn btn--secondary btn--large applytoteach\">Apply Now</a>            </div>        </div>    </section>'),
(9, 2, 'التقديم لتدريس قسم البانر الثابت', '\r\n<section class=\"section section--cta\" style=\"background-image:url(image/editor-image/1650429510-background.png);\">      \r\n	<div class=\"container container--narrow\">            \r\n		<div class=\"cta-content\">                \r\n			<h2 class=\"margin-bottom-5\">هل تريد أن تصبح مدرسا على Yo! مدرب؟</h2>                \r\n			<p class=\"margin-bottom-5\">تواصل مع الآلاف من المتعلمين حول العالم وقم بالتدريس من غرفة المعيشة الخاصة بك</p>                <a class=\"btn btn--secondary btn--large applytoteach\">قدم الآن</a>            </div>        </div>    </section>'),
(9, 3, 'Aplicar para enseñar la sección de banner estático', '\r\n<section class=\"section section--cta\" style=\"background-image:url(image/editor-image/1650429510-background.png);\">        \r\n	<div class=\"container container--narrow\">            \r\n		<div class=\"cta-content\">                \r\n			<h2 class=\"margin-bottom-5\">¿Quieres convertirte en profesor en Yo! ¿Coche?</h2>                \r\n			<p class=\"margin-bottom-5\">Con&eacute;ctese con miles de estudiantes de todo el mundo y enseñe desde su sala de estar</p>                <a class=\"btn btn--secondary btn--large applytoteach\">Aplicar ahora</a>            </div>        </div>    </section>'),
