(22, 1, 'Creating a Community', '\r\n<section class=\"section\">            \r\n	<div class=\"container container--xxl\">                \r\n		<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n			<h2>Creating A Community Of Life Long Learners.</h2>                </div>                \r\n		<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n			<div class=\"stats-wrapper\">                        \r\n				<div class=\"stats-listing\">                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"500\">0</span><i>+</i></span>                                <span class=\"stats__label\">Learners &amp; counting</span>                            </div>                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"800\">0</span><i>+</i></span>                                <span class=\"stats__label\">Courses & Videos</span>                            </div>                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"1000\">0</span><i>+</i></span>                                <span class=\"stats__label\">Certified Students</span>                            </div>                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"100\">0</span><i>+</i></span>                                <span class=\"stats__label\">Registered Enrolls</span>                            </div>                        </div>                    </div>                </div>            </div></section>'),
