(24, 1, 'Join Now', '\r\n<section class=\"section\">    \r\n	<div class=\"container container--xxl\">        \r\n		<div class=\"grid-layout\" data-aos=\"fade-up\" data-aos-duration=\"1000\">            \r\n			<div class=\"grid-layout__item\">                \r\n				<div class=\"cta-card\">                    \r\n                  \r\n					<div class=\"cta-card__media\">                        <img src=\"/image/editor-image/cta__student-img.png\" alt=\"\" />                    </div>                    \r\n					<div class=\"cta-card__content\">                        \r\n						<h2>Join now to start learning</h2>                        \r\n						<p>Learn from our quality instructors!</p>                        <a href=\"guest-user/register-form\" class=\"btn btn--primary btn--large\">Get Started</a>                    </div>                </div>            </div>            \r\n			<div class=\"grid-layout__item\">                \r\n				<div class=\"cta-card\">                    \r\n					<div class=\"cta-card__media\">                        <img src=\"/image/editor-image/cta__student-img-2.png\" alt=\"\" />                    </div>                    \r\n					<div class=\"cta-card__content\">                        \r\n						<h2>Become a new instructor</h2>                        \r\n						<p>Teach thousands of students and earn money!</p>                        <a href=\"teacher-request\" class=\"btn btn--primary btn--large\">Get Started</a>                    </div>                </div>            </div>        </div>    </div></section>'),
(24, 2, 'اشترك الآن', '\r\n<section class=\"section\">    \r\n	<div class=\"container container--xxl\">        \r\n		<div class=\"grid-layout\" data-aos=\"fade-up\" data-aos-duration=\"1000\">            \r\n			<div class=\"grid-layout__item\">                \r\n				<div class=\"cta-card\">                    \r\n                  \r\n					<div class=\"cta-card__media\">                        <img src=\"/image/editor-image/cta__student-img.png\" alt=\"\" />                    </div>                    \r\n					<div class=\"cta-card__content\">                        \r\n						<h2>انضم الآن لبدء التعلم</h2>                        \r\n						<p>تعلم من مدربينا ذوي الجودة!</p>                        <a href=\"guest-user/register-form\" class=\"btn btn--primary btn--large\">ابدأ الآن</a>                    </div>                </div>            </div>            \r\n			<div class=\"grid-layout__item\">                \r\n				<div class=\"cta-card\">                    \r\n					<div class=\"cta-card__media\">                        <img src=\"/image/editor-image/cta__student-img-2.png\" alt=\"\" />                    </div>                    \r\n					<div class=\"cta-card__content\">                        \r\n						<h2>كن مدربا جديدا</h2>                        \r\n						<p>علم آلاف الطلاب واكسب المال!</p>                        <a href=\"teacher-request\" class=\"btn btn--primary btn--large\">ابدأ الآن</a>                    </div>                </div>            </div>        </div>    </div></section>'),
(24, 3, 'Únete ahora', '\r\n<section class=\"section\">    \r\n	<div class=\"container container--xxl\">        \r\n		<div class=\"grid-layout\" data-aos=\"fade-up\" data-aos-duration=\"1000\">            \r\n			<div class=\"grid-layout__item\">                \r\n				<div class=\"cta-card\">                    \r\n                  \r\n					<div class=\"cta-card__media\">                        <img src=\"/image/editor-image/cta__student-img.png\" alt=\"\" />                    </div>                    \r\n					<div class=\"cta-card__content\">                        \r\n						<h2>Únete ahora para empezar a aprender</h2>                        \r\n						<p>¡Aprende de nuestros instructores de calidad!</p>                        <a href=\"guest-user/register-form\" class=\"btn btn--primary btn--large\">Comenzar</a>                    </div>                </div>            </div>            \r\n			<div class=\"grid-layout__item\">                \r\n				<div class=\"cta-card\">                    \r\n					<div class=\"cta-card__media\">                        <img src=\"/image/editor-image/cta__student-img-2.png\" alt=\"\" />                    </div>                    \r\n					<div class=\"cta-card__content\">                        \r\n						<h2>Conviértete en un nuevo instructor</h2>                        \r\n						<p>¡Enseña a miles de estudiantes y gana dinero!</p>                        <a href=\"teacher-request\" class=\"btn btn--primary btn--large\">Comenzar</a>                    </div>                </div>            </div>        </div>    </div></section>'),
(25, 1, 'Subscription Plans', ''),
(25, 2, 'خطط الاشتراك', ''),
(25, 3, 'Planes de suscripción', '');
INSERT INTO `tbl_language_labels` (`label_id`, `label_lang_id`, `label_key`, `label_caption`) VALUES
(null, 1, 'LBL_NEWSLETTER_DESCRITPTION', 'Subscribe, and get in touch with us'), 
(null, 2, 'LBL_NEWSLETTER_DESCRITPTION', 'اشترك وتواصل معنا'),
(null, 3, 'LBL_NEWSLETTER_DESCRITPTION', 'Suscríbete y ponte en contacto con nosotros');
INSERT INTO `tbl_pages_data` (`pdata_id`, `pdata_key`, `pdata_helping_text`) VALUES
(null, 'wallet-balance-report', '<ul>        \r\n	<li>This report shows remaining wallet balance of all the users along with their user type.</li> \r\n	<li> Export this report in the form of a CSV (Comma Separated Value) file. This file can be used to maintain a backup or use the related data outside the platform.</li>        \r\n	<li> Perform an easy search using different search filters provided on this page.</li>\r\n</ul> '),
(null, 'payouts-report', '<ul>        \r\n	<li>This report highlights the amounts already disbursed as payouts.</li>        \r\n	<li> Export this report in the form of a CSV (Comma Separated Value) file. This file can be used to maintain a backup or use the related data outside the platform.</li>        \r\n	<li> Perform an easy search using different search filters provided on this page.</li>\r\n</ul> '),
(null, 'hours-taught-report', '<ul>        \r\n	<li>The report outlines the total hours taught by teachers, with categorization of lesson hours and class hours.</li>\r\n	<li>Click Regenerate to refresh the report and display the latest data.</li>        \r\n	<li> Export this report in the form of a CSV (Comma Separated Value) file. This file can be used to maintain a backup or use the related data outside the platform.</li>        \r\n	<li> Perform an easy search using different search filters provided on this page.</li>\r\n</ul> ');
INSERT INTO `tbl_pages_language_data` (`plang_id`, `plang_key`, `plang_lang_id`, `plang_title`, `plang_summary`, `plang_warring_msg`, `plang_recommendations`, `plang_replacements`, `plang_helping_text`) VALUES
(null, 'payouts-report', 1, 'Payouts report', 'Statistics related to amounts paid to the users.', '', '', '', '\r\n<ul>        \r\n	<li>This report highlights the amounts already disbursed as payouts.</li>        \r\n	<li> Export this report in the form of a CSV (Comma Separated Value) file. This file can be used to maintain a backup or use the related data outside the platform.</li>        \r\n	<li> Perform an easy search using different search filters provided on this page.</li>\r\n</ul> '),
(null, 'payouts-report', 2, 'تقرير المدفوعات', 'الإحصائيات المتعلقة بالمبالغ المدفوعة للمستخدمين.', '', '', '', '\r\n<ul>        \r\n	<li>يسلط هذا التقرير الضوء على المبالغ التي تم صرفها بالفعل كمدفوعات.</li>        \r\n	<li> قم بتصدير هذا التقرير في شكل ملف CSV (قيمة مفصولة بفواصل). يمكن استخدام هذا الملف للاحتفاظ بنسخة احتياطية أو استخدام البيانات ذات الصلة خارج النظام الأساسي.</li>        \r\n	<li> قم بإجراء بحث سهل باستخدام عوامل تصفية البحث المختلفة المتوفرة في هذه الصفحة.</li>\r\n</ul> '),
(null, 'payouts-report', 3, 'Informe de pagos', 'Estadísticas relacionadas con los importes pagados a los usuarios.', '', '', '', '\r\n<ul>        \r\n	<li>Este informe destaca los montos ya desembolsados como pagos.</li>        \r\n	<li> Exporte este informe en forma de archivo CSV (valores separados por comas). Este archivo se puede utilizar para mantener una copia de seguridad o utilizar los datos relacionados fuera de la plataforma.</li>        \r\n	<li> Realice una búsqueda sencilla utilizando los diferentes filtros de búsqueda que se proporcionan en esta página.</li>\r\n</ul> ');
INSERT INTO `tbl_pages_language_data` (`plang_id`, `plang_key`, `plang_lang_id`, `plang_title`, `plang_summary`, `plang_warring_msg`, `plang_recommendations`, `plang_replacements`, `plang_helping_text`) VALUES
(null, 'wallet-balance-report', 1, 'Wallet balance report', 'Statistics regarding the pending amounts in all user wallets.', '', '', '', '\r\n<ul>        \r\n	<li>This report shows remaining wallet balance of all the users along with their user type.</li> \r\n	<li> Export this report in the form of a CSV (Comma Separated Value) file. This file can be used to maintain a backup or use the related data outside the platform.</li>        \r\n	<li> Perform an easy search using different search filters provided on this page.</li>\r\n</ul> '),
(null, 'wallet-balance-report', 2, 'تقرير رصيد المحفظة', 'إحصائيات بخصوص المبالغ المعلقة في جميع محافظ المستخدمين.', '', '', '', '\r\n<ul>        \r\n	<li>يعرض هذا التقرير رصيد المحفظة المتبقي لجميع المستخدمين بالإضافة إلى نوع المستخدم الخاص بهم.</li> \r\n	<li> قم بتصدير هذا التقرير في شكل ملف CSV (قيمة مفصولة بفواصل). يمكن استخدام هذا الملف للاحتفاظ بنسخة احتياطية أو استخدام البيانات ذات الصلة خارج النظام الأساسي.</li>        \r\n	<li> قم بإجراء بحث سهل باستخدام عوامل تصفية البحث المختلفة المتوفرة في هذه الصفحة.</li>\r\n</ul> '),
(null, 'wallet-balance-report', 3, 'Informe de saldo de la billetera', 'Estadísticas sobre los montos pendientes en todas las billeteras de los usuarios.', '', '', '', '\r\n<ul>        \r\n	<li>Este informe muestra el saldo restante de la billetera de todos los usuarios junto con su tipo de usuario.</li> \r\n	<li> Exporte este informe en forma de archivo CSV (valores separados por comas). Este archivo se puede utilizar para mantener una copia de seguridad o utilizar los datos relacionados fuera de la plataforma.</li>        \r\n	<li> Realice una búsqueda sencilla utilizando los diferentes filtros de búsqueda que se proporcionan en esta página.</li>\r\n</ul> ');
INSERT INTO `tbl_pages_language_data` (`plang_id`, `plang_key`, `plang_lang_id`, `plang_title`, `plang_summary`, `plang_warring_msg`, `plang_recommendations`, `plang_replacements`, `plang_helping_text`) VALUES
(null, 'hours-taught-report', 1, 'Hours taught report', 'Stats related to the hours taught by the teachers.', '', '', '', '\r\n<ul>        \r\n	<li>The report outlines the total hours taught by teachers, with categorization of lesson hours and class hours.</li>\r\n	<li>Click Regenerate to refresh the report and display the latest data.</li>        \r\n	<li> Export this report in the form of a CSV (Comma Separated Value) file. This file can be used to maintain a backup or use the related data outside the platform.</li>        \r\n	<li> Perform an easy search using different search filters provided on this page.</li>\r\n</ul> '),
(null, 'hours-taught-report', 2, 'تقرير الساعات التي تدرس', 'الإحصائيات المتعلقة بساعات التدريس من قبل المعلمين.', '', '', '', '\r\n<ul>        \r\n	<li>يحدد التقرير إجمالي ساعات التدريس من قبل المعلمين ، مع تصنيف ساعات الدرس وساعات الفصل.</li>\r\n	<li>انقر فوق إعادة إنشاء لتحديث التقرير وعرض أحدث البيانات.</li>        \r\n	<li> قم بتصدير هذا التقرير في شكل ملف CSV (قيمة مفصولة بفواصل). يمكن استخدام هذا الملف للاحتفاظ بنسخة احتياطية أو استخدام البيانات ذات الصلة خارج النظام الأساسي.</li>        \r\n	<li> قم بإجراء بحث سهل باستخدام عوامل تصفية البحث المختلفة المتوفرة في هذه الصفحة.</li>\r\n</ul> '),
(null, 'hours-taught-report', 3, 'Reporte de horas impartidas', 'Estadísticas relacionadas con las horas impartidas por los profesores.', '', '', '', '\r\n<ul>        \r\n	<li>El informe describe el total de horas impartidas por los maestros, con una categorización de las horas de lección y las horas de clase.</li>\r\n	<li>Haga clic en Regenerar para actualizar el informe y mostrar los datos más recientes.</li>        \r\n	<li> Exporte este informe en forma de archivo CSV (valores separados por comas). Este archivo se puede utilizar para mantener una copia de seguridad o utilizar los datos relacionados fuera de la plataforma.</li>        \r\n	<li> Realice una búsqueda sencilla utilizando los diferentes filtros de búsqueda que se proporcionan en esta página.</li>\r\n</ul> ');
INSERT INTO `tbl_language_labels` (`label_id`, `label_lang_id`, `label_key`, `label_caption`) VALUES 
(NULL, '1', 'htmlAfterField_COURSE_EDIT_EMAILS_SETTING_TEXT', 'Setting to enable/disable sending emails to users when the course editing is finalized either by the teacher or by the system automatically.'),
(NULL, '2', 'htmlAfterField_COURSE_EDIT_EMAILS_SETTING_TEXT', 'إعداد لتمكين/تعطيل إرسال الرسائل الإلكترونية إلى المستخدمين عند الانتهاء من تعديل الدورة إما من قبل المعلم أو تلقائيًا بواسطة النظام.'), (NULL, '3', 'htmlAfterField_COURSE_EDIT_EMAILS_SETTING_TEXT', 'Configuración para habilitar/deshabilitar el envío de correos electrónicos a los usuarios cuando se finaliza la edición del curso, ya sea por el profesor o automáticamente por el sistema.');
