(null, 2, 1, 1, '\n<div class=\"section\">\n	<div class=\"row justify-content-between align-items-xl-center g-5\">\n		<div class=\"col-md-6\">\n			<div class=\"cms-media\" data-aos=\"fade-up\" data-aos-duration=\"1000\"><img src=\"/image/editor-image/about-whoweare.png\" alt=\"\" /></div></div>\n		<div class=\"col-md-6 col-xl-5\">\n			<div class=\"cms\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n				<h4 class=\"mb-3\">يبدأ بمن نحن.</h4>\n				<h2 class=\"mb-3\">نبني منظمة لمساعدة الناس على التعلم عبر الإنترنت.</h2>\n				<p>المنصة عبارة عن حل مستضاف ذاتيا يساعد رواد الأعمال على إطلاق منصات للدروس الخصوصية والاستشارات عبر الإنترنت حيث يمكن للعديد من المعلمين أو الاستشاريين التسجيل وتقديم جلسات فردية أو جماعية عبر الإنترنت للمتعلمين. إنه حل قابل للتطوير بدرجة كبيرة وقابل للتخصيص بالكامل لتلبية متطلبات العمل للمستخدمين. تم دمج الحل مسبقا مع Cometchat و Lesson Space و Zoom لدعم ميزات مثل دردشة الفيديو ، والسبورة البيضاء ، ولوحة النص ، ومحرر التعليمات البرمجية ، ومشاركة الشاشات المتعددة ، وما إلى ذلك مما يحسن التفاعل بين المعلم والمتعلم أثناء الجلسة عبر الإنترنت.</p></div></div></div></div>\n<div class=\"section\">   \n	<div class=\"why-panel\">\n		<div class=\"section__header text-start\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n			<h4>لماذا أخترتنا</h4>\n			<h2>التعلم والتحسين دائما من أجل خلق عالم أفضل للأجيال القادمة.</h2></div>\n		<div class=\"section__body\">\n			<div class=\"counters-list pt-4\">\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-1.png\" alt=\"\" /></div><span class=\"counter-card__value\">130 +</span> <span class=\"counter-card__label\">لغة متاحة للتعلم</span></div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-2.png\" alt=\"\" /></div><span class=\"counter-card__value\">10 آلاف +</span> <span class=\"counter-card__label\">معلمين من 120 دولة</span></div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-3.png\" alt=\"\" /></div><span class=\"counter-card__value\">5 ملايين +</span> <span class=\"counter-card__label\">متعلم من 180 دولة</span></div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-4.png\" alt=\"\" /></div><span class=\"counter-card__value\">5 ملايين +</span> <span class=\"counter-card__label\">متعلم من 180 دولة</span></div></div></div></div></div>\n<div class=\"section section--testimonials\">   \n	<div class=\"section__header text-start px-4\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"row align-items-center justify-content-between\">\n			<div class=\"col-xl-8\">\n				<h4>قيمنا الأساسية</h4>\n				<h2>نحن نحب العملاء الذين يفهمون قيمنا</h2></div>\n			<div class=\"col-xl-auto\">\n				<div class=\"slider-nav\">\n					<button type=\"button\" class=\"prev-slide slick-arrow\"></button>\n					<button type=\"button\" class=\"next-slide slick-arrow\"></button>\n				</div>\n			</div>\n		</div></div>\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"client-testimonials-list js--testimonials\">\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">01</span>كلمات التقدير</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>كان كل حل يستغرق الكثير من الوقت، بما لا يقل عن 6 إلى 8 أشهر، وكان ذلك وقتًا لم يكن لدينا. وذلك عندما وجد ويل منصة FATbit. لقد استكشفنا رؤيتنا حول ما يجب أن تقدمه المنصة، ولدهشتنا، أنها تناسب تمامًا ما كان يدور في ذهننا، وكان لدينا عرض توضيحي مباشر للمنصة. لقد اغتنمنا الفرصة لإيجاد حل لتنفيذ رؤيتنا، ولم نأسف لذلك على الإطلاق. حتى الآن، كان الأمر جيدًا بالنسبة للفريق.</p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">السيد تشين وي سيونغ</h6></div></div>\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">02</span>كلمات تقدير</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>نحن نمتلك امتيازًا لمدرسة اللغات في الموقع الفعلي. بمجرد حدوث الإغلاق بسبب فيروس كورونا (COVID-19)، كنا بحاجة إلى الانتقال إلى الإنترنت. توفر المنصة منصة حديثة للغاية بالنسبة لنا ليس فقط لتعلم اللغة ولكن لجميع أنواع التعلم. </p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">راي د أنجيلو</h6></div></div>\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">03</span>كلمات تقدير</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>لقد كانت رحلتي مع FATbit طويلة. لقد استغرق الأمر ساعات وصبرًا لإنجاز موقع الويب وفقًا للتوقعات الدقيقة التي طلبتها. FATbit لا يستسلم أبدًا، فهو دائمًا يقدم ما يقوله بغض النظر عن مقدار الوقت الإضافي الذي ينفقه على المشروع والعملاء. المطور الخاص بي إيدي، جهة اتصال المبيعات الخاصة بي، Kesa، بذلت قصارى جهدها للبقاء على رأس هذا المشروع. النتيجة النهائية؛ موقع جميل وفعال وسيغير الطريقة العالمية لتعلم لغة جديدة. شكرا لك فاتبيت.</p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">كيلي</h6></div></div>\n<div class=\"client-testimonail\">\n							<div class=\"client-testimonail__head\">\n								<h4><span class=\"num\">04</span>كلمات تقدير</h4></div>\n							<div class=\"client-testimonail__body\">\n								<p>أنا أستخدم لوحة التحكم في منصة W3mentors دون أي تعقيدات ويمكن لعملائي استخدام منصتي بطريقة سهلة.</p></div>\n							<div class=\"client-testimonail__foot\">\n								<h6 class=\"client-info\">ياسين الطيبي</h6></div></div\n			</div></div></div>\n<div class=\"section\">\n	<div class=\"grey-wrapper\">\n		<div class=\"section__header text-start\">\n			<div class=\"row align-items-center justify-content-between gap-3\">\n				<div class=\"col-xl-8\">\n					<h4>مهمتنا ورؤيتنا</h4>\n					<h2>تعرف على مهمتنا ورؤيتنا</h2></div>\n				<div class=\"col-xl-auto\"><a href=\"/contact\" class=\"btn btn--primary btn--large\">اتصل بنا</a></div></div></div>\n		<div class=\"section__body\">\n			<div class=\"accordion width\" id=\"hrAccordion\">\n				<div class=\"card\">\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseOne\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">مهمتنا</span></div>\n					<div id=\"collapseOne\" class=\"collapse show width\" data-parent=\"#hrAccordion\">\n						<div class=\"card-body\">\n							<div class=\"cms-panel\">\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\n								<div class=\"cms-panel__content\">\n									<h2>هدفنا</h2>\n									<p>مهمتنا هي مساعدة رواد الأعمال والمدرسين على إنشاء منصات التدريس الخاصة بهم عبر الإنترنت مثل Verbling وPreply وCambly. نحن نساعدهم على الوصول إلى قمة حياتهم المهنية من خلال تمكينهم من إطلاق منصة التدريس الخاصة بهم باستخدام حلنا الجاهز.</p></div></div></div></div></div>\n				<div class=\"card\">\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseTwo\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">إلهامنا ومراقبتنا</span></div>\n					<div id=\"collapseTwo\" class=\"collapse width\" data-parent=\"#hrAccordion\">\n						<div class=\"card-body\">\n							<div class=\"cms-panel\">\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\n								<div class=\"cms-panel__content\">\n									<h2>هدفنا</h2>\n									<p>نحن، كقادة وخبراء في الصناعة، نقدم حل تكنولوجيا التعليم الجاهز لمساعدة رواد الأعمال على بدء أعمالهم التعليمية. هدفنا هو تقديم عملية سهلة وخالية من المتاعب لهم لدخول السوق ويصبحوا روادًا.</p></div></div></div></div></div>\n				<div class=\"card\">\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseThree\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">هدفنا</span></div>\n					<div id=\"collapseThree\" class=\"collapse width\" data-parent=\"#hrAccordion\">\n						<div class=\"card-body\">\n							<div class=\"cms-panel\">\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\n								<div class=\"cms-panel__content\">\n									<h2>هدفنا</h2>\n									<p>Nam libero tempore, cum soluta nobis est eligendi optio cumque nihil impedit quo minus id quod maxime placeat facere possimus, omnis voluptas assumenda est, omnis dolor repellendus Temporibus autem.</p></div></div></div></div></div></div></div></div></div>\n<div class=\"section\">\n	<div class=\"section__header d-flex gap-5 text-start\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"row justify-content-between pb-4 g-3\">\n			<div class=\"col-xl-3\">\n				<h6>شعب</h6>\n				<h2>تعرف على فريق الخبراء لدينا</h2></div>\n			<div class=\"col-xl-8\">\n				<p class=\"p-xlarge m-0\">يتمتع أعضاء فريقنا ذوي المعرفة والخبرة العالية بطبيعة إبداعية وتعاونية وملتزمة تمكن المنصة من أن تكون شركة فعالة للغاية.</p></div></div></div>\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"teacher-wrapper\">\n			<div class=\"slider slider-onefifth slider-onefifth-js\">\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349417-ceo364x364.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>ستيفن فليمنج</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">الرئيس التنفيذي والمؤسس</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349567-marketinghead364x3641.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>جيمس أندرسون</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">رئيس المبيعات/التسويق</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349739-creativedirector364x3642.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>ناثان أستل</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">المدير الإبداعي</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349751-techlead364x3643.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>مارك باوتشر</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">الرصاص الفني</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349756-saleshead364x3644.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>ستيف وو</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">رئيس المبيعات/التسويق</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349761-creativedirector2364x3645.jpg\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>داميان مارتن</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">المدير الإبداعي </span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div></div></div></div>\n	<div class=\"section__footer text-center pt-0\" data-aos=\"fade-up\" data-aos-duration=\"1000\"><a href=\"#\" class=\"text-button\">استكشاف جميع المعلمين <span class=\"circle-arrow\"></span></a></div></div>\n<div class=\"section section--HowItWorks\">\n	<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<h2>كيف تبدأ التعلم مع المنصة؟</h2></div>\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<nav class=\"inline-tabs\">\n			<ul class=\"js-tab list-unstyled\">\n				<li><a href=\"#tab__1\" class=\"current\">01. البحث</a></li>\n				<li><a href=\"#tab__2\" class=\"\">02. كتاب  </a> </li>\n				<li><a href=\"#tab__3\" class=\"\">03. تعلم   </a> </li>\n			</ul></nav>\n		<div class=\"flex-layout-wrapper\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n			<div class=\"tab-container visible\" id=\"tab__1\">\n				<div class=\"flex-layout\">\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/choose-your-tutor.png\" alt=\"\" /></div>\n					<div class=\"flex-layout__content\">\n						<div class=\"content\">\n							<h2>ابحث في مئات من أفضل المعلمين</h2>\n							<p class=\"p-large\">استخدم عوامل تصفية مثل السعر واللغة والكفاءة والموضوع والموقع للبحث عن معلمك المفضل</p>\n							<div class=\"step__actions\"> <a href=\"/teachers#\" class=\"btn btn--primary\" tabindex=\"0\">تصفح المدرسين</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\n									<svg class=\"icon icon--play\">                                 \n										<use xlink:href=\"/images/sprite.svg#play\"></use>                                                    </svg>&nbsp;شاهد الفيديو</a>                                            </div></div></div></div></div>\n			<div class=\"tab-container\" id=\"tab__2\">\n				<div class=\"flex-layout\">\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/become-an-expert.png\" alt=\"\" /></div>\n					<div class=\"flex-layout__content\">\n						<div class=\"content\">\n							<h2>احجز الدروس مع أفضل معلم لك</h2>\n							<p class=\"p-large\">انتقل من خلال ملف تعريف المعلم وحجز درس بعد إجراء الدفع.</p>\n							<div class=\"step__actions\"> <a href=\"/teachers#\" class=\"btn btn--primary\" tabindex=\"0\">تصفح المدرسين</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\n									<svg class=\"icon icon--play\">                                                        \n										<use xlink:href=\"/images/sprite.svg#play\"></use>                                                    </svg>&nbsp;شاهد الفيديو</a>                                            </div></div></div></div></div>\n			<div class=\"tab-container\" id=\"tab__3\">\n				<div class=\"flex-layout\">\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/book-your-free-lesson.png\" alt=\"\" /></div>\n					<div class=\"flex-layout__content\">\n						<div class=\"content\">\n							<h2>تسجيل الدخول لبدء التعلم</h2>\n							<p class=\"p-large\">حضور الدروس عبر الإنترنت والبدء في التعلم.</p>\n							<div class=\"step__actions\"> <a href=\"/teachers#\" class=\"btn btn--primary\" tabindex=\"0\">تصفح المدرسين</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\n									<svg class=\"icon icon--play\">                                                        \n										<use xlink:href=\"/images/sprite.svg#play\"></use>                                                    </svg>&nbsp;شاهد الفيديو</a>                                            </div></div></div></div></div></div></div></div>'),
(null, 2, 1, 2, '');
INSERT INTO `tbl_content_pages_block_lang` (`cpblocklang_id`, `cpblocklang_lang_id`, `cpblocklang_cpage_id`, `cpblocklang_block_id`, `cpblocklang_text`) VALUES
(null, 3, 1, 1, '\n<div class=\"section\">\n	<div class=\"row justify-content-between align-items-xl-center g-5\">\n		<div class=\"col-md-6\">\n			<div class=\"cms-media\" data-aos=\"fade-up\" data-aos-duration=\"1000\"><img src=\"/image/editor-image/about-whoweare.png\" alt=\"\" /></div></div>\n		<div class=\"col-md-6 col-xl-5\">\n			<div class=\"cms\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n				<h4 class=\"mb-3\">Comienza con Qui&eacute;nes Somos.</h4>\n				<h2 class=\"mb-3\">Construimos una organización para ayudar a las personas a aprender en línea.</h2>\n				<p>Platform es una solución autoalojada que ayuda a los emprendedores a lanzar plataformas de tutoría y consulta en línea donde varios tutores o consultores pueden registrarse y ofrecer sesiones en línea individuales o grupales a los estudiantes. Es una solución altamente escalable y totalmente personalizable para cumplir con los requisitos comerciales de los usuarios. La solución está preintegrada con Cometchat, Lesson Space y Zoom para admitir funciones como chat de video, pizarra, teclado de texto, editor de código, uso compartido de múltiples pantallas, etc., lo que mejora la interacción entre el tutor y el alumno durante una sesión en línea.</p></div></div></div></div>\n<div class=\"section\">   \n	<div class=\"why-panel\">\n		<div class=\"section__header text-start\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n			<h4>¿Por qu&eacute; elegirnos?</h4>\n			<h2>Aprender y mejorar siempre para crear un mundo mejor para las generaciones venideras.</h2></div>\n		<div class=\"section__body\">\n			<div class=\"counters-list pt-4\">\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-1.png\" alt=\"\" /></div><span class=\"counter-card__value\">130 +</span><span class=\"counter-card__label\">Idiomas disponibles para aprender</span></div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-2.png\" alt=\"\" /></div><span class=\"counter-card__value\">10k +</span><span class=\"counter-card__label\">Profesores de 120 países</span></div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-3.png\" alt=\"\" /></div><span class=\"counter-card__value\">5M +</span><span class=\"counter-card__label\">Aprendices de 180 países</span></div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-4.png\" alt=\"\" /></div><span class=\"counter-card__value\">5M +</span><span class=\"counter-card__label\">Aprendices de 180 países</span></div></div></div></div></div>\n<div class=\"section section--testimonials\">   \n	<div class=\"section__header text-start px-4\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"row align-items-center justify-content-between\">\n			<div class=\"col-xl-8\">\n				<h4>Nuestros Valores Fundamentales</h4>\n				<h2>Nos encantan los clientes que entienden nuestros valores</h2></div>\n			<div class=\"col-xl-auto\">\n				<div class=\"slider-nav\">\n					<button type=\"button\" class=\"prev-slide slick-arrow\"></button>\n					<button type=\"button\" class=\"next-slide slick-arrow\"></button>\n				</div>\n			</div>\n		</div></div>\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"client-testimonials-list js--testimonials\">\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">01</span>Palabras de agradecimiento</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>Cada solución estaba tomando demasiado tiempo, nada menos que 6 a 8 meses, y era tiempo que no teníamos. Fue entonces cuando Wale encontró la plataforma FATbit. Exploramos nuestra visión sobre lo que Platform tenía para ofrecer y, para nuestra sorpresa, encajaba exactamente con lo que teníamos en mente y tuvimos una demostración en vivo de Platform. Aprovechamos la oportunidad de encontrar una solución para ejecutar nuestra visión y no nos hemos arrepentido en absoluto. Hasta ahora, ha sido bueno para el equipo.</p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">Sr. Chin Wei Seong</h6></div></div>\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">02</span>Palabras de agradecimiento</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>Somos una franquicia de escuelas de idiomas con ubicación física física. Una vez que se produjo el cierre de COVID-19, necesitábamos pasar a estar en línea. Platform proporciona una plataforma muy moderna para que podamos ejecutar no solo el aprendizaje de idiomas sino todo tipo de aprendizaje. </p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">Ray D Angelo</h6></div></div>\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">03</span>Palabras de agradecimiento</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>Mi viaje con FATbit ha sido largo. Me tomó horas y paciencia lograr que el sitio web cumpliera con las expectativas exactas que pedí. FATbit nunca se rinde, siempre cumplen lo que dicen sin importar cuántas horas extras dediquen al proyecto y al cliente. Mi desarrollador Eddie y mi contacto de ventas, Kesa, hicieron todo lo posible para mantenerse al tanto de este proyecto. Resultado final; Un sitio hermoso y poderosamente funcional que cambiará la forma en que el mundo aprende un nuevo idioma. Gracias FATbit.</p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">Kelly</h6></div></div>\n                        <div class=\"client-testimonail\">\n							<div class=\"client-testimonail__head\">\n								<h4><span class=\"num\">04</span>Palabras de agradecimiento</h4></div>\n							<div class=\"client-testimonail__body\">\n								<p>Estoy usando el panel de control de la plataforma W3mentors sin ninguna complicación y mis clientes pueden usar mi plataforma de manera sencilla.</p></div>\n							<div class=\"client-testimonail__foot\">\n								<h6 class=\"client-info\">Yacine Tayebi</h6></div></div>\n			</div></div></div>\n<div class=\"section\">\n	<div class=\"grey-wrapper\">\n		<div class=\"section__header text-start\">\n			<div class=\"row align-items-center justify-content-between gap-3\">\n				<div class=\"col-xl-8\">\n					<h4>Nuestra misión y visión</h4>\n					<h2>Conozca nuestra misión y visión</h2></div>\n				<div class=\"col-xl-auto\"><a href=\"/contact\" class=\"btn btn--primary btn--large\">Contáctenos</a></div></div></div>\n		<div class=\"section__body\">\n			<div class=\"accordion width\" id=\"hrAccordion\">\n				<div class=\"card\">\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseOne\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">NUESTRA MISIÓN</span></div>\n					<div id=\"collapseOne\" class=\"collapse show width\" data-parent=\"#hrAccordion\">\n						<div class=\"card-body\">\n							<div class=\"cms-panel\">\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\n								<div class=\"cms-panel__content\">\n									<h2>Nuestro objetivo</h2>\n									<p>Nuestra misión es ayudar a emprendedores y tutores a configurar sus propias plataformas de tutoría en línea como Verbling, Preply y Cambly. Les ayudamos a alcanzar la cima de su carrera permitiéndoles lanzar su propia plataforma de tutoría utilizando nuestra solución lista para usar.</p></div></div></div></div></div>\n				<div class=\"card\">\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseTwo\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">Nuestra Inspiración &amp; Visión</span></div>\n					<div id=\"collapseTwo\" class=\"collapse width\" data-parent=\"#hrAccordion\">\n						<div class=\"card-body\">\n							<div class=\"cms-panel\">\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\n								<div class=\"cms-panel__content\">\n									<h2>Nuestro objetivo</h2>\n									<p>Nosotros, como líderes y expertos de la industria, brindamos nuestra solución de tecnología educativa llave en mano para ayudar a los emprendedores a iniciar sus negocios de tutoría. Nuestro objetivo es ofrecerles un proceso fácil y sin complicaciones para ingresar al mercado y convertirse en pioneros.</p></div></div></div></div></div>\n				<div class=\"card\">\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseThree\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">Nuestro objetivo</span></div>\n					<div id=\"collapseThree\" class=\"collapse width\" data-parent=\"#hrAccordion\">\n						<div class=\"card-body\">\n							<div class=\"cms-panel\">\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\n								<div class=\"cms-panel__content\">\n									<h2>Nuestro objetivo</h2>\n									<p>Nam libero tempore, cum soluta nobis est eligendi optio cumque nihil impedit quo minus id quod maxime placeat facere possimus, omnis voluptas assumenda est, omnis dolor repellendus Temporibus autem.</p></div></div></div></div></div></div></div></div></div>\n<div class=\"section\">\n	<div class=\"section__header d-flex gap-5 text-start\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"row justify-content-between pb-4 g-3\">\n			<div class=\"col-xl-3\">\n				<h6>Gente</h6>\n				<h2>Conozca a nuestro equipo de expertos</h2></div>\n			<div class=\"col-xl-8\">\n				<p class=\"p-xlarge m-0\">Los miembros de nuestro equipo altamente informados y experimentados tienen una naturaleza creativa, colaborativa y comprometida que permite a Platform ser una empresa altamente efectiva.</p></div></div></div>\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"teacher-wrapper\">\n			<div class=\"slider slider-onefifth slider-onefifth-js\">\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349417-ceo364x364.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>Esteban Fleming</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">CEO y fundador</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349567-marketinghead364x3641.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>James Anderson</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">Jefe de Ventas / Marketing</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349739-creativedirector364x3642.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>Nathan Astle</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">Director creativo</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349751-techlead364x3643.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>Marcos Boucher</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">Líder tecnológico </span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349756-saleshead364x3644.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>Steve Waugh</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">Jefe de Ventas / Marketing</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349761-creativedirector2364x3645.jpg\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>Damián Martín</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">Director creativo </span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div></div></div></div>\n	<div class=\"section__footer text-center pt-0\" data-aos=\"fade-up\" data-aos-duration=\"1000\"><a href=\"#\" class=\"text-button\">Explora todos los tutores <span class=\"circle-arrow\"></span></a></div></div>\n<div class=\"section section--HowItWorks\">\n	<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<h2>¿Cómo empezar a aprender con Platform?</h2></div>\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<nav class=\"inline-tabs\">\n			<ul class=\"js-tab list-unstyled\">\n				<li><a href=\"#tab__1\" class=\"current\">01. Buscar </a></li>\n				<li><a href=\"#tab__2\" class=\"\">02. Reservar </a> </li>\n				<li><a href=\"#tab__3\" class=\"\">03. Aprender </a> </li>\n			</ul></nav>\n		<div class=\"flex-layout-wrapper\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n			<div class=\"tab-container visible\" id=\"tab__1\">\n				<div class=\"flex-layout\">\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/choose-your-tutor.png\" alt=\"\" /></div>\n					<div class=\"flex-layout__content\">\n						<div class=\"content\">\n							<h2>Busca entre cientos de los mejores profesores</h2>\n							<p class=\"p-large\">Usa filtros como precio, idioma, competencia, materia, ubicación, para buscar a tu profesor preferido</p>\n							<div class=\"step__actions\"> <a href=\"/teachers#\" class=\"btn btn--primary\" tabindex=\"0\">Buscar Tutores</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\n									<svg class=\"icon icon--play\">                                 \n										<use xlink:href=\"/images/sprite.svg#play\"></use>                                                    </svg>&nbsp;Ver video</a>                                            </div></div></div></div></div>\n			<div class=\"tab-container\" id=\"tab__2\">\n				<div class=\"flex-layout\">\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/become-an-expert.png\" alt=\"\" /></div>\n					<div class=\"flex-layout__content\">\n						<div class=\"content\">\n							<h2>Reserva clases con el mejor profesor para ti</h2>\n							<p class=\"p-large\">Revisa el perfil del profesor y reserva una lección despu&eacute;s de realizar el pago.</p>\n							<div class=\"step__actions\"> <a href=\"/teachers#\" class=\"btn btn--primary\" tabindex=\"0\">Buscar Tutores</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\n									<svg class=\"icon icon--play\">                                                        \n										<use xlink:href=\"/images/sprite.svg#play\"></use>                                                    </svg>&nbsp;Ver video</a>                                            </div></div></div></div></div>\n			<div class=\"tab-container\" id=\"tab__3\">\n				<div class=\"flex-layout\">\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/book-your-free-lesson.png\" alt=\"\" /></div>\n					<div class=\"flex-layout__content\">\n						<div class=\"content\">\n							<h2>Inicie sesión para comenzar a aprender</h2>\n							<p class=\"p-large\">Asiste a clases en línea y empieza a aprender.</p>\n							<div class=\"step__actions\"> <a href=\"/teachers#\" class=\"btn btn--primary\" tabindex=\"0\">Buscar Tutores</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\n									<svg class=\"icon icon--play\">                                                        \n										<use xlink:href=\"/images/sprite.svg#play\"></use>                                                    </svg>&nbsp;Ver video</a>                                            </div></div></div></div></div></div></div></div>'),
(null, 3, 1, 2, '');
INSERT INTO `tbl_content_pages_lang` (`cpagelang_cpage_id`, `cpagelang_lang_id`, `cpage_title`, `cpage_content`, `cpage_image_title`) VALUES
(1, 1, 'About Us', '\n<div class=\"section\">\n	<div class=\"row justify-content-between align-items-xl-center g-5\">\n		<div class=\"col-md-6\">\n			<div class=\"cms-media\" data-aos=\"fade-up\" data-aos-duration=\"1000\"><img src=\"/image/editor-image/about-whoweare.png\" alt=\"\" /></div></div>\n		<div class=\"col-md-6 col-xl-5\">\n			<div class=\"cms\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n				<h4 class=\"mb-3\">It starts with Who We Are.</h4>\n				<h2 class=\"mb-3\">We build an organization to help people to learn online.</h2>\n				<p>Platform is a self-hosted solution that helps entrepreneurs to launch online tutoring and consultation platforms where multiple tutors or consultants can register and deliver one-to-one or group online sessions to learners. It is a highly scalable and fully customizable solution to meet the business requirements of the users. The solution is pre-integrated with Cometchat, Lesson Space, and Zoom to support features such as video chat, Whiteboard, Textpad, code editor, multiple screen sharing, etc. which improves the interaction between tutor and learner during an online session.</p></div></div></div></div>\n<div class=\"section\">   \n	<div class=\"why-panel\">\n		<div class=\"section__header text-start\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n			<h4>Why Choose Us</h4>\n			<h2>To always learn and improve in order to create better world for the generations to come.</h2></div>\n		<div class=\"section__body\">\n			<div class=\"counters-list pt-4\">\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-1.png\" alt=\"\" /></div><span class=\"counter-card__value\">130 +</span><span class=\"counter-card__label\">Languages Available to Learn</span></div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-2.png\" alt=\"\" /></div><span class=\"counter-card__value\">10k +</span><span class=\"counter-card__label\">Teachers From 120 Countries</span></div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-3.png\" alt=\"\" /></div><span class=\"counter-card__value\">5M +</span><span class=\"counter-card__label\">Learners From 180 Countries</span></div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-4.png\" alt=\"\" /></div><span class=\"counter-card__value\">5M +</span><span class=\"counter-card__label\">Learners From 180 Countries</span></div></div></div></div></div>\n<div class=\"section section--testimonials\">   \n	<div class=\"section__header text-start px-4\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"row align-items-center justify-content-between\">\n			<div class=\"col-xl-8\">\n				<h4>Our Core Values</h4>\n				<h2>We love clients who understand our values</h2>\n			</div>\n			<div class=\"col-xl-auto\">\n				<div class=\"slider-nav\">\n					<button type=\"button\" class=\"prev-slide slick-arrow\"></button>\n					<button type=\"button\" class=\"next-slide slick-arrow\"></button>\n				</div>\n			</div>\n		</div></div>\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"client-testimonials-list js--testimonials\">\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">01</span>Words of Appreciaton</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>Every solution was taking too much time with nothing less than 6 - 8 months, and it was time we did not have. That\'s when Wale found FATbit\'s Platform. We explored our vision around what Platform had to offer, and to our surprise, it fit exactly what we had in mind, and we had a live demo of Platform. We took the chance of picking up a solution to run our vision on, and we haven\'t regretted it any bit. So far, it\'s been a good one for the team.</p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">Mr. Chin Wei Seong</h6></div></div>\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">02</span>Words of Appreciaton</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>We are a brick-and-mortar physical location language school franchise. Once the COVID-19 shut down happened we needed to move online. Platform provides a very modern platform for us to execute not only language learning but all types of learning. </p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">Ray D Angelo</h6></div></div>\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">03</span>Words of Appreciaton</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>My journey with FATbit has been a long one. It took hours and patience to get the website done and to the exact expectations I asked for. FATbit never gives up, they always deliver what they say no matter how much overtime they spend on the project and customer. My developer Eddie, my sales contact Kesa went over and above the call of duty to stay on top of this project. End result; A beautiful and powerfully functional site that will change the world\'s way of learning a new language. Thank you FATbit.</p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">Kelly</h6></div></div>\n						<div class=\"client-testimonail\">\n							<div class=\"client-testimonail__head\">\n								<h4><span class=\"num\">04</span>Words of Appreciaton</h4></div>\n							<div class=\"client-testimonail__body\">\n								<p>I\'m using dashboard of W3mentors platform without any complications and my customers can use my platform in easy way.</p></div>\n							<div class=\"client-testimonail__foot\">\n								<h6 class=\"client-info\">Yacine Tayebi</h6></div></div>\n			</div></div></div>\n<div class=\"section\">\n	<div class=\"grey-wrapper\">\n		<div class=\"section__header text-start\">\n			<div class=\"row align-items-center justify-content-between gap-3\">\n				<div class=\"col-xl-8\">\n					<h4>Our mission &amp; Vision</h4>\n					<h2>Get to know about our mission and vision</h2></div>\n				<div class=\"col-xl-auto\"><a href=\"/contact\" class=\"btn btn--primary btn--large\">Contact Us</a></div></div></div>\n		<div class=\"section__body\">\n			<div class=\"accordion width\" id=\"hrAccordion\">\n				<div class=\"card\">\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseOne\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">Our Mission</span></div>\n					<div id=\"collapseOne\" class=\"collapse show width\" data-parent=\"#hrAccordion\">\n						<div class=\"card-body\">\n							<div class=\"cms-panel\">\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\n								<div class=\"cms-panel__content\">\n									<h2>Our Goal</h2>\n									<p>Our mission is to help entrepreneurs and tutors set up their own online tutoring platforms like Verbling, Preply, and Cambly. We help them reach the pinnacle of their career by enabling them to launch their own tutoring platform using our readymade solution.</p></div></div></div></div></div>\n				<div class=\"card\">\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseTwo\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">Our Inspiration &amp; Vison</span></div>\n					<div id=\"collapseTwo\" class=\"collapse width\" data-parent=\"#hrAccordion\">\n						<div class=\"card-body\">\n							<div class=\"cms-panel\">\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\n								<div class=\"cms-panel__content\">\n									<h2>Our Goal</h2>\n									<p>We, being the leaders and industry experts, provide our turnkey edtech solution, to help entrepreneurs to start their tutoring businesses. Our aim is to offer an easy and hassle-free process for them to enter the market and become a pioneer.</p></div></div></div></div></div>\n				<div class=\"card\">\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseThree\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">Our Goal</span></div>\n					<div id=\"collapseThree\" class=\"collapse width\" data-parent=\"#hrAccordion\">\n						<div class=\"card-body\">\n							<div class=\"cms-panel\">\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\n								<div class=\"cms-panel__content\">\n									<h2>Our Goal</h2>\n									<p>Nam libero tempore, cum soluta nobis est eligendi optio cumque nihil impedit quo minus id quod maxime placeat facere possimus, omnis voluptas assumenda est, omnis dolor repellendus Temporibus autem.</p></div></div></div></div></div></div></div></div></div>\n<div class=\"section\">\n	<div class=\"section__header d-flex gap-5 text-start\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"row justify-content-between pb-4 g-3\">\n			<div class=\"col-xl-3\">\n				<h6>People</h6>\n				<h2>Meet our team of experts</h2></div>\n			<div class=\"col-xl-8\">\n				<p class=\"p-xlarge m-0\">Our highly knowledgeable and experienced team members have a creative, collaborative, and committed nature which enables Platform to be a highly effective company.</p></div></div></div>\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"teacher-wrapper\">\n			<div class=\"slider slider-onefifth slider-onefifth-js\">\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349417-ceo364x364.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>Stephen Fleming</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">CEO & Founder</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349567-marketinghead364x3641.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>James Anderson</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">Sales/Marketing Head</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349739-creativedirector364x3642.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>Nathan Astle</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">Creative Director</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349751-techlead364x3643.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>Mark Boucher</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">Tech Lead </span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349756-saleshead364x3644.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>Steve Waugh</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">Sales/Marketing Head</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349761-creativedirector2364x3645.jpg\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>Damien Martyn</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">Creative Director </span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div></div></div></div>\n	<div class=\"section__footer text-center pt-0\" data-aos=\"fade-up\" data-aos-duration=\"1000\"><a href=\"#\" class=\"text-button\">Explore All Tutors <span class=\"circle-arrow\"></span></a></div></div>\n<div class=\"section section--HowItWorks\">\n	<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<h2>How to start learning with Platform?</h2></div>\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<nav class=\"inline-tabs\">\n			<ul class=\"js-tab list-unstyled\">\n				<li><a href=\"#tab__1\" class=\"current\">01. Search </a></li>\n				<li><a href=\"#tab__2\" class=\"\">02. Book </a> </li>\n				<li><a href=\"#tab__3\" class=\"\">03. Learn </a> </li>\n			</ul></nav>\n		<div class=\"flex-layout-wrapper\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n			<div class=\"tab-container visible\" id=\"tab__1\">\n				<div class=\"flex-layout\">\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/choose-your-tutor.png\" alt=\"\" /></div>\n					<div class=\"flex-layout__content\">\n						<div class=\"content\">\n							<h2>Search through hundreds of best teachers</h2>\n							<p class=\"p-large\">Use filters like price, language, proficiency, subject, location, to search for your preferred teacher</p>\n							<div class=\"step__actions\"> <a href=\"/teachers#\" class=\"btn btn--primary\" tabindex=\"0\">Browse Tutors</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\n									<svg class=\"icon icon--play\">                                 \n										<use xlink:href=\"/images/sprite.svg#play\"></use>                                                    </svg>&nbsp;Watch Video</a>                                            </div></div></div></div></div>\n			<div class=\"tab-container\" id=\"tab__2\">\n				<div class=\"flex-layout\">\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/become-an-expert.png\" alt=\"\" /></div>\n					<div class=\"flex-layout__content\">\n						<div class=\"content\">\n							<h2>Book lessons with the best teacher for you</h2>\n							<p class=\"p-large\">Go through the teacher\'s profile and book a lesson after making the payment.</p>\n							<div class=\"step__actions\"> <a href=\"/teachers#\" class=\"btn btn--primary\" tabindex=\"0\">Browse Tutors</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\n									<svg class=\"icon icon--play\">                                                        \n										<use xlink:href=\"/images/sprite.svg#play\"></use>                                                    </svg>&nbsp;Watch Video</a>                                            </div></div></div></div></div>\n			<div class=\"tab-container\" id=\"tab__3\">\n				<div class=\"flex-layout\">\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/book-your-free-lesson.png\" alt=\"\" /></div>\n					<div class=\"flex-layout__content\">\n						<div class=\"content\">\n							<h2>Log in to Start learning</h2>\n							<p class=\"p-large\">Attend online lessons and start learning.</p>\n							<div class=\"step__actions\"> <a href=\"/teachers#\" class=\"btn btn--primary\" tabindex=\"0\">Browse Tutors</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\n									<svg class=\"icon icon--play\">                                                        \n										<use xlink:href=\"/images/sprite.svg#play\"></use>                                                    </svg>&nbsp;Watch Video</a>                                            </div></div></div></div></div></div></div></div>', 'We build an organization to help people to learn online.'),
(1, 2, 'من نحن', '\n<div class=\"section\">\n	<div class=\"row justify-content-between align-items-xl-center g-5\">\n		<div class=\"col-md-6\">\n			<div class=\"cms-media\" data-aos=\"fade-up\" data-aos-duration=\"1000\"><img src=\"/image/editor-image/about-whoweare.png\" alt=\"\" /></div></div>\n		<div class=\"col-md-6 col-xl-5\">\n			<div class=\"cms\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n				<h4 class=\"mb-3\">يبدأ بمن نحن.</h4>\n				<h2 class=\"mb-3\">نبني منظمة لمساعدة الناس على التعلم عبر الإنترنت.</h2>\n				<p>المنصة عبارة عن حل مستضاف ذاتيا يساعد رواد الأعمال على إطلاق منصات للدروس الخصوصية والاستشارات عبر الإنترنت حيث يمكن للعديد من المعلمين أو الاستشاريين التسجيل وتقديم جلسات فردية أو جماعية عبر الإنترنت للمتعلمين. إنه حل قابل للتطوير بدرجة كبيرة وقابل للتخصيص بالكامل لتلبية متطلبات العمل للمستخدمين. تم دمج الحل مسبقا مع Cometchat و Lesson Space و Zoom لدعم ميزات مثل دردشة الفيديو ، والسبورة البيضاء ، ولوحة النص ، ومحرر التعليمات البرمجية ، ومشاركة الشاشات المتعددة ، وما إلى ذلك مما يحسن التفاعل بين المعلم والمتعلم أثناء الجلسة عبر الإنترنت.</p></div></div></div></div>\n<div class=\"section\">   \n	<div class=\"why-panel\">\n		<div class=\"section__header text-start\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n			<h4>لماذا أخترتنا</h4>\n			<h2>التعلم والتحسين دائما من أجل خلق عالم أفضل للأجيال القادمة.</h2></div>\n		<div class=\"section__body\">\n			<div class=\"counters-list pt-4\">\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-1.png\" alt=\"\" /></div><span class=\"counter-card__value\">130 +</span> <span class=\"counter-card__label\">لغة متاحة للتعلم</span></div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-2.png\" alt=\"\" /></div><span class=\"counter-card__value\">10 آلاف +</span> <span class=\"counter-card__label\">معلمين من 120 دولة</span></div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-3.png\" alt=\"\" /></div><span class=\"counter-card__value\">5 ملايين +</span> <span class=\"counter-card__label\">متعلم من 180 دولة</span></div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-4.png\" alt=\"\" /></div><span class=\"counter-card__value\">5 ملايين +</span> <span class=\"counter-card__label\">متعلم من 180 دولة</span></div></div></div></div></div>\n<div class=\"section section--testimonials\">   \n	<div class=\"section__header text-start px-4\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"row align-items-center justify-content-between\">\n			<div class=\"col-xl-8\">\n				<h4>قيمنا الأساسية</h4>\n				<h2>نحن نحب العملاء الذين يفهمون قيمنا</h2></div>\n			<div class=\"col-xl-auto\">\n				<div class=\"slider-nav\">\n					<button type=\"button\" class=\"prev-slide slick-arrow\"></button>\n					<button type=\"button\" class=\"next-slide slick-arrow\"></button>\n				</div>\n			</div>\n		</div></div>\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"client-testimonials-list js--testimonials\">\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">01</span>كلمات التقدير</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>كان كل حل يستغرق الكثير من الوقت، بما لا يقل عن 6 إلى 8 أشهر، وكان ذلك وقتًا لم يكن لدينا. وذلك عندما وجد ويل منصة FATbit. لقد استكشفنا رؤيتنا حول ما يجب أن تقدمه المنصة، ولدهشتنا، أنها تناسب تمامًا ما كان يدور في ذهننا، وكان لدينا عرض توضيحي مباشر للمنصة. لقد اغتنمنا الفرصة لإيجاد حل لتنفيذ رؤيتنا، ولم نأسف لذلك على الإطلاق. حتى الآن، كان الأمر جيدًا بالنسبة للفريق.</p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">السيد تشين وي سيونغ</h6></div></div>\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">02</span>كلمات تقدير</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>نحن نمتلك امتيازًا لمدرسة اللغات في الموقع الفعلي. بمجرد حدوث الإغلاق بسبب فيروس كورونا (COVID-19)، كنا بحاجة إلى الانتقال إلى الإنترنت. توفر المنصة منصة حديثة للغاية بالنسبة لنا ليس فقط لتعلم اللغة ولكن لجميع أنواع التعلم. </p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">راي د أنجيلو</h6></div></div>\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">03</span>كلمات تقدير</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>لقد كانت رحلتي مع FATbit طويلة. لقد استغرق الأمر ساعات وصبرًا لإنجاز موقع الويب وفقًا للتوقعات الدقيقة التي طلبتها. FATbit لا يستسلم أبدًا، فهو دائمًا يقدم ما يقوله بغض النظر عن مقدار الوقت الإضافي الذي ينفقه على المشروع والعملاء. المطور الخاص بي إيدي، جهة اتصال المبيعات الخاصة بي، Kesa، بذلت قصارى جهدها للبقاء على رأس هذا المشروع. النتيجة النهائية؛ موقع جميل وفعال وسيغير الطريقة العالمية لتعلم لغة جديدة. شكرا لك فاتبيت.</p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">كيلي</h6></div></div>\n<div class=\"client-testimonail\">\n							<div class=\"client-testimonail__head\">\n								<h4><span class=\"num\">04</span>كلمات تقدير</h4></div>\n							<div class=\"client-testimonail__body\">\n								<p>أنا أستخدم لوحة التحكم في منصة W3mentors دون أي تعقيدات ويمكن لعملائي استخدام منصتي بطريقة سهلة.</p></div>\n							<div class=\"client-testimonail__foot\">\n								<h6 class=\"client-info\">ياسين الطيبي</h6></div></div\n			</div></div></div>\n<div class=\"section\">\n	<div class=\"grey-wrapper\">\n		<div class=\"section__header text-start\">\n			<div class=\"row align-items-center justify-content-between gap-3\">\n				<div class=\"col-xl-8\">\n					<h4>مهمتنا ورؤيتنا</h4>\n					<h2>تعرف على مهمتنا ورؤيتنا</h2></div>\n				<div class=\"col-xl-auto\"><a href=\"/contact\" class=\"btn btn--primary btn--large\">اتصل بنا</a></div></div></div>\n		<div class=\"section__body\">\n			<div class=\"accordion width\" id=\"hrAccordion\">\n				<div class=\"card\">\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseOne\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">مهمتنا</span></div>\n					<div id=\"collapseOne\" class=\"collapse show width\" data-parent=\"#hrAccordion\">\n						<div class=\"card-body\">\n							<div class=\"cms-panel\">\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\n								<div class=\"cms-panel__content\">\n									<h2>هدفنا</h2>\n									<p>مهمتنا هي مساعدة رواد الأعمال والمدرسين على إنشاء منصات التدريس الخاصة بهم عبر الإنترنت مثل Verbling وPreply وCambly. نحن نساعدهم على الوصول إلى قمة حياتهم المهنية من خلال تمكينهم من إطلاق منصة التدريس الخاصة بهم باستخدام حلنا الجاهز.</p></div></div></div></div></div>\n				<div class=\"card\">\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseTwo\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">إلهامنا ومراقبتنا</span></div>\n					<div id=\"collapseTwo\" class=\"collapse width\" data-parent=\"#hrAccordion\">\n						<div class=\"card-body\">\n							<div class=\"cms-panel\">\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\n								<div class=\"cms-panel__content\">\n									<h2>هدفنا</h2>\n									<p>نحن، كقادة وخبراء في الصناعة، نقدم حل تكنولوجيا التعليم الجاهز لمساعدة رواد الأعمال على بدء أعمالهم التعليمية. هدفنا هو تقديم عملية سهلة وخالية من المتاعب لهم لدخول السوق ويصبحوا روادًا.</p></div></div></div></div></div>\n				<div class=\"card\">\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseThree\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">هدفنا</span></div>\n					<div id=\"collapseThree\" class=\"collapse width\" data-parent=\"#hrAccordion\">\n						<div class=\"card-body\">\n							<div class=\"cms-panel\">\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\n								<div class=\"cms-panel__content\">\n									<h2>هدفنا</h2>\n									<p>Nam libero tempore, cum soluta nobis est eligendi optio cumque nihil impedit quo minus id quod maxime placeat facere possimus, omnis voluptas assumenda est, omnis dolor repellendus Temporibus autem.</p></div></div></div></div></div></div></div></div></div>\n<div class=\"section\">\n	<div class=\"section__header d-flex gap-5 text-start\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"row justify-content-between pb-4 g-3\">\n			<div class=\"col-xl-3\">\n				<h6>شعب</h6>\n				<h2>تعرف على فريق الخبراء لدينا</h2></div>\n			<div class=\"col-xl-8\">\n				<p class=\"p-xlarge m-0\">يتمتع أعضاء فريقنا ذوي المعرفة والخبرة العالية بطبيعة إبداعية وتعاونية وملتزمة تمكن المنصة من أن تكون شركة فعالة للغاية.</p></div></div></div>\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"teacher-wrapper\">\n			<div class=\"slider slider-onefifth slider-onefifth-js\">\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349417-ceo364x364.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>ستيفن فليمنج</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">الرئيس التنفيذي والمؤسس</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349567-marketinghead364x3641.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>جيمس أندرسون</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">رئيس المبيعات/التسويق</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349739-creativedirector364x3642.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>ناثان أستل</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">المدير الإبداعي</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349751-techlead364x3643.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>مارك باوتشر</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">الرصاص الفني</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349756-saleshead364x3644.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>ستيف وو</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">رئيس المبيعات/التسويق</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349761-creativedirector2364x3645.jpg\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>داميان مارتن</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">المدير الإبداعي </span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div></div></div></div>\n	<div class=\"section__footer text-center pt-0\" data-aos=\"fade-up\" data-aos-duration=\"1000\"><a href=\"#\" class=\"text-button\">استكشاف جميع المعلمين <span class=\"circle-arrow\"></span></a></div></div>\n<div class=\"section section--HowItWorks\">\n	<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<h2>كيف تبدأ التعلم مع المنصة؟</h2></div>\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<nav class=\"inline-tabs\">\n			<ul class=\"js-tab list-unstyled\">\n				<li><a href=\"#tab__1\" class=\"current\">01. البحث</a></li>\n				<li><a href=\"#tab__2\" class=\"\">02. كتاب  </a> </li>\n				<li><a href=\"#tab__3\" class=\"\">03. تعلم   </a> </li>\n			</ul></nav>\n		<div class=\"flex-layout-wrapper\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n			<div class=\"tab-container visible\" id=\"tab__1\">\n				<div class=\"flex-layout\">\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/choose-your-tutor.png\" alt=\"\" /></div>\n					<div class=\"flex-layout__content\">\n						<div class=\"content\">\n							<h2>ابحث في مئات من أفضل المعلمين</h2>\n							<p class=\"p-large\">استخدم عوامل تصفية مثل السعر واللغة والكفاءة والموضوع والموقع للبحث عن معلمك المفضل</p>\n							<div class=\"step__actions\"> <a href=\"/teachers#\" class=\"btn btn--primary\" tabindex=\"0\">تصفح المدرسين</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\n									<svg class=\"icon icon--play\">                                 \n										<use xlink:href=\"/images/sprite.svg#play\"></use>                                                    </svg>&nbsp;شاهد الفيديو</a>                                            </div></div></div></div></div>\n			<div class=\"tab-container\" id=\"tab__2\">\n				<div class=\"flex-layout\">\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/become-an-expert.png\" alt=\"\" /></div>\n					<div class=\"flex-layout__content\">\n						<div class=\"content\">\n							<h2>احجز الدروس مع أفضل معلم لك</h2>\n							<p class=\"p-large\">انتقل من خلال ملف تعريف المعلم وحجز درس بعد إجراء الدفع.</p>\n							<div class=\"step__actions\"> <a href=\"/teachers#\" class=\"btn btn--primary\" tabindex=\"0\">تصفح المدرسين</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\n									<svg class=\"icon icon--play\">                                                        \n										<use xlink:href=\"/images/sprite.svg#play\"></use>                                                    </svg>&nbsp;شاهد الفيديو</a>                                            </div></div></div></div></div>\n			<div class=\"tab-container\" id=\"tab__3\">\n				<div class=\"flex-layout\">\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/book-your-free-lesson.png\" alt=\"\" /></div>\n					<div class=\"flex-layout__content\">\n						<div class=\"content\">\n							<h2>تسجيل الدخول لبدء التعلم</h2>\n							<p class=\"p-large\">حضور الدروس عبر الإنترنت والبدء في التعلم.</p>\n							<div class=\"step__actions\"> <a href=\"/teachers#\" class=\"btn btn--primary\" tabindex=\"0\">تصفح المدرسين</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\n									<svg class=\"icon icon--play\">                                                        \n										<use xlink:href=\"/images/sprite.svg#play\"></use>                                                    </svg>&nbsp;شاهد الفيديو</a>                                            </div></div></div></div></div></div></div></div>', 'نبني منظمة لمساعدة الناس على التعلم عبر الإنترنت.');
INSERT INTO `tbl_content_pages_lang` (`cpagelang_cpage_id`, `cpagelang_lang_id`, `cpage_title`, `cpage_content`, `cpage_image_title`) VALUES
(1, 3, 'Sobre nosotros', '\n<div class=\"section\">\n	<div class=\"row justify-content-between align-items-xl-center g-5\">\n		<div class=\"col-md-6\">\n			<div class=\"cms-media\" data-aos=\"fade-up\" data-aos-duration=\"1000\"><img src=\"/image/editor-image/about-whoweare.png\" alt=\"\" /></div></div>\n		<div class=\"col-md-6 col-xl-5\">\n			<div class=\"cms\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n				<h4 class=\"mb-3\">Comienza con Qui&eacute;nes Somos.</h4>\n				<h2 class=\"mb-3\">Construimos una organización para ayudar a las personas a aprender en línea.</h2>\n				<p>Platform es una solución autoalojada que ayuda a los emprendedores a lanzar plataformas de tutoría y consulta en línea donde varios tutores o consultores pueden registrarse y ofrecer sesiones en línea individuales o grupales a los estudiantes. Es una solución altamente escalable y totalmente personalizable para cumplir con los requisitos comerciales de los usuarios. La solución está preintegrada con Cometchat, Lesson Space y Zoom para admitir funciones como chat de video, pizarra, teclado de texto, editor de código, uso compartido de múltiples pantallas, etc., lo que mejora la interacción entre el tutor y el alumno durante una sesión en línea.</p></div></div></div></div>\n<div class=\"section\">   \n	<div class=\"why-panel\">\n		<div class=\"section__header text-start\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n			<h4>¿Por qu&eacute; elegirnos?</h4>\n			<h2>Aprender y mejorar siempre para crear un mundo mejor para las generaciones venideras.</h2></div>\n		<div class=\"section__body\">\n			<div class=\"counters-list pt-4\">\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-1.png\" alt=\"\" /></div><span class=\"counter-card__value\">130 +</span><span class=\"counter-card__label\">Idiomas disponibles para aprender</span></div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-2.png\" alt=\"\" /></div><span class=\"counter-card__value\">10k +</span><span class=\"counter-card__label\">Profesores de 120 países</span></div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-3.png\" alt=\"\" /></div><span class=\"counter-card__value\">5M +</span><span class=\"counter-card__label\">Aprendices de 180 países</span></div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-4.png\" alt=\"\" /></div><span class=\"counter-card__value\">5M +</span><span class=\"counter-card__label\">Aprendices de 180 países</span></div></div></div></div></div>\n<div class=\"section section--testimonials\">   \n	<div class=\"section__header text-start px-4\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"row align-items-center justify-content-between\">\n			<div class=\"col-xl-8\">\n				<h4>Nuestros Valores Fundamentales</h4>\n				<h2>Nos encantan los clientes que entienden nuestros valores</h2></div>\n			<div class=\"col-xl-auto\">\n				<div class=\"slider-nav\">\n					<button type=\"button\" class=\"prev-slide slick-arrow\"></button>\n					<button type=\"button\" class=\"next-slide slick-arrow\"></button>\n				</div>\n			</div>\n		</div></div>\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"client-testimonials-list js--testimonials\">\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">01</span>Palabras de agradecimiento</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>Cada solución estaba tomando demasiado tiempo, nada menos que 6 a 8 meses, y era tiempo que no teníamos. Fue entonces cuando Wale encontró la plataforma FATbit. Exploramos nuestra visión sobre lo que Platform tenía para ofrecer y, para nuestra sorpresa, encajaba exactamente con lo que teníamos en mente y tuvimos una demostración en vivo de Platform. Aprovechamos la oportunidad de encontrar una solución para ejecutar nuestra visión y no nos hemos arrepentido en absoluto. Hasta ahora, ha sido bueno para el equipo.</p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">Sr. Chin Wei Seong</h6></div></div>\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">02</span>Palabras de agradecimiento</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>Somos una franquicia de escuelas de idiomas con ubicación física física. Una vez que se produjo el cierre de COVID-19, necesitábamos pasar a estar en línea. Platform proporciona una plataforma muy moderna para que podamos ejecutar no solo el aprendizaje de idiomas sino todo tipo de aprendizaje. </p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">Ray D Angelo</h6></div></div>\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">03</span>Palabras de agradecimiento</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>Mi viaje con FATbit ha sido largo. Me tomó horas y paciencia lograr que el sitio web cumpliera con las expectativas exactas que pedí. FATbit nunca se rinde, siempre cumplen lo que dicen sin importar cuántas horas extras dediquen al proyecto y al cliente. Mi desarrollador Eddie y mi contacto de ventas, Kesa, hicieron todo lo posible para mantenerse al tanto de este proyecto. Resultado final; Un sitio hermoso y poderosamente funcional que cambiará la forma en que el mundo aprende un nuevo idioma. Gracias FATbit.</p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">Kelly</h6></div></div>\n                        <div class=\"client-testimonail\">\n							<div class=\"client-testimonail__head\">\n								<h4><span class=\"num\">04</span>Palabras de agradecimiento</h4></div>\n							<div class=\"client-testimonail__body\">\n								<p>Estoy usando el panel de control de la plataforma W3mentors sin ninguna complicación y mis clientes pueden usar mi plataforma de manera sencilla.</p></div>\n							<div class=\"client-testimonail__foot\">\n								<h6 class=\"client-info\">Yacine Tayebi</h6></div></div>\n			</div></div></div>\n<div class=\"section\">\n	<div class=\"grey-wrapper\">\n		<div class=\"section__header text-start\">\n			<div class=\"row align-items-center justify-content-between gap-3\">\n				<div class=\"col-xl-8\">\n					<h4>Nuestra misión y visión</h4>\n					<h2>Conozca nuestra misión y visión</h2></div>\n				<div class=\"col-xl-auto\"><a href=\"/contact\" class=\"btn btn--primary btn--large\">Contáctenos</a></div></div></div>\n		<div class=\"section__body\">\n			<div class=\"accordion width\" id=\"hrAccordion\">\n				<div class=\"card\">\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseOne\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">NUESTRA MISIÓN</span></div>\n					<div id=\"collapseOne\" class=\"collapse show width\" data-parent=\"#hrAccordion\">\n						<div class=\"card-body\">\n							<div class=\"cms-panel\">\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\n								<div class=\"cms-panel__content\">\n									<h2>Nuestro objetivo</h2>\n									<p>Nuestra misión es ayudar a emprendedores y tutores a configurar sus propias plataformas de tutoría en línea como Verbling, Preply y Cambly. Les ayudamos a alcanzar la cima de su carrera permitiéndoles lanzar su propia plataforma de tutoría utilizando nuestra solución lista para usar.</p></div></div></div></div></div>\n				<div class=\"card\">\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseTwo\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">Nuestra Inspiración &amp; Visión</span></div>\n					<div id=\"collapseTwo\" class=\"collapse width\" data-parent=\"#hrAccordion\">\n						<div class=\"card-body\">\n							<div class=\"cms-panel\">\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\n								<div class=\"cms-panel__content\">\n									<h2>Nuestro objetivo</h2>\n									<p>Nosotros, como líderes y expertos de la industria, brindamos nuestra solución de tecnología educativa llave en mano para ayudar a los emprendedores a iniciar sus negocios de tutoría. Nuestro objetivo es ofrecerles un proceso fácil y sin complicaciones para ingresar al mercado y convertirse en pioneros.</p></div></div></div></div></div>\n				<div class=\"card\">\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseThree\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">Nuestro objetivo</span></div>\n					<div id=\"collapseThree\" class=\"collapse width\" data-parent=\"#hrAccordion\">\n						<div class=\"card-body\">\n							<div class=\"cms-panel\">\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\n								<div class=\"cms-panel__content\">\n									<h2>Nuestro objetivo</h2>\n									<p>Nam libero tempore, cum soluta nobis est eligendi optio cumque nihil impedit quo minus id quod maxime placeat facere possimus, omnis voluptas assumenda est, omnis dolor repellendus Temporibus autem.</p></div></div></div></div></div></div></div></div></div>\n<div class=\"section\">\n	<div class=\"section__header d-flex gap-5 text-start\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"row justify-content-between pb-4 g-3\">\n			<div class=\"col-xl-3\">\n				<h6>Gente</h6>\n				<h2>Conozca a nuestro equipo de expertos</h2></div>\n			<div class=\"col-xl-8\">\n				<p class=\"p-xlarge m-0\">Los miembros de nuestro equipo altamente informados y experimentados tienen una naturaleza creativa, colaborativa y comprometida que permite a Platform ser una empresa altamente efectiva.</p></div></div></div>\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"teacher-wrapper\">\n			<div class=\"slider slider-onefifth slider-onefifth-js\">\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349417-ceo364x364.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>Esteban Fleming</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">CEO y fundador</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349567-marketinghead364x3641.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>James Anderson</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">Jefe de Ventas / Marketing</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349739-creativedirector364x3642.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>Nathan Astle</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">Director creativo</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349751-techlead364x3643.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>Marcos Boucher</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">Líder tecnológico </span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349756-saleshead364x3644.png\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>Steve Waugh</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">Jefe de Ventas / Marketing</span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n				<div class=\"tile__media ratio ratio--3by4\"><a href=\"#\"><img src=\"/image/editor-image/1650349761-creativedirector2364x3645.jpg\" alt=\"\" /></a></div>\n			<div class=\"tile__body\"><h4>Damián Martín</h4>\n                                            <div class=\"card-element justify-content-center\">\n                                                <span class=\"card-element__item\">Director creativo </span>\n                                                                                            </div>\n                                        </div>\n			</div></div></div></div></div></div></div>\n	<div class=\"section__footer text-center pt-0\" data-aos=\"fade-up\" data-aos-duration=\"1000\"><a href=\"#\" class=\"text-button\">Explora todos los tutores <span class=\"circle-arrow\"></span></a></div></div>\n<div class=\"section section--HowItWorks\">\n	<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<h2>¿Cómo empezar a aprender con Platform?</h2></div>\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<nav class=\"inline-tabs\">\n			<ul class=\"js-tab list-unstyled\">\n				<li><a href=\"#tab__1\" class=\"current\">01. Buscar </a></li>\n				<li><a href=\"#tab__2\" class=\"\">02. Reservar </a> </li>\n				<li><a href=\"#tab__3\" class=\"\">03. Aprender </a> </li>\n			</ul></nav>\n		<div class=\"flex-layout-wrapper\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n			<div class=\"tab-container visible\" id=\"tab__1\">\n				<div class=\"flex-layout\">\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/choose-your-tutor.png\" alt=\"\" /></div>\n					<div class=\"flex-layout__content\">\n						<div class=\"content\">\n							<h2>Busca entre cientos de los mejores profesores</h2>\n							<p class=\"p-large\">Usa filtros como precio, idioma, competencia, materia, ubicación, para buscar a tu profesor preferido</p>\n							<div class=\"step__actions\"> <a href=\"/teachers#\" class=\"btn btn--primary\" tabindex=\"0\">Buscar Tutores</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\n									<svg class=\"icon icon--play\">                                 \n										<use xlink:href=\"/images/sprite.svg#play\"></use>                                                    </svg>&nbsp;Ver video</a>                                            </div></div></div></div></div>\n			<div class=\"tab-container\" id=\"tab__2\">\n				<div class=\"flex-layout\">\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/become-an-expert.png\" alt=\"\" /></div>\n					<div class=\"flex-layout__content\">\n						<div class=\"content\">\n							<h2>Reserva clases con el mejor profesor para ti</h2>\n							<p class=\"p-large\">Revisa el perfil del profesor y reserva una lección despu&eacute;s de realizar el pago.</p>\n							<div class=\"step__actions\"> <a href=\"/teachers#\" class=\"btn btn--primary\" tabindex=\"0\">Buscar Tutores</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\n									<svg class=\"icon icon--play\">                                                        \n										<use xlink:href=\"/images/sprite.svg#play\"></use>                                                    </svg>&nbsp;Ver video</a>                                            </div></div></div></div></div>\n			<div class=\"tab-container\" id=\"tab__3\">\n				<div class=\"flex-layout\">\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/book-your-free-lesson.png\" alt=\"\" /></div>\n					<div class=\"flex-layout__content\">\n						<div class=\"content\">\n							<h2>Inicie sesión para comenzar a aprender</h2>\n							<p class=\"p-large\">Asiste a clases en línea y empieza a aprender.</p>\n							<div class=\"step__actions\"> <a href=\"/teachers#\" class=\"btn btn--primary\" tabindex=\"0\">Buscar Tutores</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\n									<svg class=\"icon icon--play\">                                                        \n										<use xlink:href=\"/images/sprite.svg#play\"></use>                                                    </svg>&nbsp;Ver video</a>                                            </div></div></div></div></div></div></div></div>', 'Construimos una organización para ayudar a las personas a aprender en línea.');
INSERT INTO `tbl_attached_files` (`file_id`, `file_type`, `file_record_id`, `file_lang_id`, `file_path`, `file_name`, `file_order`, `file_added`) VALUES
