INSERT INTO `tbl_email_templates` (`etpl_code`, `etpl_lang_id`, `etpl_name`, `etpl_subject`, `etpl_body`, `etpl_vars`, `etpl_status`, `etpl_quick_send`) VALUES
('delete_account_request_email', 1, 'Account Deletion Request', 'Account Deletion Requested', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\">                                </h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;background-color: rgb(255, 255, 255); margin: 8px 0px 0px; padding: 0px; font-size: 30px;\">Account Delete Request\r\n                                </h2> \r\n                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">                                    Dear Admin</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">You have received an\r\n                                    account deletion request from a user. Please consider the below details for further\r\n                                    processing:</p>                                \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n									<tbody>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Username</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{username}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Email</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{email}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Account Type</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{account_type}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Reason</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{deletion_reason}</td>                                        \r\n										</tr>                                    \r\n									</tbody>                                \r\n								</table>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table> ', '{username} User Full Name<br>\r\n{email} User Email<br>\r\n{account_type} Learner/Teacher<br>\r\n{deletion_reason} Reason for deletion request <br>{website_name} - Website Name<br>', 1, 1),
('delete_account_request_email', 2, 'طلب حذف الحساب', 'طلب حذف الحساب', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\">                                </h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;background-color: rgb(255, 255, 255); margin: 8px 0px 0px; padding: 0px; font-size: 30px;\">طلب حذف الحساب                                </h2> \r\n                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">                                    عزيزي المشرف</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">تلقيت\r\n                                    طلب حذف الحساب من مستخدم. يرجى النظر في التفاصيل أدناه لمزيد من المعلومات\r\n                                    تجهيز:</p>                                \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n									<tbody>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">اسم المستخدم</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{<span style=\"color: rgb(51, 51, 51); font-size: 13px; text-align: left; background-color: rgb(255, 255, 255);\">username</span>}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">البريد الإلكتروني</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{<span style=\"color: rgb(51, 51, 51); font-size: 13px; text-align: left; background-color: rgb(255, 255, 255);\">email</span><span style=\"color: rgb(51, 51, 51); font-size: 13px; text-align: left; background-color: rgb(255, 255, 255);\"></span>}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">نوع الحساب</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{account_type}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">سبب</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{deletion_reason}</td>                                        \r\n										</tr>                                    \r\n									</tbody>                                \r\n								</table>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>  ', '{username} User Full Name<br>\r\n{email} User Email<br>\r\n{account_type} Learner/Teacher<br>\r\n{deletion_reason} Reason for deletion request <br>{website_name} - Website Name<br>', 1, 1),
('delete_account_request_email', 3, 'Solicitud de eliminación de cuenta', 'Eliminación de cuenta solicitada', '\r\n<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\">                                </h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;background-color: rgb(255, 255, 255); margin: 8px 0px 0px; padding: 0px; font-size: 30px;\">Solicitud de eliminación de cuenta                                </h2> \r\n                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">                                    Estimado administrador</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Ha recibido un\r\n                                    Solicitud de eliminación de cuenta de un usuario. Tenga en cuenta los detalles a continuación para obtener más información.\r\n                                    Tratamiento:</p>                                \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n									<tbody>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Nombre de usuario</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{<span style=\"color: rgb(51, 51, 51); font-size: 13px; background-color: rgb(255, 255, 255);\">username</span>}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Correo electrónico</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{<span style=\"color: rgb(51, 51, 51); font-size: 13px; background-color: rgb(255, 255, 255);\">email</span>}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Tipo de cuenta</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{account_type}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Razón</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{deletion_reason}</td>                                        \r\n										</tr>                                    \r\n									</tbody>                                \r\n								</table>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>  ', '{username} User Full Name<br>\r\n{email} User Email<br>\r\n{account_type} Learner/Teacher<br>\r\n{deletion_reason} Reason for deletion request <br>{website_name} - Website Name<br>', 1, 0);
INSERT INTO `tbl_extra_pages` (`epage_id`, `epage_identifier`, `epage_block_type`, `epage_type`, `epage_editable`, `epage_active`, `epage_default_content`, `epage_order`) VALUES ('22', 'Creating A Community Section', '22', '1', '1', '1', '<section class=\"section\">\r\n            <div class=\"container container--xxl\">\r\n                <div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n                    <h2>Creating A Community Of Life Long Learners.</h2>\r\n                </div>\r\n                <div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n                    <div class=\"stats-wrapper\">\r\n                        <div class=\"stats-listing\">\r\n                            <div class=\"stats\">\r\n                                <span class=\"stats__number\"><span data-target=\"30\">0</span><i>+</i></span>\r\n                                <span class=\"stats__label\">Learners</span>\r\n                            </div>\r\n                            <div class=\"stats\">\r\n                                <span class=\"stats__number\"><span data-target=\"15\">0</span><i>+</i></span>\r\n                                <span class=\"stats__label\">Teachers</span>\r\n                            </div>\r\n                            <div class=\"stats\">\r\n                                <span class=\"stats__number\"><span data-target=\"5\">0</span><i>+</i></span>\r\n                                <span class=\"stats__label\">Affiliate</span>\r\n                            </div>\r\n                            <div class=\"stats\">\r\n                                <span class=\"stats__number\"><span data-target=\"35\">0</span><i>+</i></span>\r\n                                <span class=\"stats__label\">Total Users</span>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </section>', '8');
INSERT INTO `tbl_extra_pages_lang` (`epagelang_epage_id`, `epagelang_lang_id`, `epage_label`, `epage_content`) VALUES
(22, 1, 'Creating A Community Section', '    \r\n<section class=\"section\">            \r\n	<div class=\"container container--xxl\">                \r\n		<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n			<h2>Creating A Community Of Life Long Learners.</h2>                </div>                \r\n		<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n			<div class=\"stats-wrapper\">                        \r\n				<div class=\"stats-listing\">                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"30\">0</span><i>+</i></span>                                <span class=\"stats__label\">Learners</span>                            </div>                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"15\">0</span><i>+</i></span>                                <span class=\"stats__label\">Teachers</span>                            </div>                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"5\">0</span><i>+</i></span>                                <span class=\"stats__label\">Affiliate</span>                            </div>                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"35\">0</span><i>+</i></span>                                <span class=\"stats__label\">Total Users</span>                            </div>                        </div>                    </div>                </div>            </div>        </section>'),
(22, 2, 'إنشاء قسم المجتمع', '    \r\n<section class=\"section\">            \r\n	<div class=\"container container--xxl\">                \r\n		<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n			<h2>خلق مجتمع من المتعلمين مدى الحياة.</h2>                </div>                \r\n		<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n			<div class=\"stats-wrapper\">                        \r\n				<div class=\"stats-listing\">                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"30\">0</span><i>+</i></span> <span class=\"stats__label\">المتعلمون</span>                                                            </div>                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"15\">0</span><i>+</i></span>                                <span class=\"stats__label\">معلمون</span>                            </div>                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"5\">0</span><i>+</i></span>                                <span class=\"stats__label\">تابع</span>                            </div>                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"35\">0</span><i>+</i></span>                                <span class=\"stats__label\">إجمالي المستخدمين</span>                            </div>                        </div>                    </div>                </div>            </div>        </section>'),
(22, 3, 'Creación de una sección de la comunidad', '    \r\n<section class=\"section\">            \r\n	<div class=\"container container--xxl\">                \r\n		<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n			<h2>Creando una comunidad de aprendices de por vida.</h2>                </div>                \r\n		<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n			<div class=\"stats-wrapper\">                        \r\n				<div class=\"stats-listing\">                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"30\">0</span><i>+</i></span>                                <span class=\"stats__label\">Aprendices</span>                            </div>                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"15\">0</span><i>+</i></span>                                <span class=\"stats__label\">Profesores</span>                            </div>                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"5\">0</span><i>+</i></span>                                <span class=\"stats__label\">Afiliado</span>                            </div>                            \r\n					<div class=\"stats\">                                <span class=\"stats__number\"><span data-target=\"35\">0</span><i>+</i></span>                                <span class=\"stats__label\">Total de usuarios</span>                            </div>                        </div>                    </div>                </div>            </div>        </section>');
INSERT INTO `tbl_language_labels` (`label_id`, `label_lang_id`, `label_key`, `label_caption`) VALUES (NULL, '1', 'LBL_CART_COURSE_LANGUAGE', 'Course language'), (NULL, '2', 'LBL_CART_COURSE_LANGUAGE', 'لغة الدورة'), (NULL, '3', 'LBL_CART_COURSE_LANGUAGE', 'Idioma del curso');
INSERT INTO `tbl_content_pages_block_lang` (`cpblocklang_id`, `cpblocklang_lang_id`, `cpblocklang_cpage_id`, `cpblocklang_block_id`, `cpblocklang_text`) VALUES
(12, 1, 1, 1, '\n<div class=\"section\">\n	<div class=\"row justify-content-between align-items-xl-center g-5\">\n		<div class=\"col-md-6\">\n			<div class=\"cms-media\" data-aos=\"fade-up\" data-aos-duration=\"1000\"><img src=\"/image/editor-image/about-whoweare.png\" alt=\"\" /></div></div>\n		<div class=\"col-md-6 col-xl-5\">\n			<div class=\"cms\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n				<h4 class=\"mb-3\">It starts with Who We Are.</h4>\n				<h2 class=\"mb-3\">We build an organization to help people to learn online.</h2>\n				<p>Platform is a self-hosted solution that helps entrepreneurs to launch online tutoring and\n					consultation platforms where multiple tutors or consultants can register and deliver one-to-one or\n					group online sessions to learners. It is a highly scalable and fully customizable solution to meet\n					the business requirements of the users. The solution is pre-integrated with Cometchat, Lesson Space,\n					and Zoom to support features such as video chat, Whiteboard, Textpad, code editor, multiple screen\n					sharing, etc. which improves the interaction between tutor and learner during an online session.</p></div></div></div></div>\n<div class=\"section\">\n	<div class=\"why-panel\">\n		<div class=\"section__header text-start\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n			<h4>Why Choose Us</h4>\n			<h2>To always learn and improve in order to create better world for the generations to come.</h2></div>\n		<div class=\"section__body\">\n			<div class=\"counters-list pt-4\">\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-1.png\" alt=\"\" /></div><span class=\"counter-card__value\">130 +</span><span class=\"counter-card__label\">Languages Available\n						to Learn</span></div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-2.png\" alt=\"\" /></div><span class=\"counter-card__value\">10k +</span><span class=\"counter-card__label\">Teachers From 120\n						Countries</span></div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-3.png\" alt=\"\" /></div><span class=\"counter-card__value\">5M +</span><span class=\"counter-card__label\">Learners From 180\n						Countries</span></div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-4.png\" alt=\"\" /></div><span class=\"counter-card__value\">5M +</span><span class=\"counter-card__label\">Learners From 180\n						Countries</span></div></div></div></div></div>\n<div class=\"section section--testimonials\">\n	<div class=\"section__header text-start px-4\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"row align-items-center justify-content-between\">\n			<div class=\"col-xl-8\">\n				<h4>Our Core Values</h4>\n				<h2>We love clients who understand our values</h2></div>\n			<div class=\"col-xl-auto\">\n				<div class=\"slider-nav\">\n					<button type=\"button\" class=\"prev-slide slick-arrow\"></button>\n					<button type=\"button\" class=\"next-slide slick-arrow\"></button></div></div></div></div>\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"client-testimonials-list js--testimonials\">\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">01</span>Words of Appreciaton</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>Every solution was taking too much time with nothing less than 6 - 8 months, and it was time we\n						did not have. That\'s when Wale found FATbit\'s Platform. We explored our vision around what\n						Platform had to offer, and to our surprise, it fit exactly what we had in mind, and we had a\n						live demo of Platform. We took the chance of picking up a solution to run our vision on, and we\n						haven\'t regretted it any bit. So far, it\'s been a good one for the team.</p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">Mr. Chin Wei Seong</h6></div></div>\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">02</span>Words of Appreciaton</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>We are a brick-and-mortar physical location language school franchise. Once the COVID-19 shut\n						down happened we needed to move online. Platform provides a very modern platform for us to\n						execute not only language learning but all types of learning. </p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">Ray D Angelo</h6></div></div>\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">03</span>Words of Appreciaton</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>My journey with FATbit has been a long one. It took hours and patience to get the website done\n						and to the exact expectations I asked for. FATbit never gives up, they always deliver what they\n						say no matter how much overtime they spend on the project and customer. My developer Eddie, my\n						sales contact Kesa went over and above the call of duty to stay on top of this project. End\n						result; A beautiful and powerfully functional site that will change the world\'s way of learning\n						a new language. Thank you FATbit.</p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">Kelly</h6></div></div>\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">04</span>Words of Appreciaton</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>I\'m using dashboard of W3mentors platform without any complications and my customers can use my\n						platform in easy way.</p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">Yacine Tayebi</h6></div></div></div></div></div>\n<div class=\"section\">\n	<div class=\"grey-wrapper\">\n		<div class=\"section__header text-start\">\n			<div class=\"row align-items-center justify-content-between gap-3\">\n				<div class=\"col-xl-8\">\n					<h4>Our mission &amp; Vision</h4>\n					<h2>Get to know about our mission and vision</h2></div>\n				<div class=\"col-xl-auto\"><a href=\"/contact\" class=\"btn btn--primary btn--large\">Contact Us</a></div></div></div>\n		<div class=\"section__body\">\n			<div class=\"accordion width\" id=\"hrAccordion\">\n				<div class=\"card\">\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseOne\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">Our Mission</span></div>\n					<div id=\"collapseOne\" class=\"collapse show width\" data-parent=\"#hrAccordion\">\n						<div class=\"card-body\">\n							<div class=\"cms-panel\">\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\n								<div class=\"cms-panel__content\">\n									<h2>Our Goal</h2>\n									<p>Our mission is to help entrepreneurs and tutors set up their own online tutoring\n										platforms like Verbling, Preply, and Cambly. We help them reach the pinnacle of\n										their career by enabling them to launch their own tutoring platform using our\n										readymade solution.</p></div></div></div></div></div>\n				<div class=\"card\">\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseTwo\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">Our Inspiration &amp; Vison</span></div>\n					<div id=\"collapseTwo\" class=\"collapse width\" data-parent=\"#hrAccordion\">\n						<div class=\"card-body\">\n							<div class=\"cms-panel\">\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\n								<div class=\"cms-panel__content\">\n									<h2>Our Goal</h2>\n									<p>We, being the leaders and industry experts, provide our turnkey edtech solution,\n										to help entrepreneurs to start their tutoring businesses. Our aim is to offer an\n										easy and hassle-free process for them to enter the market and become a pioneer.</p></div></div></div></div></div>\n				<div class=\"card\">\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseThree\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">Our Goal</span></div>\n					<div id=\"collapseThree\" class=\"collapse width\" data-parent=\"#hrAccordion\">\n						<div class=\"card-body\">\n							<div class=\"cms-panel\">\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\n								<div class=\"cms-panel__content\">\n									<h2>Our Goal</h2>\n									<p>Nam libero tempore, cum soluta nobis est eligendi optio cumque nihil impedit quo\n										minus id quod maxime placeat facere possimus, omnis voluptas assumenda est,\n										omnis dolor repellendus Temporibus autem.</p></div></div></div></div></div></div></div></div></div>\n<div class=\"section\">\n	<div class=\"section__header d-flex gap-5 text-start\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"row justify-content-between pb-4 g-3\">\n			<div class=\"col-xl-3\">\n				<h6>People</h6>\n				<h2>Meet our team of experts</h2></div>\n			<div class=\"col-xl-8\">\n				<p class=\"p-xlarge m-0\">Our highly knowledgeable and experienced team members have a creative,\n					collaborative, and committed nature which enables Platform to be a highly effective company.</p></div></div></div>\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"teacher-wrapper\">\n			<div class=\"slider d-block slider-onefifth slider-onefifth-js\">\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n								<div class=\"tile__media ratio ratio--3by4\"><img src=\"/image/editor-image/1650349417-ceo364x364.png\" alt=\"\" /></div>\n								<div class=\"tile__body\">\n									<h4>Stephen Fleming</h4>\n									<div class=\"card-element justify-content-center\"><span class=\"card-element__item\">CEO &amp; Founder</span></div></div></div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n								<div class=\"tile__media ratio ratio--3by4\"><img src=\"/image/editor-image/1650349567-marketinghead364x3641.png\" alt=\"\" /></div>\n								<div class=\"tile__body\">\n									<h4>James Anderson</h4>\n									<div class=\"card-element justify-content-center\"><span class=\"card-element__item\">Sales/Marketing Head</span></div></div></div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n								<div class=\"tile__media ratio ratio--3by4\"><img src=\"/image/editor-image/1650349739-creativedirector364x3642.png\" alt=\"\" /></div>\n								<div class=\"tile__body\">\n									<h4>Nathan Astle</h4>\n									<div class=\"card-element justify-content-center\"><span class=\"card-element__item\">Creative Director</span></div></div></div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n								<div class=\"tile__media ratio ratio--3by4\"><img src=\"/image/editor-image/1650349751-techlead364x3643.png\" alt=\"\" /></div>\n								<div class=\"tile__body\">\n									<h4>Mark Boucher</h4>\n									<div class=\"card-element justify-content-center\"><span class=\"card-element__item\">Tech Lead </span></div></div></div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n								<div class=\"tile__media ratio ratio--3by4\"><img src=\"/image/editor-image/1650349756-saleshead364x3644.png\" alt=\"\" /></div>\n								<div class=\"tile__body\">\n									<h4>Steve Waugh</h4>\n									<div class=\"card-element justify-content-center\"><span class=\"card-element__item\">Sales/Marketing Head</span></div></div></div></div></div></div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n								<div class=\"tile__media ratio ratio--3by4\"><img src=\"/image/editor-image/1650349761-creativedirector2364x3645.jpg\" alt=\"\" /></div>\n								<div class=\"tile__body\">\n									<h4>Damien Martyn</h4>\n									<div class=\"card-element justify-content-center\"><span class=\"card-element__item\">Creative Director </span></div></div></div></div></div></div></div></div></div></div>\n<div class=\"section section--HowItWorks\">\n	<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<h2>How to start learning with Platform?</h2></div>\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<nav class=\"inline-tabs\">\n			<ul class=\"js-tab list-unstyled\">\n				<li><a href=\"#tab__1\" class=\"current\">01. Search </a></li>\n				<li><a href=\"#tab__2\" class=\"\">02. Book </a> </li>\n				<li><a href=\"#tab__3\" class=\"\">03. Learn </a> </li>\n			</ul></nav>\n		<div class=\"flex-layout-wrapper\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n			<div class=\"tab-container visible\" id=\"tab__1\">\n				<div class=\"flex-layout\">\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/choose-your-tutor.png\" alt=\"\" /></div>\n					<div class=\"flex-layout__content\">\n						<div class=\"content\">\n							<h2>Search through hundreds of best teachers</h2>\n							<p class=\"p-large\">Use filters like price, language, proficiency, subject, location, to\n								search for your preferred teacher</p>\n							<div class=\"step__actions\"> <a href=\"/teachers\" class=\"btn btn--primary\" tabindex=\"0\">Browse\n									Tutors</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\n									<svg class=\"icon icon--play\">\n										<use xlink:href=\"/images/sprite.svg#play\"></use></svg>&nbsp;Watch Video</a> </div></div></div></div></div>\n			<div class=\"tab-container\" id=\"tab__2\">\n				<div class=\"flex-layout\">\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/become-an-expert.png\" alt=\"\" /></div>\n					<div class=\"flex-layout__content\">\n						<div class=\"content\">\n							<h2>Book lessons with the best teacher for you</h2>\n							<p class=\"p-large\">Go through the teacher\'s profile and book a lesson after making the\n								payment.</p>\n							<div class=\"step__actions\"> <a href=\"/teachers\" class=\"btn btn--primary\" tabindex=\"0\">Browse\n									Tutors</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\n									<svg class=\"icon icon--play\">\n										<use xlink:href=\"/images/sprite.svg#play\"></use></svg>&nbsp;Watch Video</a> </div></div></div></div></div>\n			<div class=\"tab-container\" id=\"tab__3\">\n				<div class=\"flex-layout\">\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/book-your-free-lesson.png\" alt=\"\" /></div>\n					<div class=\"flex-layout__content\">\n						<div class=\"content\">\n							<h2>Log in to Start learning</h2>\n							<p class=\"p-large\">Attend online lessons and start learning.</p>\n							<div class=\"step__actions\"> <a href=\"/teachers\" class=\"btn btn--primary\" tabindex=\"0\">Browse\n									Tutors</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\n									<svg class=\"icon icon--play\">\n										<use xlink:href=\"/images/sprite.svg#play\"></use></svg>&nbsp;Watch Video</a> </div></div></div></div></div></div></div></div>'),
(14, 2, 1, 1, '\r\n<div class=\"section\">\r\n	<div class=\"row justify-content-between align-items-xl-center g-5\">\r\n		<div class=\"col-md-6\">\r\n			<div class=\"cms-media\" data-aos=\"fade-up\" data-aos-duration=\"1000\"><img src=\"/image/editor-image/about-whoweare.png\" alt=\"\" /></div></div>\r\n		<div class=\"col-md-6 col-xl-5\">\r\n			<div class=\"cms\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n				<h4 class=\"mb-3\">يبدأ بمن نحن.</h4>\r\n				<h2 class=\"mb-3\">نبني منظمة لمساعدة الناس على التعلم عبر الإنترنت.</h2>\r\n				<p>المنصة هي حل مستضاف ذاتيا يساعد رواد الأعمال على إطلاق دروس خصوصية عبر الإنترنت و\r\n					منصات الاستشارات حيث يمكن للعديد من المعلمين أو الاستشاريين التسجيل وتقديم الفردية أو\r\n					جلسات جماعية عبر الإنترنت للمتعلمين. إنه حل قابل للتطوير بدرجة كبيرة وقابل للتخصيص بالكامل لتلبية\r\n					متطلبات العمل للمستخدمين. تم دمج الحل مسبقا مع Cometchat ، Lesson Space ،\r\n					و Zoom لدعم ميزات مثل دردشة الفيديو ، والسبورة البيضاء ، ولوحة النص ، ومحرر التعليمات البرمجية ، والشاشات المتعددة\r\n					المشاركة ، وما إلى ذلك ، مما يحسن التفاعل بين المعلم والمتعلم أثناء الجلسة عبر الإنترنت.</p></div></div></div></div>\r\n<div class=\"section\">\r\n	<div class=\"why-panel\">\r\n		<div class=\"section__header text-start\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n			<h4>لماذا أخترتنا</h4>\r\n			<h2>التعلم والتحسين دائما من أجل خلق عالم أفضل للأجيال القادمة.</h2></div>\r\n		<div class=\"section__body\">\r\n			<div class=\"counters-list pt-4\">\r\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-1.png\" alt=\"\" /></div><span class=\"counter-card__value\">130 +</span><span class=\"counter-card__label\">اللغات المتاحة\r\n						ليتعلم</span></div>\r\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-2.png\" alt=\"\" /></div><span class=\"counter-card__value\">10 آلاف +</span> <span class=\"counter-card__label\">معلم من 120\r\n						البلدان</span></div>\r\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-3.png\" alt=\"\" /></div><span class=\"counter-card__value\">5 ملايين +</span> <span class=\"counter-card__label\">متعلمون من 180\r\n						البلدان</span></div>\r\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-4.png\" alt=\"\" /></div><span class=\"counter-card__value\">5 ملايين +</span> <span class=\"counter-card__label\">متعلمون من 180\r\n						البلدان</span></div></div></div></div></div>\r\n<div class=\"section section--testimonials\">\r\n	<div class=\"section__header text-start px-4\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n		<div class=\"row align-items-center justify-content-between\">\r\n			<div class=\"col-xl-8\">\r\n				<h4>قيمنا الأساسية</h4>\r\n				<h2>نحن نحب العملاء الذين يفهمون قيمنا</h2></div>\r\n			<div class=\"col-xl-auto\">\r\n				<div class=\"slider-nav\">\r\n					<button type=\"button\" class=\"prev-slide slick-arrow\"></button>\r\n					<button type=\"button\" class=\"next-slide slick-arrow\"></button></div></div></div></div>\r\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n		<div class=\"client-testimonials-list js--testimonials\">\r\n			<div class=\"client-testimonail\">\r\n				<div class=\"client-testimonail__head\">\r\n					<h4><span class=\"num\">01</span>كلمات التقدير</h4></div>\r\n				<div class=\"client-testimonail__body\">\r\n					<p>كان كل حل يستغرق الكثير من الوقت مع ما لا يقل عن 6-8 أشهر ، وقد حان الوقت\r\n						لم يكن لديه. وذلك عندما وجد Wale منصة FATbit. استكشفنا رؤيتنا حول ما\r\n						كان على المنصة أن تقدمها ، ولدهشتنا ، كانت تناسب تماما ما كان يدور في أذهاننا ، وكان لدينا\r\n						عرض توضيحي مباشر للمنصة. انتهزنا الفرصة لاختيار حل لتشغيل رؤيتنا ، ونحن\r\n						لم أندم على ذلك قليلا. حتى الآن ، كانت مباراة جيدة للفريق.</p></div>\r\n				<div class=\"client-testimonail__foot\">\r\n					<h6 class=\"client-info\">السيد تشين وي سونغ</h6></div></div>\r\n			<div class=\"client-testimonail\">\r\n				<div class=\"client-testimonail__head\">\r\n					<h4><span class=\"num\">02</span>كلمات التقدير</h4></div>\r\n				<div class=\"client-testimonail__body\">\r\n					<p>نحن امتياز مدرسة لغة من الطوب وقذائف الهاون. بمجرد إغلاق COVID-19\r\n						حدث نزول كنا بحاجة إلى الانتقال عبر الإنترنت. توفر المنصة منصة حديثة جدا لنا\r\n						لا تنفذ تعلم اللغة فحسب ، بل جميع أنواع التعلم. </p></div>\r\n				<div class=\"client-testimonail__foot\">\r\n					<h6 class=\"client-info\">راي دي أنجيلو</h6></div></div>\r\n			<div class=\"client-testimonail\">\r\n				<div class=\"client-testimonail__head\">\r\n					<h4><span class=\"num\">03</span>كلمات التقدير</h4></div>\r\n				<div class=\"client-testimonail__body\">\r\n					<p>كانت رحلتي مع FATbit طويلة. استغرق الأمر ساعات وصبرا لإنجاز الموقع\r\n						والتوقعات الدقيقة التي طلبتها. FATbit لا تستسلم أبدا ، فهي دائما ما تقدم ما تقدمه\r\n						قل بغض النظر عن مقدار العمل الإضافي الذي يقضونه في المشروع والعميل. المطور الخاص بي Eddie ، بلدي\r\n						ذهب الاتصال بالمبيعات Kesa إلى أكثر من نداء الواجب للبقاء على رأس هذا المشروع. انتهاء\r\n						نتيجة; موقع جميل وعملي بقوة سيغير طريقة التعلم في العالم\r\n						لغة جديدة. شكرا لك FATbit.</p></div>\r\n				<div class=\"client-testimonail__foot\">\r\n					<h6 class=\"client-info\">كيلي</h6></div></div>\r\n			<div class=\"client-testimonail\">\r\n				<div class=\"client-testimonail__head\">\r\n					<h4><span class=\"num\">04</span>كلمات التقدير</h4></div>\r\n				<div class=\"client-testimonail__body\">\r\n					<p>أنا أستخدم لوحة القيادة الخاصة بمنصة W3mentors دون أي تعقيدات ويمكن لعملائي استخدام بلدي\r\n						منصة بطريقة سهلة.</p></div>\r\n				<div class=\"client-testimonail__foot\">\r\n					<h6 class=\"client-info\">ياسين الطيبي</h6></div></div></div></div></div>\r\n<div class=\"section\">\r\n	<div class=\"grey-wrapper\">\r\n		<div class=\"section__header text-start\">\r\n			<div class=\"row align-items-center justify-content-between gap-3\">\r\n				<div class=\"col-xl-8\">\r\n					<h4>مهمتنا ورؤيتنا</h4>\r\n					<h2>تعرف على مهمتنا ورؤيتنا</h2></div>\r\n				<div class=\"col-xl-auto\"><a href=\"/contact\" class=\"btn btn--primary btn--large\">اتصل بنا</a></div></div></div>\r\n		<div class=\"section__body\">\r\n			<div class=\"accordion width\" id=\"hrAccordion\">\r\n				<div class=\"card\">\r\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseOne\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">مهمتنا</span></div>\r\n					<div id=\"collapseOne\" class=\"collapse show width\" data-parent=\"#hrAccordion\">\r\n						<div class=\"card-body\">\r\n							<div class=\"cms-panel\">\r\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\r\n								<div class=\"cms-panel__content\">\r\n									<h2>هدفنا</h2>\r\n									<p>مهمتنا هي مساعدة رواد الأعمال والمعلمين على إنشاء دروس خصوصية خاصة بهم عبر الإنترنت\r\n										منصات مثل Verbling و Preply و Cambly. نحن نساعدهم على الوصول إلى ذروة\r\n										حياتهم المهنية من خلال تمكينهم من إطلاق منصة التدريس الخاصة بهم باستخدام\r\n										حل جاهز.</p></div></div></div></div></div>\r\n				<div class=\"card\">\r\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseTwo\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">إلهامنا ومراقبتنا</span></div>\r\n					<div id=\"collapseTwo\" class=\"collapse width\" data-parent=\"#hrAccordion\">\r\n						<div class=\"card-body\">\r\n							<div class=\"cms-panel\">\r\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\r\n								<div class=\"cms-panel__content\">\r\n									<h2>هدفنا</h2>\r\n									<p>نحن ، كوننا رواد وخبراء في الصناعة ، نقدم حلنا الجاهز لتكنولوجيا التعليم ،\r\n										لمساعدة رواد الأعمال على بدء أعمالهم التعليمية هدفنا هو تقديم\r\n										عملية سهلة وخالية من المتاعب بالنسبة لهم لدخول السوق ويصبحوا روادا.</p></div></div></div></div></div>\r\n				<div class=\"card\">\r\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseThree\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">هدفنا</span></div>\r\n					<div id=\"collapseThree\" class=\"collapse width\" data-parent=\"#hrAccordion\">\r\n						<div class=\"card-body\">\r\n							<div class=\"cms-panel\">\r\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\r\n								<div class=\"cms-panel__content\">\r\n									<h2>هدفنا</h2>\r\n									<p>Nam libero tempore, cum soluta nobis est eligendi optio cumque nihil impedit quo\r\n										ناقص معرف quod maxime placeat facere possimus, omnis voluptas assumenda est,\r\n										omnis dolor repellendus temporibus autem.</p></div></div></div></div></div></div></div></div></div>\r\n<div class=\"section\">\r\n	<div class=\"section__header d-flex gap-5 text-start\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n		<div class=\"row justify-content-between pb-4 g-3\">\r\n			<div class=\"col-xl-3\">\r\n				<h6>شعب</h6>\r\n				<h2>تعرف على فريق الخبراء لدينا</h2></div>\r\n			<div class=\"col-xl-8\">\r\n				<p class=\"p-xlarge m-0\">يتمتع أعضاء فريقنا ذوو المعرفة العالية والخبرة بإبداع ،\r\n					طبيعة تعاونية وملتزمة تمكن المنصة من أن تكون شركة فعالة للغاية.</p></div></div></div>\r\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n		<div class=\"teacher-wrapper\">\r\n			<div class=\"slider d-block slider-onefifth slider-onefifth-js\">\r\n				<div class=\"slider__item\">\r\n					<div class=\"tile-cover\">\r\n						<div class=\"tile\">\r\n							<div class=\"tile__head\">\r\n								<div class=\"tile__media ratio ratio--3by4\"><img src=\"/image/editor-image/1650349417-ceo364x364.png\" alt=\"\" /></div>\r\n								<div class=\"tile__body\">\r\n									<h4>ستيفن فليمنج</h4>\r\n									<div class=\"card-element justify-content-center\"><span class=\"card-element__item\">الرئيس التنفيذي والمؤسس</span></div></div></div></div></div></div>\r\n				<div class=\"slider__item\">\r\n					<div class=\"tile-cover\">\r\n						<div class=\"tile\">\r\n							<div class=\"tile__head\">\r\n								<div class=\"tile__media ratio ratio--3by4\"><img src=\"/image/editor-image/1650349567-marketinghead364x3641.png\" alt=\"\" /></div>\r\n								<div class=\"tile__body\">\r\n									<h4>جيمس أندرسون</h4>\r\n									<div class=\"card-element justify-content-center\"><span class=\"card-element__item\">رئيس المبيعات / التسويق</span></div></div></div></div></div></div>\r\n				<div class=\"slider__item\">\r\n					<div class=\"tile-cover\">\r\n						<div class=\"tile\">\r\n							<div class=\"tile__head\">\r\n								<div class=\"tile__media ratio ratio--3by4\"><img src=\"/image/editor-image/1650349739-creativedirector364x3642.png\" alt=\"\" /></div>\r\n								<div class=\"tile__body\">\r\n									<h4>ناثان أستل</h4>\r\n									<div class=\"card-element justify-content-center\"><span class=\"card-element__item\">المدير الإبداعي</span></div></div></div></div></div></div>\r\n				<div class=\"slider__item\">\r\n					<div class=\"tile-cover\">\r\n						<div class=\"tile\">\r\n							<div class=\"tile__head\">\r\n								<div class=\"tile__media ratio ratio--3by4\"><img src=\"/image/editor-image/1650349751-techlead364x3643.png\" alt=\"\" /></div>\r\n								<div class=\"tile__body\">\r\n									<h4>مارك باوتشر</h4>\r\n									<div class=\"card-element justify-content-center\"><span class=\"card-element__item\">القائد التقني </span></div></div></div></div></div></div>\r\n				<div class=\"slider__item\">\r\n					<div class=\"tile-cover\">\r\n						<div class=\"tile\">\r\n							<div class=\"tile__head\">\r\n								<div class=\"tile__media ratio ratio--3by4\"><img src=\"/image/editor-image/1650349756-saleshead364x3644.png\" alt=\"\" /></div>\r\n								<div class=\"tile__body\">\r\n									<h4>ستيف وو</h4>\r\n									<div class=\"card-element justify-content-center\"><span class=\"card-element__item\">رئيس المبيعات / التسويق</span></div></div></div></div></div></div>\r\n				<div class=\"slider__item\">\r\n					<div class=\"tile-cover\">\r\n						<div class=\"tile\">\r\n							<div class=\"tile__head\">\r\n								<div class=\"tile__media ratio ratio--3by4\"><img src=\"/image/editor-image/1650349761-creativedirector2364x3645.jpg\" alt=\"\" /></div>\r\n								<div class=\"tile__body\">\r\n									<h4>داميان مارتين</h4>\r\n									<div class=\"card-element justify-content-center\"><span class=\"card-element__item\">المدير الإبداعي </span></div></div></div></div></div></div></div></div></div></div>\r\n<div class=\"section section--HowItWorks\">\r\n	<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n		<h2>كيف تبدأ التعلم باستخدام المنصة؟</h2></div>\r\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n		<nav class=\"inline-tabs\">\r\n			<ul class=\"js-tab list-unstyled\">\r\n				<li><a href=\"#tab__1\" class=\"current\">01. البحث </a></li>\r\n				<li><a href=\"#tab__2\" class=\"\">02. كتاب </a> </li>\r\n				<li><a href=\"#tab__3\" class=\"\">03. تعلم </a> </li>\r\n			</ul></nav>\r\n		<div class=\"flex-layout-wrapper\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n			<div class=\"tab-container visible\" id=\"tab__1\">\r\n				<div class=\"flex-layout\">\r\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/choose-your-tutor.png\" alt=\"\" /></div>\r\n					<div class=\"flex-layout__content\">\r\n						<div class=\"content\">\r\n							<h2>ابحث في المئات من أفضل المعلمين</h2>\r\n							<p class=\"p-large\">استخدم عوامل تصفية مثل السعر واللغة والكفاءة والموضوع والموقع وإلى\r\n								ابحث عن معلمك المفضل</p>\r\n							<div class=\"step__actions\"><a href=\"/teachers\" class=\"btn btn--primary\" tabindex=\"0\">تصفح\r\n									المعلمون</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\r\n									<svg class=\"icon icon--play\">\r\n										<use xlink:href=\"/images/sprite.svg#play\"></use></svg>&nbsp;شاهد الفيديو</a> </div></div></div></div></div>\r\n			<div class=\"tab-container\" id=\"tab__2\">\r\n				<div class=\"flex-layout\">\r\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/become-an-expert.png\" alt=\"\" /></div>\r\n					<div class=\"flex-layout__content\">\r\n						<div class=\"content\">\r\n							<h2>احجز الدروس مع أفضل معلم لك</h2>\r\n							<p class=\"p-large\">راجع ملف تعريف المعلم واحجز درسا بعد إجراء\r\n								دفع.</p>\r\n							<div class=\"step__actions\"><a href=\"/teachers\" class=\"btn btn--primary\" tabindex=\"0\">تصفح\r\n									المعلمون</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\r\n									<svg class=\"icon icon--play\">\r\n										<use xlink:href=\"/images/sprite.svg#play\"></use></svg>&nbsp;شاهد الفيديو</a> </div></div></div></div></div>\r\n			<div class=\"tab-container\" id=\"tab__3\">\r\n				<div class=\"flex-layout\">\r\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/book-your-free-lesson.png\" alt=\"\" /></div>\r\n					<div class=\"flex-layout__content\">\r\n						<div class=\"content\">\r\n							<h2>قم بتسجيل الدخول لبدء التعلم</h2>\r\n							<p class=\"p-large\">احضر الدروس عبر الإنترنت وابدأ التعلم.</p>\r\n							<div class=\"step__actions\"><a href=\"/teachers\" class=\"btn btn--primary\" tabindex=\"0\">تصفح\r\n									المعلمون</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\r\n									<svg class=\"icon icon--play\">\r\n										<use xlink:href=\"/images/sprite.svg#play\"></use></svg>&nbsp;شاهد الفيديو</a> </div></div></div></div></div></div></div></div>');
INSERT INTO `tbl_content_pages_block_lang` (`cpblocklang_id`, `cpblocklang_lang_id`, `cpblocklang_cpage_id`, `cpblocklang_block_id`, `cpblocklang_text`) VALUES
(16, 3, 1, 1, '\r\n<div class=\"section\">\r\n	<div class=\"row justify-content-between align-items-xl-center g-5\">\r\n		<div class=\"col-md-6\">\r\n			<div class=\"cms-media\" data-aos=\"fade-up\" data-aos-duration=\"1000\"><img src=\"/image/editor-image/about-whoweare.png\" alt=\"\" /></div></div>\r\n		<div class=\"col-md-6 col-xl-5\">\r\n			<div class=\"cms\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n				<h4 class=\"mb-3\">Comienza con Qui&eacute;nes Somos.</h4>\r\n				<h2 class=\"mb-3\">Construimos una organización para ayudar a las personas a aprender en línea.</h2>\r\n				<p>La plataforma es una solución autoalojada que ayuda a los emprendedores a lanzar tutorías en línea y\r\n					plataformas de consulta en las que varios tutores o consultores pueden registrarse y realizar consultas individuales o\r\n					Sesiones grupales en línea para los alumnos. Es una solución altamente escalable y totalmente personalizable para cumplir\r\n					los requisitos comerciales de los usuarios. La solución está preintegrada con Cometchat, Lesson Space,\r\n					y Zoom para admitir funciones como chat de video, pizarra, teclado de texto, editor de código, pantalla múltiple\r\n					compartir, etc., lo que mejora la interacción entre el tutor y el alumno durante una sesión en línea.</p></div></div></div></div>\r\n<div class=\"section\">\r\n	<div class=\"why-panel\">\r\n		<div class=\"section__header text-start\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n			<h4>¿Por qu&eacute; elegirnos?</h4>\r\n			<h2>Aprender y mejorar siempre para crear un mundo mejor para las generaciones venideras.</h2></div>\r\n		<div class=\"section__body\">\r\n			<div class=\"counters-list pt-4\">\r\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-1.png\" alt=\"\" /></div><span class=\"counter-card__value\">130 +</span><span class=\"counter-card__label\">Idiomas disponibles\r\n						Aprender</span></div>\r\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-2.png\" alt=\"\" /></div><span class=\"counter-card__value\">10k +</span><span class=\"counter-card__label\">Profesores desde 120\r\n						Países</span></div>\r\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-3.png\" alt=\"\" /></div><span class=\"counter-card__value\">5M +</span><span class=\"counter-card__label\">Aprendices de 180\r\n						Países</span></div>\r\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-4.png\" alt=\"\" /></div><span class=\"counter-card__value\">5M +</span><span class=\"counter-card__label\">Aprendices de 180\r\n						Países</span></div></div></div></div></div>\r\n<div class=\"section section--testimonials\">\r\n	<div class=\"section__header text-start px-4\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n		<div class=\"row align-items-center justify-content-between\">\r\n			<div class=\"col-xl-8\">\r\n				<h4>Nuestros Valores Fundamentales</h4>\r\n				<h2>Nos encantan los clientes que entienden nuestros valores</h2></div>\r\n			<div class=\"col-xl-auto\">\r\n				<div class=\"slider-nav\">\r\n					<button type=\"button\" class=\"prev-slide slick-arrow\"></button>\r\n					<button type=\"button\" class=\"next-slide slick-arrow\"></button></div></div></div></div>\r\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n		<div class=\"client-testimonials-list js--testimonials\">\r\n			<div class=\"client-testimonail\">\r\n				<div class=\"client-testimonail__head\">\r\n					<h4><span class=\"num\">01</span>Palabras de agradecimiento</h4></div>\r\n				<div class=\"client-testimonail__body\">\r\n					<p>Cada solución tomaba demasiado tiempo con nada menos que 6 a 8 meses, y era hora de que\r\n						no tenía. Fue entonces cuando Wale encontró la plataforma de FATbit. Exploramos nuestra visión en torno a lo que\r\n						Platform tenía para ofrecer, y para nuestra sorpresa, se ajustaba exactamente a lo que teníamos en mente, y teníamos un\r\n						demostración en vivo de la plataforma. Aprovechamos la oportunidad de encontrar una solución para llevar a cabo nuestra visión, y\r\n						No me he arrepentido nada. Hasta ahora, ha sido bueno para el equipo.</p></div>\r\n				<div class=\"client-testimonail__foot\">\r\n					<h6 class=\"client-info\">Sr. Chin Wei Seong</h6></div></div>\r\n			<div class=\"client-testimonail\">\r\n				<div class=\"client-testimonail__head\">\r\n					<h4><span class=\"num\">02</span>Palabras de agradecimiento</h4></div>\r\n				<div class=\"client-testimonail__body\">\r\n					<p>Somos una franquicia de escuelas de idiomas de ubicación física física. Una vez que el COVID-19 cerró\r\n						Sucedió que necesitábamos movernos en línea. La plataforma proporciona una plataforma muy moderna para que podamos\r\n						Ejecutar no solo el aprendizaje de idiomas, sino todo tipo de aprendizaje. </p></div>\r\n				<div class=\"client-testimonail__foot\">\r\n					<h6 class=\"client-info\">Ray D Angelo</h6></div></div>\r\n			<div class=\"client-testimonail\">\r\n				<div class=\"client-testimonail__head\">\r\n					<h4><span class=\"num\">03</span>Palabras de agradecimiento</h4></div>\r\n				<div class=\"client-testimonail__body\">\r\n					<p>Mi viaje con FATbit ha sido largo. Se necesitaron horas y paciencia para terminar el sitio web\r\n						y a las expectativas exactas que pedí. FATbit nunca se rinde, siempre entregan lo que\r\n						Digamos que no importa cuántas horas extras dediquen al proyecto y al cliente. Mi desarrollador Eddie, mi\r\n						El contacto de ventas Kesa hizo todo lo posible para mantenerse al tanto de este proyecto. Fin\r\n						resultado; Un sitio hermoso y poderosamente funcional que cambiará la forma de aprender en el mundo\r\n						Un nuevo idioma. Gracias FATbit.</p></div>\r\n				<div class=\"client-testimonail__foot\">\r\n					<h6 class=\"client-info\">Kelly</h6></div></div>\r\n			<div class=\"client-testimonail\">\r\n				<div class=\"client-testimonail__head\">\r\n					<h4><span class=\"num\">04</span>Palabras de agradecimiento</h4></div>\r\n				<div class=\"client-testimonail__body\">\r\n					<p>Estoy usando el panel de control de la plataforma W3mentors sin ninguna complicación y mis clientes pueden usar mi\r\n						plataforma de manera fácil.</p></div>\r\n				<div class=\"client-testimonail__foot\">\r\n					<h6 class=\"client-info\">Yacine Tayebi</h6></div></div></div></div></div>\r\n<div class=\"section\">\r\n	<div class=\"grey-wrapper\">\r\n		<div class=\"section__header text-start\">\r\n			<div class=\"row align-items-center justify-content-between gap-3\">\r\n				<div class=\"col-xl-8\">\r\n					<h4>Nuestra misión y visión</h4>\r\n					<h2>Conozca nuestra misión y visión</h2></div>\r\n				<div class=\"col-xl-auto\"><a href=\"/contact\" class=\"btn btn--primary btn--large\">Contáctenos</a></div></div></div>\r\n		<div class=\"section__body\">\r\n			<div class=\"accordion width\" id=\"hrAccordion\">\r\n				<div class=\"card\">\r\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseOne\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">NUESTRA MISIÓN</span></div>\r\n					<div id=\"collapseOne\" class=\"collapse show width\" data-parent=\"#hrAccordion\">\r\n						<div class=\"card-body\">\r\n							<div class=\"cms-panel\">\r\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\r\n								<div class=\"cms-panel__content\">\r\n									<h2>Nuestro objetivo</h2>\r\n									<p>Nuestra misión es ayudar a emprendedores y tutores a crear su propia tutoría en línea\r\n										plataformas como Verbling, Preply y Cambly. Les ayudamos a alcanzar la cima de la\r\n										su carrera profesional, permiti&eacute;ndoles lanzar su propia plataforma de tutoría utilizando nuestro\r\n										solución lista para usar.</p></div></div></div></div></div>\r\n				<div class=\"card\">\r\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseTwo\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">Nuestra Inspiración &amp; Visión</span></div>\r\n					<div id=\"collapseTwo\" class=\"collapse width\" data-parent=\"#hrAccordion\">\r\n						<div class=\"card-body\">\r\n							<div class=\"cms-panel\">\r\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\r\n								<div class=\"cms-panel__content\">\r\n									<h2>Nuestro objetivo</h2>\r\n									<p>Nosotros, siendo los líderes y expertos de la industria, proporcionamos nuestra solución de tecnología educativa llave en mano,\r\n										para ayudar a los emprendedores a iniciar sus negocios de tutoría. Nuestro objetivo es ofrecer una\r\n										Proceso fácil y sin complicaciones para que ingresen al mercado y se conviertan en pioneros.</p></div></div></div></div></div>\r\n				<div class=\"card\">\r\n					<div class=\"card-header\" data-toggle=\"collapse\" data-target=\"#collapseThree\"><span class=\"circle-arrow\"></span><span class=\"tab-title\">Nuestro objetivo</span></div>\r\n					<div id=\"collapseThree\" class=\"collapse width\" data-parent=\"#hrAccordion\">\r\n						<div class=\"card-body\">\r\n							<div class=\"cms-panel\">\r\n								<div class=\"cms-panel__media\"><img src=\"/image/editor-image/our-goal.png\" alt=\"\" /></div>\r\n								<div class=\"cms-panel__content\">\r\n									<h2>Nuestro objetivo</h2>\r\n									<p>Nam libero tempore, cum soluta nobis est eligendi optio cumque nihil impedit quo\r\n										minus id quod maxime placeat facere possimus, omnis voluptas assumenda est,\r\n										omnis dolor repellendus Temporibus autem.</p></div></div></div></div></div></div></div></div></div>\r\n<div class=\"section\">\r\n	<div class=\"section__header d-flex gap-5 text-start\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n		<div class=\"row justify-content-between pb-4 g-3\">\r\n			<div class=\"col-xl-3\">\r\n				<h6>Gente</h6>\r\n				<h2>Conozca a nuestro equipo de expertos</h2></div>\r\n			<div class=\"col-xl-8\">\r\n				<p class=\"p-xlarge m-0\">Los miembros de nuestro equipo, altamente informados y experimentados, tienen un enfoque creativo,\r\n					carácter colaborativo y comprometido que permite a Platform ser una empresa altamente efectiva.</p></div></div></div>\r\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n		<div class=\"teacher-wrapper\">\r\n			<div class=\"slider d-block slider-onefifth slider-onefifth-js\">\r\n				<div class=\"slider__item\">\r\n					<div class=\"tile-cover\">\r\n						<div class=\"tile\">\r\n							<div class=\"tile__head\">\r\n								<div class=\"tile__media ratio ratio--3by4\"><img src=\"/image/editor-image/1650349417-ceo364x364.png\" alt=\"\" /></div>\r\n								<div class=\"tile__body\">\r\n									<h4>Stephen Fleming</h4>\r\n									<div class=\"card-element justify-content-center\"><span class=\"card-element__item\">CEO &amp; Fundador</span></div></div></div></div></div></div>\r\n				<div class=\"slider__item\">\r\n					<div class=\"tile-cover\">\r\n						<div class=\"tile\">\r\n							<div class=\"tile__head\">\r\n								<div class=\"tile__media ratio ratio--3by4\"><img src=\"/image/editor-image/1650349567-marketinghead364x3641.png\" alt=\"\" /></div>\r\n								<div class=\"tile__body\">\r\n									<h4>James Anderson</h4>\r\n									<div class=\"card-element justify-content-center\"><span class=\"card-element__item\">Jefe de Ventas/Marketing</span></div></div></div></div></div></div>\r\n				<div class=\"slider__item\">\r\n					<div class=\"tile-cover\">\r\n						<div class=\"tile\">\r\n							<div class=\"tile__head\">\r\n								<div class=\"tile__media ratio ratio--3by4\"><img src=\"/image/editor-image/1650349739-creativedirector364x3642.png\" alt=\"\" /></div>\r\n								<div class=\"tile__body\">\r\n									<h4>Nathan Astle</h4>\r\n									<div class=\"card-element justify-content-center\"><span class=\"card-element__item\">Director Creativo</span></div></div></div></div></div></div>\r\n				<div class=\"slider__item\">\r\n					<div class=\"tile-cover\">\r\n						<div class=\"tile\">\r\n							<div class=\"tile__head\">\r\n								<div class=\"tile__media ratio ratio--3by4\"><img src=\"/image/editor-image/1650349751-techlead364x3643.png\" alt=\"\" /></div>\r\n								<div class=\"tile__body\">\r\n									<h4>Marcos Boucher</h4>\r\n									<div class=\"card-element justify-content-center\"><span class=\"card-element__item\">Líder T&eacute;cnico </span></div></div></div></div></div></div>\r\n				<div class=\"slider__item\">\r\n					<div class=\"tile-cover\">\r\n						<div class=\"tile\">\r\n							<div class=\"tile__head\">\r\n								<div class=\"tile__media ratio ratio--3by4\"><img src=\"/image/editor-image/1650349756-saleshead364x3644.png\" alt=\"\" /></div>\r\n								<div class=\"tile__body\">\r\n									<h4>Steve Waugh</h4>\r\n									<div class=\"card-element justify-content-center\"><span class=\"card-element__item\">Jefe de Ventas/Marketing</span></div></div></div></div></div></div>\r\n				<div class=\"slider__item\">\r\n					<div class=\"tile-cover\">\r\n						<div class=\"tile\">\r\n							<div class=\"tile__head\">\r\n								<div class=\"tile__media ratio ratio--3by4\"><img src=\"/image/editor-image/1650349761-creativedirector2364x3645.jpg\" alt=\"\" /></div>\r\n								<div class=\"tile__body\">\r\n									<h4>Damien Martyn</h4>\r\n									<div class=\"card-element justify-content-center\"><span class=\"card-element__item\">Director Creativo </span></div></div></div></div></div></div></div></div></div></div>\r\n<div class=\"section section--HowItWorks\">\r\n	<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n		<h2>¿Cómo empezar a aprender con Platform?</h2></div>\r\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n		<nav class=\"inline-tabs\">\r\n			<ul class=\"js-tab list-unstyled\">\r\n				<li><a href=\"#tab__1\" class=\"current\">01. Buscar </a></li>\r\n				<li><a href=\"#tab__2\" class=\"\">02. Reservar </a> </li>\r\n				<li><a href=\"#tab__3\" class=\"\">03. Aprender </a> </li>\r\n			</ul></nav>\r\n		<div class=\"flex-layout-wrapper\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n			<div class=\"tab-container visible\" id=\"tab__1\">\r\n				<div class=\"flex-layout\">\r\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/choose-your-tutor.png\" alt=\"\" /></div>\r\n					<div class=\"flex-layout__content\">\r\n						<div class=\"content\">\r\n							<h2>Busca entre cientos de los mejores profesores</h2>\r\n							<p class=\"p-large\">Utilice filtros como precio, idioma, competencia, tema, ubicación, para\r\n								Busca a tu profesor preferido</p>\r\n							<div class=\"step__actions\"><a href=\"/teachers\" class=\"btn btn--primary\" tabindex=\"0\">Hojear\r\n									Tutores</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\r\n									<svg class=\"icon icon--play\">\r\n										<use xlink:href=\"/images/sprite.svg#play\"></use></svg>&nbsp;Ver video</a> </div></div></div></div></div>\r\n			<div class=\"tab-container\" id=\"tab__2\">\r\n				<div class=\"flex-layout\">\r\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/become-an-expert.png\" alt=\"\" /></div>\r\n					<div class=\"flex-layout__content\">\r\n						<div class=\"content\">\r\n							<h2>Reserva clases con el mejor profesor para ti</h2>\r\n							<p class=\"p-large\">Revisa el perfil del profesor y reserva una lección despu&eacute;s de hacer el\r\n								pago.</p>\r\n							<div class=\"step__actions\"><a href=\"/teachers\" class=\"btn btn--primary\" tabindex=\"0\">Hojear\r\n									Tutores</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\r\n									<svg class=\"icon icon--play\">\r\n										<use xlink:href=\"/images/sprite.svg#play\"></use></svg>&nbsp;Ver video</a> </div></div></div></div></div>\r\n			<div class=\"tab-container\" id=\"tab__3\">\r\n				<div class=\"flex-layout\">\r\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/book-your-free-lesson.png\" alt=\"\" /></div>\r\n					<div class=\"flex-layout__content\">\r\n						<div class=\"content\">\r\n							<h2>Inicie sesión para comenzar a aprender</h2>\r\n							<p class=\"p-large\">Asiste a clases en línea y empieza a aprender.</p>\r\n							<div class=\"step__actions\"><a href=\"/teachers\" class=\"btn btn--primary\" tabindex=\"0\">Hojear\r\n									Tutores</a>&nbsp;<a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\" class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">&nbsp;\r\n									<svg class=\"icon icon--play\">\r\n										<use xlink:href=\"/images/sprite.svg#play\"></use></svg>&nbsp;Ver video</a> </div></div></div></div></div></div></div></div>');
INSERT INTO `tbl_extra_pages_lang` (`epagelang_epage_id`, `epagelang_lang_id`, `epage_label`, `epage_content`) VALUES
(4, 1, 'Contact Banner', '\r\n<div class=\"intro-head\">\r\n	<h6 class=\"small-title\">Contact Us</h6>\r\n	<h1>Want to get in touch?<br />\r\n		We would love to hear from you.</h1></div>'),
(4, 2, 'اتصل بنر', '\r\n<div class=\"intro-head\">\r\n	<h6 class=\"small-title\">اتصل بنا</h6>\r\n	<h1>هل تريد التواصل؟<br />\r\n		نود أن نسمع منك.</h1></div>'),
(4, 3, 'Banner de contacto', '\r\n<div class=\"intro-head\">\r\n	<h6 class=\"small-title\">Contáctenos</h6>\r\n	<h1>¿Quieres ponerte en contacto?<br />\r\n		Nos encantaría saber de ti.</h1></div>');
INSERT INTO `tbl_extra_pages_lang` (`epagelang_epage_id`, `epagelang_lang_id`, `epage_label`, `epage_content`) VALUES
(9, 1, 'Apply to teach static banner section', '\r\n<div class=\"container container--xxl\">\r\n	<div class=\"cta-block bg-gradiant\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n		<div class=\"cta-block__content\">\r\n			<div class=\"content\">\r\n				<h2>Do you want to become a teacher on w3mentors?</h2>\r\n				<p>Connect with thousands of learners around the world and teach from your living room</p>\r\n				<button class=\"btn btn--primary applytoteach\">Apply Now</button></div></div>\r\n		<div class=\"cta-block__media\">\r\n			<picture> <img srcset=\"/image/editor-image/cta-block-img.png\" alt=\"\" /> </picture></div></div></div>'),
(9, 2, 'تقدم بطلب لتدريس قسم الشعار الثابت', '\r\n<div class=\"container container--xxl\">\r\n	<div class=\"cta-block bg-gradiant\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n		<div class=\"cta-block__content\">\r\n			<div class=\"content\">\r\n				<h2>هل تريد أن تصبح مدرسا على Yo! مدرب؟</h2>\r\n				<p>تواصل مع آلاف المتعلمين حول العالم وقم بالتدريس من غرفة المعيشة الخاصة بك</p>\r\n				<button class=\"btn btn--primary applytoteach\">قدم الآن</button></div></div>\r\n		<div class=\"cta-block__media\">\r\n			<picture><img srcset=\"/image/editor-image/cta-block-img.png\" alt=\"\" /> </picture></div></div></div>'),
(9, 3, 'Aplicar para enseñar la sección de banner estático', '\r\n<div class=\"container container--xxl\">\r\n	<div class=\"cta-block bg-gradiant\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n		<div class=\"cta-block__content\">\r\n			<div class=\"content\">\r\n				<h2>¿Quieres convertirte en profesor en Yo! ¿Coche?</h2>\r\n				<p>Con&eacute;ctese con miles de estudiantes de todo el mundo y enseñe desde su sala de estar</p>\r\n				<button class=\"btn btn--primary applytoteach\">Aplicar ahora</button></div></div>\r\n		<div class=\"cta-block__media\">\r\n			<picture><img srcset=\"/image/editor-image/cta-block-img.png\" alt=\"\" /> </picture></div></div></div>');
INSERT INTO `tbl_extra_pages` (`epage_id`, `epage_identifier`, `epage_block_type`, `epage_type`, `epage_editable`, `epage_active`, `epage_default_content`, `epage_order`) VALUES
(26, 'Got Questions Section', 26, 3, 1, 1, '<div class=\"cms-cta\"> \n <div class=\"cms-cta__content\"> \n <h2> Got questions?\n <span>Request a call-back</span> </h2> <a href=\"/contact\" class=\"btn btn--primary\">Contact us</a> </div> \n <div class=\"cms-cta__media\"> <img src=\"/image/editor-image/cta-img.png\" alt=\"Contact\" /> </div></div>', 0);
INSERT INTO `tbl_extra_pages_lang` (`epagelang_epage_id`, `epagelang_lang_id`, `epage_label`, `epage_content`) VALUES
