INSERT INTO `tbl_extra_pages_lang` (`epagelang_epage_id`, `epagelang_lang_id`, `epage_label`, `epage_content`) VALUES
(22, 1, 'Creating A Community Section', '\r\n<section class=\"section\">\r\n	<div class=\"container container--xxl\">\r\n		<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n			<h2>Creating a community of life long learners.</h2></div>\r\n		<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n			<div class=\"stats-wrapper\">\r\n				<div class=\"stats-listing\">\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"500\">0</span><i>+</i></span><span class=\"stats__label\">Learners &amp; Teachers</span></div>\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"800\">0</span><i>+</i></span><span class=\"stats__label\">Total Courses</span></div>\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"1000\">0</span><i>+</i></span><span class=\"stats__label\">Total Posts</span></div>\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"100\">0</span><i>+</i></span><span class=\"stats__label\">Registered Users</span></div></div></div></div></div></section>'),
(22, 2, 'إنشاء قسم المجتمع', '\r\n<section class=\"section\">\r\n	<div class=\"container container--xxl\">\r\n		<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n			<h2>خلق مجتمع من المتعلمين مدى الحياة.</h2></div>\r\n		<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n			<div class=\"stats-wrapper\">\r\n				<div class=\"stats-listing\">\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"500\">0</span><i>+</i></span><span class=\"stats__label\">متعلمون ومعلمون</span></div>\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"800\">0</span><i>+</i></span><span class=\"stats__label\">إجمالي الدورات</span></div>\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"1000\">0</span><i>+</i></span><span class=\"stats__label\">إجمالي المشاركات</span></div>\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"100\">0</span><i>+</i></span><span class=\"stats__label\">مستخدم مسجل</span></div></div></div></div></div></section>'),
(22, 3, 'Creación de una sección de la comunidad', '\r\n<section class=\"section\">\r\n	<div class=\"container container--xxl\">\r\n		<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n			<h2>Crear una comunidad de aprendices a lo largo de toda la vida.</h2></div>\r\n		<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\r\n			<div class=\"stats-wrapper\">\r\n				<div class=\"stats-listing\">\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"500\">0</span><i>+</i></span> <span class=\"stats__label\">Aprendices y Profesores</span></div>\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"800\">0</span><i>+</i></span><span class=\"stats__label\">Cursos en total</span></div>\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"1000\">0</span><i>+</i></span> <span class=\"stats__label\">Publicaciones Totales</span></div>\r\n					<div class=\"stats\"><span class=\"stats__number\"><span data-target=\"100\">0</span><i>+</i></span> <span class=\"stats__label\">Usuarios Registrados</span></div></div></div></div></div></section>');
