(5, 2, 'اتصل بالقسم الأيسر', '<div class=\"col-md-5 col-lg-4\">\n	<div class=\"contact-info\">\n		<div class=\"contact-info__row\">\n			<div class=\"contact__icon\">\n				<svg class=\"icon icon--address\">\n\n					<use xlink:href=\"/images/sprite.svg#address\"></use>\n				</svg>\n			</div>\n			<div class=\"contact__content\">\n				<h6>عنوان</h6>\n				<p>مركز التجارة الدولية 3 ، القطاع 67 ،<br />\n					صاحب زاده أجيت سينغ ناجار,<br />\n					البنجاب 160062</p>\n			</div>\n		</div>\n		<div class=\"contact-info__row\">\n			<div class=\"contact__icon\">\n				<svg class=\"icon icon--mail\">\n\n					<use xlink:href=\"/images/sprite.svg#mail\"></use>\n				</svg>\n			</div>\n			<div class=\"contact__content\">\n				<h6>البريد الإلكتروني</h6>\n				<p>sales@fatbit.com <br />\n					sales@fatbit.com</p>\n			</div>\n		</div>\n		<div class=\"contact-info__row\">\n			<div class=\"contact__icon\">\n				<svg class=\"icon icon--telephone\">\n\n					<use xlink:href=\"/images/sprite.svg#telephone\"></use>\n				</svg>\n			</div>\n			<div class=\"contact__content\">\n				<h6>رقم الهاتف</h6>\n				<p>+1 469 844 3346 <br />\n					+1 469 844 3346 <br />\n					+1 469 844 3346</p>\n			</div>\n		</div>\n	</div>\n</div>'),
(5, 3, 'Contacto Sección Izquierda', '<div class=\"col-md-5 col-lg-4\">\n	<div class=\"contact-info\">\n		<div class=\"contact-info__row\">\n			<div class=\"contact__icon\">\n				<svg class=\"icon icon--address\">\n					<use xlink:href=\"/images/sprite.svg#address\"></use>\n				</svg>\n			</div>\n			<div class=\"contact__content\">\n				<h6>Dirección</h6>\n				<p>CIC 3, Sector 67,<br />Sahibzada Ajit Singh Nagar,<br />Punjab 160062</p>\n			</div>\n		</div>\n		<div class=\"contact-info__row\">\n			<div class=\"contact__icon\">\n				<svg class=\"icon icon--mail\">\n					<use xlink:href=\"/images/sprite.svg#mail\"></use>\n				</svg>\n			</div>\n			<div class=\"contact__content\">\n				<h6>Correo electrónico</h6>\n				<p>sales@fatbit.com <br />sales@fatbit.com</p>\n			</div>\n		</div>\n		<div class=\"contact-info__row\">\n			<div class=\"contact__icon\">\n				<svg class=\"icon icon--telephone\">\n					<use xlink:href=\"/images/sprite.svg#telephone\"></use>\n				</svg>\n			</div>\n			<div class=\"contact__content\">\n				<h6>Nº de teléfono</h6>\n				<p>+1 469 844 3346 <br />+1 469 844 3346 <br />+1 469 844 3346</p>\n			</div>\n		</div>\n	</div>\n</div>');
