INSERT INTO `tbl_content_pages_block_lang` (`cpblocklang_id`, `cpblocklang_lang_id`, `cpblocklang_cpage_id`, `cpblocklang_block_id`, `cpblocklang_text`) VALUES
(NULL, 1, 1, 1, '<div class=\"section\">\n	<div class=\"row justify-content-between align-items-xl-center g-5\">\n		<div class=\"col-md-6\">\n			<div class=\"cms-media\" data-aos=\"fade-up\" data-aos-duration=\"1000\"><img\n					src=\"/image/editor-image/about-whoweare.png\" alt=\"\" /></div>\n		</div>\n		<div class=\"col-md-6 col-xl-5\">\n			<div class=\"cms\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n				<h4 class=\"mb-3\">It starts with Who We Are.</h4>\n				<h2 class=\"mb-3\">We build an organization to help people to learn online.</h2>\n				<p>Platform is a self-hosted solution that helps entrepreneurs to launch online tutoring and\n					consultation platforms where multiple tutors or consultants can register and deliver one-to-one or\n					group online sessions to learners. It is a highly scalable and fully customizable solution to meet\n					the business requirements of the users. The solution is pre-integrated with Cometchat, Lesson Space,\n					and Zoom to support features such as video chat, Whiteboard, Textpad, code editor, multiple screen\n					sharing, etc. which improves the interaction between tutor and learner during an online session.</p>\n			</div>\n		</div>\n	</div>\n</div>\n<div class=\"section\">\n	<div class=\"why-panel\">\n		<div class=\"section__header text-start\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n			<h4>Why Choose Us</h4>\n			<h2>To always learn and improve in order to create better world for the generations to come.</h2>\n		</div>\n		<div class=\"section__body\">\n			<div class=\"counters-list pt-4\">\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-1.png\" alt=\"\" /></div>\n					<span class=\"counter-card__value\">130 +</span><span class=\"counter-card__label\">Languages Available\n						to Learn</span>\n				</div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-2.png\" alt=\"\" /></div>\n					<span class=\"counter-card__value\">10k +</span><span class=\"counter-card__label\">Teachers From 120\n						Countries</span>\n				</div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-3.png\" alt=\"\" /></div>\n					<span class=\"counter-card__value\">5M +</span><span class=\"counter-card__label\">Learners From 180\n						Countries</span>\n				</div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-4.png\" alt=\"\" /></div>\n					<span class=\"counter-card__value\">5M +</span><span class=\"counter-card__label\">Learners From 180\n						Countries</span>\n				</div>\n			</div>\n		</div>\n	</div>\n</div>\n<div class=\"section section--testimonials\">\n	<div class=\"section__header text-start px-4\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"row align-items-center justify-content-between\">\n			<div class=\"col-xl-8\">\n				<h4>Our Core Values</h4>\n				<h2>We love clients who understand our values</h2>\n			</div>\n			<div class=\"col-xl-auto\">\n				<div class=\"slider-nav\">\n					<button type=\"button\" class=\"prev-slide slick-arrow\"></button>\n					<button type=\"button\" class=\"next-slide slick-arrow\"></button>\n				</div>\n			</div>\n		</div>\n	</div>\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"client-testimonials-list js--testimonials\">\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">01</span>Words of Appreciaton</h4>\n				</div>\n				<div class=\"client-testimonail__body\">\n					<p>Every solution was taking too much time with nothing less than 6 - 8 months, and it was time we\n						did not have. That\'s when Wale found FATbit\'s Platform. We explored our vision around what\n						Platform had to offer, and to our surprise, it fit exactly what we had in mind, and we had a\n						live demo of Platform. We took the chance of picking up a solution to run our vision on, and we\n						haven\'t regretted it any bit. So far, it\'s been a good one for the team.</p>\n				</div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">Mr. Chin Wei Seong</h6>\n				</div>\n			</div>\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">02</span>Words of Appreciaton</h4>\n				</div>\n				<div class=\"client-testimonail__body\">\n					<p>We are a brick-and-mortar physical location language school franchise. Once the COVID-19 shut\n						down happened we needed to move online. Platform provides a very modern platform for us to\n						execute not only language learning but all types of learning. </p>\n				</div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">Ray D Angelo</h6>\n				</div>\n			</div>\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">03</span>Words of Appreciaton</h4>\n				</div>\n				<div class=\"client-testimonail__body\">\n					<p>My journey with FATbit has been a long one. It took hours and patience to get the website done\n						and to the exact expectations I asked for. FATbit never gives up, they always deliver what they\n						say no matter how much overtime they spend on the project and customer. My developer Eddie, my\n						sales contact Kesa went over and above the call of duty to stay on top of this project. End\n						result; A beautiful and powerfully functional site that will change the world\'s way of learning\n						a new language. Thank you FATbit.</p>\n				</div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">Kelly</h6>\n				</div>\n			</div>\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">04</span>Words of Appreciaton</h4>\n				</div>\n				<div class=\"client-testimonail__body\">\n					<p>I\'m using dashboard of W3mentors platform without any complications and my customers can use my\n						platform in easy way.</p>\n				</div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">Yacine Tayebi</h6>\n				</div>\n			</div>\n		</div>\n	</div>\n</div>\n<div class=\"section\">\n	<div class=\"grey-wrapper\">\n		<div class=\"row justify-content\">\n			<div class=\"col-xl-4\">\n				<div class=\"section__header text-start\">\n					<h4>Our mission &amp; Vision</h4>\n					<h2 class=\"mb-4\">Get to know about our mission and vision</h2>\n					<a href=\"/contact\" class=\"btn btn--primary btn--large\">Contact Us</a>\n				</div>\n			</div>\n			<div class=\"col-xl-7\">\n				<div class=\"section__body\">\n					<div class=\"cms-panel mb-5 pb-2\">\n						<div class=\"cms-panel__media\">\n							<svg width=\"100\" height=\"100\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 512 512\">\n								<path\n									d=\"M409.78,0c4.98,3.24,6.05,7.96,5.97,13.64-.24,17.83-.09,35.67-.09,53.5,0,5.89,1.67,7.53,7.65,7.53,18.69,0,37.38-.01,56.06,0,6.34,0,10.37,3.07,11.4,8.78.55,3.07-.15,5.99-2.4,8.25-18.32,18.37-36.5,36.88-55.09,54.96-8.46,8.22-19.18,12.53-30.97,13-12.95.52-25.93.3-38.9.29-2.62,0-4.63.6-6.03,2.95-.6,1.01-1.52,1.84-2.36,2.68-34.75,34.76-69.51,69.51-104.26,104.27-6.71,6.72-14.54,9.51-23.74,6.19-13.52-4.88-18.86-21.82-9.59-32.73,7.93-9.33,17.08-17.64,25.76-26.33,11.09-11.11,22.26-22.15,33.39-33.22.54-.54,1.05-1.1,1.66-1.74-15.84-9.39-32.83-13.59-51.02-11.85-28.63,2.75-51.05,16.29-65.84,40.93-15.48,25.78-16.74,52.95-4.13,80.3,10.41,22.58,27.94,37.75,51.63,45.04,27.47,8.46,53.32,4.07,76.41-13.05,22.22-16.47,33.25-39.18,34.33-66.73.49-12.57,8.67-21.67,21.03-21.91,11.5-.22,20.61,7.98,21.41,19.18.85,11.93