ass=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n								<div class=\"tile__media ratio ratio--3by4\"><img\n										src=\"/image/editor-image/1650349756-saleshead364x3644.png\" alt=\"\" /></div>\n								<div class=\"tile__body\">\n									<h4>Steve Waugh</h4>\n									<div class=\"card-element justify-content-center\"><span\n											class=\"card-element__item\">Sales/Marketing Head</span></div>\n								</div>\n							</div>\n						</div>\n					</div>\n				</div>\n				<div class=\"slider__item\">\n					<div class=\"tile-cover\">\n						<div class=\"tile\">\n							<div class=\"tile__head\">\n								<div class=\"tile__media ratio ratio--3by4\"><img\n										src=\"/image/editor-image/1650349761-creativedirector2364x3645.jpg\" alt=\"\" />\n								</div>\n								<div class=\"tile__body\">\n									<h4>Damien Martyn</h4>\n									<div class=\"card-element justify-content-center\"><span\n											class=\"card-element__item\">Creative Director </span></div>\n								</div>\n							</div>\n						</div>\n					</div>\n				</div>\n			</div>\n		</div>\n	</div>\n</div>\n<div class=\"section section--HowItWorks\">\n	<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<h2>How to start learning with Platform?</h2>\n	</div>\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<nav class=\"inline-tabs\">\n			<ul class=\"js-tab list-unstyled\">\n				<li><a href=\"#tab__1\" class=\"current\">01. Search </a></li>\n				<li><a href=\"#tab__2\" class=\"\">02. Book </a> </li>\n				<li><a href=\"#tab__3\" class=\"\">03. Learn </a> </li>\n			</ul>\n		</nav>\n		<div class=\"flex-layout-wrapper\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n			<div class=\"tab-container visible\" id=\"tab__1\">\n				<div class=\"flex-layout\">\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/choose-your-tutor.png\" alt=\"\" /></div>\n					<div class=\"flex-layout__content\">\n						<div class=\"content\">\n							<h2>Search through hundreds of best teachers</h2>\n							<p class=\"p-large\">Use filters like price, language, proficiency, subject, location, to\n								search for your preferred teacher</p>\n							<div class=\"step__actions\"> <a href=\"/teachers\" class=\"btn btn--primary\" tabindex=\"0\">Browse\n									Tutors</a><a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\"\n									class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">\n									<svg class=\"icon icon--play\">\n										<use xlink:href=\"/images/sprite.svg#play\"></use>\n									</svg>Watch Video</a> </div>\n						</div>\n					</div>\n				</div>\n			</div>\n			<div class=\"tab-container\" id=\"tab__2\">\n				<div class=\"flex-layout\">\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/become-an-expert.png\" alt=\"\" /></div>\n					<div class=\"flex-layout__content\">\n						<div class=\"content\">\n							<h2>Book lessons with the best teacher for you</h2>\n							<p class=\"p-large\">Go through the teacher\'s profile and book a lesson after making the\n								payment.</p>\n							<div class=\"step__actions\"> <a href=\"/teachers\" class=\"btn btn--primary\" tabindex=\"0\">Browse\n									Tutors</a><a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\"\n									class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">\n									<svg class=\"icon icon--play\">\n										<use xlink:href=\"/images/sprite.svg#play\"></use>\n									</svg>Watch Video</a> </div>\n						</div>\n					</div>\n				</div>\n			</div>\n			<div class=\"tab-container\" id=\"tab__3\">\n				<div class=\"flex-layout\">\n					<div class=\"flex-layout__media\"><img src=\"/image/editor-image/book-your-free-lesson.png\" alt=\"\" />\n					</div>\n					<div class=\"flex-layout__content\">\n						<div class=\"content\">\n							<h2>Log in to Start learning</h2>\n							<p class=\"p-large\">Attend online lessons and start learning.</p>\n							<div class=\"step__actions\"> <a href=\"/teachers\" class=\"btn btn--primary\" tabindex=\"0\">Browse\n									Tutors</a><a data-src=\"https://www.youtube.com/embed/q_Fy8DceWZM?autoplay=1\"\n									class=\"btn btn--bordered color-secondary btn-video play-video\" tabindex=\"0\">\n									<svg class=\"icon icon--play\">\n										<use xlink:href=\"/images/sprite.svg#play\"></use>\n									</svg>Watch Video</a> </div>\n						</div>\n					</div>\n				</div>\n			</div>\n		</div>\n	</div>\n</div>'),
(NULL, 2, 1, 1, '\n<div class=\"section\">\n	<div class=\"row justify-content-between align-items-xl-center g-5\">\n		<div class=\"col-md-6\">\n			<div class=\"cms-media\" data-aos=\"fade-up\" data-aos-duration=\"1000\"><img src=\"/image/editor-image/about-whoweare.png\" alt=\"\" /></div></div>\n		<div class=\"col-md-6 col-xl-5\">\n			<div class=\"cms\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n				<h4 class=\"mb-3\">يبدأ بمن نحن.</h4>\n				<h2 class=\"mb-3\">نبني منظمة لمساعدة الناس على التعلم عبر الإنترنت.</h2>\n				<p>المنصة هي حل مستضاف ذاتيا يساعد رواد الأعمال على إطلاق دروس خصوصية عبر الإنترنت و\n					منصات الاستشارات حيث يمكن للعديد من المعلمين أو الاستشاريين التسجيل وتقديم الفردية أو\n					جلسات جماعية عبر الإنترنت للمتعلمين. إنه حل قابل للتطوير بدرجة كبيرة وقابل للتخصيص بالكامل لتلبية\n					متطلبات العمل للمستخدمين. تم دمج الحل مسبقا مع Cometchat ، Lesson Space ،\n					و Zoom لدعم ميزات مثل دردشة الفيديو ، والسبورة البيضاء ، ولوحة النص ، ومحرر التعليمات البرمجية ، والشاشات المتعددة\n					المشاركة ، وما إلى ذلك ، مما يحسن التفاعل بين المعلم والمتعلم أثناء الجلسة عبر الإنترنت.</p></div></div></div></div>\n<div class=\"section\">\n	<div class=\"why-panel\">\n		<div class=\"section__header text-start\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n			<h4>لماذا أخترتنا</h4>\n			<h2>التعلم والتحسين دائما من أجل خلق عالم أفضل للأجيال القادمة.</h2></div>\n		<div class=\"section__body\">\n			<div class=\"counters-list pt-4\">\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-1.png\" alt=\"\" /></div><span class=\"counter-card__value\">130 +</span><span class=\"counter-card__label\">اللغات المتاحة\n						ليتعلم</span></div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-2.png\" alt=\"\" /></div><span class=\"counter-card__value\">10 آلاف +</span> <span class=\"counter-card__label\">معلم من 120\n						البلدان</span></div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-3.png\" alt=\"\" /></div><span class=\"counter-card__value\">5 ملايين +</span> <span class=\"counter-card__label\">متعلمون من 180\n						البلدان</span></div>\n				<div class=\"counter-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n					<div class=\"counter-card__icon\"><img src=\"/image/editor-image/choose-icon-4.png\" alt=\"\" /></div><span class=\"counter-card__value\">5 ملايين +</span> <span class=\"counter-card__label\">متعلمون من 180\n						البلدان</span></div></div></div></div></div>\n<div class=\"section section--testimonials\">\n	<div class=\"section__header text-start px-4\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"row align-items-center justify-content-between\">\n			<div class=\"col-xl-8\">\n				<h4>قيمنا الأساسية</h4>\n				<h2>نحن نحب العملاء الذين يفهمون قيمنا</h2></div>\n			<div class=\"col-xl-auto\">\n				<div class=\"slider-nav\">\n					<button type=\"button\" class=\"prev-slide slick-arrow\"></button>\n					<button type=\"button\" class=\"next-slide slick-arrow\"></button></div></div></div></div>\n	<div class=\"section__body\" data-aos=\"fade-up\" data-aos-duration=\"1000\">\n		<div class=\"client-testimonials-list js--testimonials\">\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">01</span>كلمات التقدير</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>كان كل حل يستغرق الكثير من الوقت مع ما لا يقل عن 6-8 أشهر ، وقد حان الوقت\n						لم يكن لديه. وذلك عندما وجد Wale منصة FATbit. استكشفنا رؤيتنا حول ما\n						كان على المنصة أن تقدمها ، ولدهشتنا ، كانت تناسب تماما ما كان يدور في أذهاننا ، وكان لدينا\n						عرض توضيحي مباشر للمنصة. انتهزنا الفرصة لاختيار حل لتشغيل رؤيتنا ، ونحن\n						لم أندم على ذلك قليلا. حتى الآن ، كانت مباراة جيدة للفريق.</p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">السيد تشين وي سونغ</h6></div></div>\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">02</span>كلمات التقدير</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>نحن امتياز مدرسة لغة من الطوب وقذائف الهاون. بمجرد إغلاق COVID-19\n						حدث نزول كنا بحاجة إلى الانتقال عبر الإنترنت. توفر المنصة منصة حديثة جدا لنا\n						لا تنفذ تعلم اللغة فحسب ، بل جميع أنواع التعلم. </p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">راي دي أنجيلو</h6></div></div>\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">03</span>كلمات التقدير</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>كانت رحلتي مع FATbit طويلة. استغرق الأمر ساعات وصبرا لإنجاز الموقع\n						والتوقعات الدقيقة التي طلبتها. FATbit لا تستسلم أبدا ، فهي دائما ما تقدم ما تقدمه\n						قل بغض النظر عن مقدار العمل الإضافي الذي يقضونه في المشروع والعميل. المطور الخاص بي Eddie ، بلدي\n						ذهب الاتصال بالمبيعات Kesa إلى أكثر من نداء الواجب للبقاء على رأس هذا المشروع. انتهاء\n						نتيجة; موقع جميل وعملي بقوة سيغير طريقة التعلم في العالم\n						لغة جديدة. شكرا لك FATbit.</p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">كيلي</h6></div></div>\n			<div class=\"client-testimonail\">\n				<div class=\"client-testimonail__head\">\n					<h4><span class=\"num\">04</span>كلمات التقدير</h4></div>\n				<div class=\"client-testimonail__body\">\n					<p>أنا أستخدم لوحة القيادة الخاصة بمنصة W3mentors دون أي تعقيدات ويمكن لعملائي استخدام بلدي\n						منصة بطريقة سهلة.</p></div>\n				<div class=\"client-testimonail__foot\">\n					<h6 class=\"client-info\">ياسين الطيبي</h6></div></div></div></div></div>\n<div class=\"section\">\n	<div class=\"grey-wrapper\">\n		<div class=\"row justify-content\">\n			<div class=\"col-xl-4\">\n				<div class=\"section__header text-start\">\n					<h4>مهمتنا ورؤيتنا</h4>\n					<h2 class=\"mb-4\">تعرف على مهمتنا ورؤيتنا</h2><a href=\"/contact\" class=\"btn btn--primary btn--large\">اتصل بنا</a></div></div>\n			<div class=\"col-xl-7\">\n				<div class=\"section__body\">\n					<div class=\"cms-panel mb-5 pb-2\">\n						<div class=\"cms-panel__media\">\n							<svg width=\"100\" height=\"100\" xmlns=\"http://www.w3.org/2000/svg\" viewbox=\"0 0 512 512\">\n								<path d=\"M409.78,0c4.98,3.24,6.05,7.96,5.97,13.64-.24,17.83-.09,35.67-.09,53.5,0,5.89,1.67,7.53,7.65,7.53,18.69,0,37.38-.01,56.06,0,6.34,0,10.37,3.07,11.4,8.78.55,3.07-.15,5.99-2.4,8.25-18.32,18.37-36.5,36.88-55.09,54.96-8.46,8.22-19.18,12.53-30.97,13-12.95.52-25.93.3-38.9.29-2.62,0-4.63.6-6.03,2.95-.6,1.01-1.52,1.84-2.36,2.68-34.75,34.76-69.51,69.51-104.26,104.27-6.71,6.72-14.54,9.51-23.74,6.19-13.52-4.88-18.86-21.82-9.59-32.73,7.93-9.33,17.08-17.64,25.76-26.33,11.09-11.11,22.26-22.15,33.39-33.22.54-.54,1.05-1.1,1.66-1.74-15.84-9.39-32.83-13.59-51.02-11.85-28.63,2.75-51.05,16.29-65.84,40.93-15.48,25.78-16.74,52.95-4.13,80.3,10.41,22.58,27.94,37.75,51.63,45.04,27.47,8.46,53.32,4.07,76.41-13.05,22.22-16.47,33.25-39.18,34.33-66.73.49-12.57,8.67-21.67,21.03-21.91,11.5-.22,20.61,7.98,21.41,19.18.85,11.93-.89,23.67-4.17,35.14-12.16,42.46-39.01,71.63-80.2,87.28-20.73,7.88-42.31,9.57-64.22,5.91-28.77-4.8-53.13-18.04-72.98-39.26-16.51-17.65-27.17-38.51-31.68-62.33-5.98-31.51-1.31-61.46,15.1-89.01,19.15-32.15,47.23-52.63,84.01-60.53,27.65-5.94,54.46-2.42,80.38,8.37,7.3,3.04,14.31,6.78,21.67,10.31,4.28-4.25,8.78-8.77,13.34-13.23,1.58-1.54,3.48-2.79,4.89-4.47,1.01-1.21,1.96-2.88,2.04-4.4.27-4.59.19-9.21.03-13.82-.03-.82-.92-1.92-1.71-2.36-18.03-10.16-37.17-17.51-57.39-21.84-18.46-3.95-37.1-5.01-55.94-2.86-20.13,2.3-39.31,7.77-57.38,16.81-21,10.51-39.04,24.88-54.2,42.88-15.85,18.82-27.11,40.08-33.73,63.71-5.05,18.02-6.96,36.44-5.93,55.19,1.34,24.39,7.55,