CREATE TABLE `tbl_course_edit_requests` (
  `coedre_id` int NOT NULL,
  `coedre_course_id` int NOT NULL,
  `coedre_title` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `coedre_details` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `coedre_status` tinyint NOT NULL,
  `coedre_created` datetime DEFAULT NULL,
  `coedre_updated` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE `tbl_course_edit_requests`
  ADD PRIMARY KEY (`coedre_id`);

ALTER TABLE `tbl_course_edit_requests`
  MODIFY `coedre_id` int NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=1;

ALTER TABLE `tbl_lectures` ADD `lecture_archived` TINYINT(4) NOT NULL DEFAULT '0' AFTER `lecture_order`;
ALTER TABLE `tbl_course_edit_requests` ADD `coedre_updates_done` TINYINT NULL DEFAULT '0' AFTER `coedre_status`;




ALTER TABLE `tbl_course_edit_requests` ADD `coedre_recent` TINYINT NOT NULL COMMENT 'Recent request status' AFTER `coedre_updates_done`; 

UPDATE `tbl_email_templates` SET `etpl_body` = '\r\n<table width=\"600\" border=\"0\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Solicitud de curso recibida</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Estimado administrador</h3>\r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">El usuario {username} ha solicitado acceso de edición para el curso titulado \"{course_title}\". Por favor, revise la presentación lo antes posible.<br />\r\n									<br />\r\n									</p>\r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;text-align: center;\"><a href=\"{course_link}\" style=\"background:{secondary-color}; color:{secondary-inverse-color}; text-decoration:none;font-size:16px; font-weight:500;padding:10px 30px;display:inline-block;border-radius:3px;\">Ver Solicitud de Curso</a></p>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>' WHERE `tbl_email_templates`.`etpl_code` = 'course_edit_request_email_to_admin' AND `tbl_email_templates`.`etpl_lang_id` = 3; 
UPDATE `tbl_email_templates` SET `etpl_body` = '\r\n<table width=\"600\" border=\"0\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Actualización de la solicitud de edición del curso</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Estimado {username}</h3>\r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Hemos procesado su solicitud para el curso llamado \"{course_title}\". Después de la verificación, la solicitud se ha marcado como \"{request_status}\".<br />\r\n									                          </p></