UPDATE `tbl_pages_data` SET `pdata_helping_text` = '<ul><li>Manage edit requests submitted by teachers for modifying their published courses.</li><li>You can view the request details or the reason for editing by clicking the view icon in the list. </li><li>Requests can be approved to enable editing for the specified number of days set under Manage Settings > General Settings > Courses. Once approved, the expiration date for editing will be displayed in the "Expired on" column in the listing.<br /></li><li>Requests can also be declined with a reason, and the teacher will be notified accordingly. </li>	<li>Export the list of edit requests as a CSV (Comma Separated Value) file, which can be used for backup purposes or to utilize the data outside the platform.</li></ul>' WHERE `pdata_key` = 'course-edit-requests';
UPDATE `tbl_pages_language_data` SET `plang_helping_text` = '<ul><li>Manage edit requests submitted by teachers for modifying their published courses.</li><li>You can view the request details or the reason for editing by clicking the view icon in the list. </li><li>Requests can be approved to enable editing for the specified number of days set under Manage Settings > General Settings > Courses. Once approved, the expiration date for editing will be displayed in the "Expired on" column in the listing.<br /></li><li>Requests can also be declined with a reason, and the teacher will be notified accordingly. </li>	<li>Export the list of edit requests as a CSV (Comma Separated Value) file, which can be used for backup purposes or to utilize the data outside the platform.</li></ul>' WHERE `tbl_pages_language_data`.`plang_key` = 'course-edit-requests' AND `plang_lang_id` = 1;
UPDATE `tbl_pages_language_data` SET `plang_helping_text` = '<ul><li>إدارة طلبات التحرير المقدمة من قبل المعلمين لتعديل دوراتهم المنشورة.</li><li>يمكنك عرض تفاصيل الطلب أو سبب التحرير من خلال النقر على أيقونة العرض في القائمة. </li><li>يمكن الموافقة على الطلبات لتمكين التحرير لعدد محدد من الأيام ضمن إدارة الإعدادات > الإعدادات العامة > الدورات التدريبية. بمجرد الموافقة، سيتم عرض تاريخ انتهاء الصلاحية للتحرير في عمود "انتهت الصلاحية" في القائمة.<br /></li><li>يمكن أيضًا رفض الطلبات مع ذكر السبب، وسيتم إخطار المعلم وفقًا لذلك. </li> <li>قم بتصدير قائمة طلبات التحرير كملف CSV (قيمة مفصولة بفواصل)، والذي يمكن استخدامه لأغراض النسخ الاحتياطي أو للاستفادة من البيانات خارج النظام الأساسي.</li></ul>' WHERE `tbl_pages_language_data`.`plang_key` = 'course-edit-requests' AND `plang_lang_id` = 2;
UPDATE `tbl_pages_language_data` SET `plang_helping_text` = '<ul><li>Administre las solicitudes de edición enviadas por los profesores para modificar sus cursos publicados.</li><li>Puede ver los detalles de la solicitud o el motivo de la edición haciendo clic en el icono de vista en la lista. </li><li>Se pueden aprobar solicitudes para permitir la edición durante el número de días especificado establecido en Administrar configuración > Configuración general > Cursos. Una vez aprobada, la fecha de vencimiento para la edición se mostrará en la columna "Expirada el" del listado.<br /></li><li>Las solicitudes también se pueden rechazar con un motivo y se notificará al maestro en consecuencia. </li> <li>Exporte la lista de solicitudes de edición como un archivo CSV (valores separados por comas), que se puede utilizar con fines de copia de seguridad o para utilizar los datos fuera de la plataforma.</li></ul>' WHERE `tbl_pages_language_data`.`plang_key` = 'course-edit-requests' AND `plang_lang_id` = 3;


UPDATE `tbl_email_templates` SET `etpl_body` = '\r\n<table width=\"600\" border=\"0\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Course Edit Request Update</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Dear {username}</h3>\r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Your course edit request has been processed successfully. Below are the details for the same: <br /><br /></p>\r\n									\r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse;\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n									<tbody>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">Course Title</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{course_title}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">Status</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{request_status}</td>                                        \r\n										</tr>\r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">Expiry On</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{expiry_date}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">Comment/Reason</td>\r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{admin_comment}</td>\r\n										</tr>                                    \r\n									</tbody>                                \r\n								</table>\r\n									\r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">For more details, please contact admin.</p>\r\n							</td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', `etpl_vars` = '{username} Teacher name<br>\r\n{course_title} Course title<br>\r\n{request_status} Approved or Declined<br>\r\n{expiry_date} Expiry Date <br>\r\n{admin_comment} Declined reason <br>\r\n{website_name} - Website Name<br>' WHERE `tbl_email_templates`.`etpl_code` = 'course_edit_request_update_email_to_teacher' AND `tbl_email_templates`.`etpl_lang_id` = 1;
UPDATE `tbl_email_templates` SET `etpl_body` = '\r\n<table width=\"600\" border=\"0\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">تعديل طلب تحديث الدورة التدريبية</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">{username} عزيزي </h3>\r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">تمت معالجة طلب تعديل الدورة التدريبية بنجاح. وفيما يلي التفاصيل لنفسه: <br /><br /></p>\r\n									\r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse;\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n									<tbody>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">عنوان الدورة</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{course_title}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">حالة</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{request_status}</td>                                        \r\n										</tr>\r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">انتهاء الصلاحية</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{expiry_date}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">التعليق/السبب</td>\r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{admin_comment}</td>\r\n										</tr>                                    \r\n									</tbody>                                \r\n								</table>\r\n									\r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">لمزيد من التفاصيل، يرجى الاتصال بالمسؤول.</p>\r\n							</td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', `etpl_vars` = '{username} Teacher name<br> {course_title} Course title<br> {request_status} Approved or Declined<br>\r\n{expiry_date} Expiry Date <br>\r\n{admin_comment} Declined reason <br> {website_name} - Website Name<br>' WHERE `tbl_email_templates`.`etpl_code` = 'course_edit_request_update_email_to_teacher' AND `tbl_email_templates`.`etpl_lang_id` = 2;
UPDATE `tbl_email_templates` SET `etpl_body` = '\r\n<table width=\"600\" border=\"0\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\">    \r\n	<tbody>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:20px 0\">                                \r\n								<h5 style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\"></h5>                                \r\n								<h2 style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;\">Actualización de solicitud de edición de curso</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">Estimado {username}</h3>\r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Su solicitud de edición de curso se ha procesado correctamente. A continuación se detallan los detalles del mismo: <br /><br /></p>\r\n									\r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse;\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n									<tbody>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">Título del curso</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{course_title}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">Estado</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{request_status}</td>                                        \r\n										</tr>\r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">Vencimiento el</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{expiry_date}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"153\">Comentario/Razón</td>\r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"620\">{admin_comment}</td>\r\n										</tr>                                    \r\n									</tbody>                                \r\n								</table>\r\n									\r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Para obtener más detalles, comuníquese con el administrador.</p>\r\n							</td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', `etpl_vars` = '{username} Teacher name<br> {course_title} Course title<br> {request_status} Approved or Declined<br>\r\n{expiry_date} Expiry Date <br>\r\n{admin_comment} Declined reason <br> {website_name} - Website Name<br>' WHERE `tbl_email_templates`.`etpl_code` = 'course_edit_request_update_email_to_teacher' AND `tbl_email_templates`.`etpl_lang_id` = 3;
ALTER TABLE `tbl_order_courses` ADD `ordcrs_course_type` TINYINT(1) NOT NULL AFTER `ordcrs_course_id`; 
UPDATE `tbl_order_courses` INNER JOIN (SELECT course_id, course_type FROM tbl_courses) as c ON c.course_id = ordcrs_course_id SET ordcrs_course_type = c.course_type;

