ualizado.<br />\r\n									</p>                           </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>' WHERE `tbl_email_templates`.`etpl_code` = 'course_modifications_completed_email' AND `tbl_email_templates`.`etpl_lang_id` = 3;

