n:center;\">                                    Actualización de la solicitud del RGPD</h2>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>        \r\n		<tr>            \r\n			<td style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">                \r\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">                    \r\n					<tbody>                        \r\n						<tr>                            \r\n							<td style=\"padding:40px 0 60px;\">                                \r\n								<h3 style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">                                    Estimado {username}</h3>                                \r\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Eliminación de tu cuenta\r\n                                    La solicitud asociada con el ID de cuenta {email} ha sido procesada por el\r\n                                    Admin.<br />\r\n									                                    <br />A continuación se muestran los detalles actualizados:                                </p>                                \r\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">                                    \r\n									<tbody>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Estado de la solicitud</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{request_status}</td>                                        \r\n										</tr>                                        \r\n										<tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Datos eliminados</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{data_removal_status}</td>                                        \r\n										</tr>  <tr>                                            \r\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\" width=\"40%\">Razón (si es rechazado)</td>                                            \r\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\" width=\"60%\">{declined_reason}</td>                                        \r\n										</tr>                                  \r\n									</tbody>                                \r\n								</table>                            </td>                        \r\n						</tr>                    \r\n					</tbody>                \r\n				</table>            </td>        \r\n		</tr>    \r\n	</tbody>\r\n</table>', `etpl_vars` = '{username} User Full Name<br>\r\n{email} User Email<br>\r\n{request_status} Request Stauts<br>\r\n{data_removal_status} Data is removed or not<br>\r\n{declined_reason} Request declined reason<br>\r\n{website_name} - Website Name<br>' WHERE `tbl_email_templates`.`etpl_code` = 'delete_account_request_status_update_email' AND `tbl_email_templates`.`etpl_lang_id` = 3;

UPDATE `tbl_extra_pages` SET `epage_default_content` = '<section class=\"section\">    \r\n	<div class=\"container container--xxl\">        \r\n		<div class=\"grid-layout\" data-aos=\"fade-up\" data-aos-duration=\"1000\">            \r\n			<div class=\"grid-layout__item\">                \r\n				<div class=\"cta-card\">                    \r\n					<div class=\"cta-card__media\">                        <img src=\"/image/editor-image/cta__student-img.png\" alt=\"\" />                    </div>                    \r\n					<div class=\"cta-card__content\">                        \r\n						<h2>Join now to start learning</h2>                        \r\n						<p>Learn from our quality instructors!</p>                        <a href=\"guest-user/register-form\" class=\"btn btn--primary btn--large\">Get Started</a>                    </div>                </div>            </div>            \r\n			<div class=\"grid-layout__item\">                \r\n				<div class=\"cta-card\">                    \r\n					<div class=\"cta-card__media\">                        <img src=\"/image/editor-image/cta__student-img-2.png\" alt=\"\" />                    </div>                    \r\n					<div class=\"cta-card__content\">                        \r\n						<h2>Become a new instructor</h2>                        \r\n						<p>Teach thousands of students and earn money!</p>                        <a href=\"teacher-request\" class=\"btn btn--primary btn--large\">Get Started</a>                    </div>                </div>            </div>        </div>    </div></section>' WHERE `tbl_extra_pages`.`epage_block_type` = 24;
UPDATE `tbl_extra_pages` SET `epage_default_content` = '<div class=\"container container--xxl\">                \r\n	<div class=\"section__header\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                    \r\n		<h2>We Make Language Learning Easy &amp; Simpler</h2>                </div>                \r\n	<div class=\"section__body\">                    \r\n		<div class=\"grid-blocks\">                        \r\n			<div class=\"cms-block\" data-aos=\"fade-right\" data-aos-duration=\"1000\">                            \r\n				<div class=\"cms-block__media\">                                \r\n					<div class=\"media ratio ratio--4by3\">                                    <img src=\"/image/editor-image/cms-block-img__1.png\" alt=\"\" />                                </div>                            </div>                            \r\n				<div class=\"cms-block__content\">                                \r\n					<h3>Professional Tutors</h3>                                \r\n					<p>Choose from over a myriad of professional &amp; experienced teachers to be fluent in any language.</p>                            </div>                        </div>                        \r\n			<div class=\"cms-block\" data-aos=\"fade-up\" data-aos-duration=\"600\">                            \r\n				<div class=\"cms-block__media\">                                \r\n					<div class=\"media ratio ratio--4by3\">                                    <img src=\"/image/editor-image/cms-block-img__2.png\" alt=\"\" />                                </div>                            </div>                            \r\n				<div class=\"cms-block__content\">                                \r\n					<h3>1-on-1 Live sessions</h3>                                \r\n					<p>Connect with your teachers via 1-on-1 live chat sessions and build a deeper understanding of a language.</p>                            </div>                        </div>                        \r\n			<div class=\