UPDATE `tbl_extra_pages` SET `epage_default_content` = '<section class=\"section\"> \r\n	<div class=\"container container--xxl\"> \r\n		<div class=\"section--cta\" style=\"background-image:url(/image/editor-image/1600x514.jpg);\" data-aos=\"fade-up\" data-aos-duration=\"1000\"> \r\n			<div class=\"cta-content\"> \r\n				<h6></h6> \r\n				<h2>Learn any Subject with the help of professional teachers</h2> <a class=\"btn btn--primary btn--large\" href=\"teachers\">Browse Teachers</a> </div> </div> </div></section>' WHERE `tbl_extra_pages`.`epage_block_type` = 3;


