UPDATE `tbl_pages_language_data` SET `plang_key` = 'teacher-payouts-report', `plang_title` = 'تقرير مدفوعات المعلمين', `plang_summary` = 'إحصائيات متعلقة بالمبالغ المدفوعة للمعلمين', `plang_helping_text` = '\r\n<ul>        \r\n	<li>يسلط هذا التقرير الضوء على المبالغ التي تم صرفها كمدفوعات للمعلمين عند تسوية دروسهم الفردية المكتملة والفصول والدورات.</li>        \r\n	<li>قم بتصدير هذا التقرير في شكل ملف CSV (قيم مفصولة بفاصلة). يمكن استخدام هذا الملف للاحتفاظ بنسخة احتياطية أو استخدام البيانات ذات الصلة خارج المنصة.</li>        \r\n	<li>قم بإجراء بحث سهل باستخدام الفلاتر المختلفة المتاحة في هذه الصفحة.</li>\r\n</ul> ' WHERE `plang_key` = 'payouts-report' AND `plang_lang_id` = 2;  
UPDATE `tbl_pages_language_data` SET `plang_key` = 'teacher-payouts-report', `plang_title` = 'Informe de pagos a profesores', `plang_summary` = 'Estadísticas relacionadas con los montos pagados a los profesores', `plang_helping_text` = '\r\n<ul>        \r\n	<li>Este informe destaca los montos ya desembolsados como pagos a los profesores tras la liquidación de sus lecciones, clases y cursos individuales completados.</li>        \r\n	<li>Exporte este informe en forma de un archivo CSV (valores separados por comas). Este archivo puede usarse para mantener una copia de seguridad o utilizar los datos relacionados fuera de la plataforma.</li>        \r\n	<li>Realice una búsqueda sencilla utilizando los diferentes filtros proporcionados en esta página.</li>\r\n</ul> '  WHERE `plang_key` = 'payouts-report' AND `plang_lang_id` = 3; 

