UPDATE `tbl_extra_pages` SET `epage_default_content` = '\n<div class=\"container container--xxl\">        \n	<div class=\"section__header\">            \n		<h2>Benefits of becoming a teacher on w3mentors?</h2>        </div>        \n	<div class=\"section__body\">            \n		<div class=\"row g-xl-5 g-4\">                \n			<div class=\"col-xl-4 col-md-6\">                    \n				<div class=\"site-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                        \n					<div class=\"site-card__media\">                            \n						<figure class=\"media\">                                <img src=\"/image/editor-image/cardicon1.png\" alt=\"\" />                            </figure>                        </div>                        \n					<div class=\"site-card__content\">                            \n						<h3>Make money online</h3>                            \n						<p>Opportunity to make money online from working from home</p>                        </div>                    </div>                </div>                \n			<div class=\"col-xl-4 col-md-6\">                    \n				<div class=\"site-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                        \n					<div class=\"site-card__media\">                            \n						<figure class=\"media\">                                <img src=\"/image/editor-image/cardicon2.png\" alt=\"\" />                            </figure>                        </div>                        \n					<div class=\"site-card__content\">                            \n						<h3>Work anywhere, anytime</h3>                            \n						<p>Flexibility to teach at home without wasting productive time.</p>                        </div>                    </div>                </div>                \n			<div class=\"col-xl-4 col-md-6\">                    \n				<div class=\"site-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                        \n					<div class=\"site-card__media\">                            \n						<figure class=\"media\">                                <img src=\"/image/editor-image/cardicon3.png\" alt=\"\" />                            </figure>                        </div>                        \n					<div class=\"site-card__content\">                            \n						<h3>Mark on your schedule.</h3>                            \n						<p>The ability to perform your educational duties at your convenience.</p>                        </div>                    </div>                </div>                \n			<div class=\"col-xl-4 col-md-6\">                    \n				<div class=\"site-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                        \n					<div class=\"site-card__media\">                            \n						<figure class=\"media\">                                <img src=\"/image/editor-image/cardicon4.png\" alt=\"\" />                            </figure>                        </div>                        \n					<div class=\"site-card__content\">                            \n						<h3>Manage your students</h3>                            \n						<p>Teach as many students as possible or as few students as you like.</p>                        </div>                    </div>                </div>                \n			<div class=\"col-xl-4 col-md-6\">                    \n				<div class=\"site-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                        \n					<div class=\"site-card__media\">                            \n						<figure class=\"media\">                                <img src=\"/image/editor-image/cardicon5.png\" alt=\"\" />                            </figure>                        </div>                        \n					<div class=\"site-card__content\">                            \n						<h3>Find more students</h3>                                \n						<p>Ability to teach students from all over the world without traveling.</p>                        </div>                    </div>                </div>                \n			<div class=\"col-xl-4 col-md-6\">                    \n				<div class=\"site-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                        \n					<div class=\"site-card__media\">                            \n						<figure class=\"media\">                                <img src=\"/image/editor-image/cardicon6.png\" alt=\"\" />                            </figure>                        </div>                        \n					<div class=\"site-card__content\">                            \n						<h3>Safety &amp; Security</h3>                                \n						<p>Considering all the benefits, you will be professionally satisfied.</p>                        </div>                    </div>                </div>            </div>        </div>    </div>' WHERE `tbl_extra_pages`.`epage_block_type` = 6;
UPDATE `tbl_extra_pages` SET `epage_default_content` = '\r\n<div class=\"container container--xxl\">        \r\n	<div class=\"row g-5 justify-content-between align-items-center\">            \r\n		<div class=\"col-xl-4 col-md-6\">                \r\n			<div class=\"section__header text-start\">                    \r\n				<h2>Teach students from over 180 countries</h2>                </div>                \r\n			<ul class=\"list-group list-group--tick\">                    \r\n				<li>Steady stream of new students</li>                    \r\n				<li>Smart calendar</li>                    \r\n				<li>Interactive classroom</li>                    \r\n				<li>Convenient payment methods</li>                    \r\n				<li>Training webinars</li>                    \r\n				<li>Supportive tutor community</li>                \r\n			</ul>            </div>            \r\n		<div class=\"col-md-6\">                \r\n			<div class=\"media-wrap\"><img src=\"/image/editor-image/teaching-img.png\" alt=\"\" /></div>            </div>        </div>    </div>' WHERE `tbl_extra_pages`.`epage_block_type` = 7; 
UPDATE `tbl_extra_pages` SET `epage_default_content` = '\r\n<div class=\"container\">        \r\n	<div class=\"section__header\">            \r\n		<h2>How to Become a Teacher on the Platform?</h2>        </div>        \r\n	<div class=\"section__body\">            \r\n		<div class=\"row g-xl-5 g-4\">                \r\n			<div class=\"col-md-4\">                    \r\n				<div class=\"step-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                        \r\n					<div class=\"step-card__media\"> <img src=\"/image/editor-image/icon-register.png\" /> </div>                        \r\n					<div class=\"step-card__content\">                            \r\n						<h3>Register on Platform</h3>                            \r\n						<p>Register as a teacher on Platform and start filling in the required information.</p>                        </div>                    </div>                </div>                \r\n			<div class=\"col-md-4\">                    \r\n				<div class=\"step-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                        \r\n					<div class=\"step-card__media\"> <img src=\"/image/editor-image/icon-profile.png\" /> </div>                        \r\n					<div class=\"step-card__content\">                            \r\n						<h3>Complete Profile</h3>                            \r\n						<p>Complete the profile by adding qualifications, experience, and skills.</p>                        </div>                    </div>                </div>                \r\n			<div class=\"col-md-4\">                    \r\n				<div class=\"step-card\" data-aos=\"fade-up\" data-aos-duration=\"1000\">                        \r\n					<div class=\"step-card__media\"> <img src=\"/image/editor-image/icon-teaching.png\" /> </div>                        \r\n					<div class=\"step-card__content\">                            \r\n						<h3>Start Teaching</h3>                            \r\n						<p>Accept session requests and start taking online classes.</p>                        </div>                    </div>                </div>            </div>        </div>    </div>' WHERE `tbl_extra_pages`.`epage_block_type` = 8; 
UPDATE `tbl_extra_pages` SET `epage_default_content` = '\r\n<div class=\"container container--xxl\">        \r\n	<div class=\"cta-block\" data-aos=\"fade-up\" data-aos-duration=\"1000\">            \r\n		<div class=\"cta-block__content\">                \r\n			<div class=\"content\">                    \r\n				<h2>Do you want to become a teacher on w3mentors?</h2>                    \r\n				<p>Connect with thousands of learners around the world and teach from your living room</p>                    \r\n				<button class=\"btn btn--primary applytoteach\">Apply Now</button>                </div>            </div>            \r\n		<div class=\"cta-block__media\">                \r\n			<picture>                    <img srcset=\"/image/editor-image/cta-block-img.png\" alt=\"\" />                </picture>            </div>        </div>    </div>' WHERE `tbl_extra_pages`.`epage_block_type` = 9;
