UPDATE `tbl_email_templates` SET `etpl_body` = '<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">\n	<tbody>\n		<tr>\n			<td\n				style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">\n					<tbody>\n						<tr>\n							<td style=\"padding:20px 0\">\n								<h5\n									style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\">\n								</h5>\n								<h2\n									style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;background-color: rgb(255, 255, 255); margin: 8px 0px 0px; padding: 0px; font-size: 30px;\">\n									طلب حذف الحساب </h2>\n							</td>\n						</tr>\n					</tbody>\n				</table>\n			</td>\n		</tr>\n		<tr>\n			<td\n				style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">\n				<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">\n					<tbody>\n						<tr>\n							<td style=\"padding:40px 0 60px;\">\n								<h3\n									style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">\n									عزيزي المشرف</h3>\n								<p style=\"font-size: 14px; line-height: 20px;color: #676767;\">تلقيت\n									طلب حذف الحساب من مستخدم. يرجى النظر في التفاصيل أدناه لمزيد من المعلومات\n									تجهيز:</p>\n								<table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\"\n									cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n									<tbody>\n										<tr>\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\"\n												width=\"40%\">اسم المستخدم</td>\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\"\n												width=\"60%\">{username}\n											</td>\n										</tr>\n										<tr>\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\"\n												width=\"40%\">البريد الإلكتروني</td>\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\"\n												width=\"60%\">{email}\n											</td>\n										</tr>\n										<tr>\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\"\n												width=\"40%\">نوع الحساب</td>\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\"\n												width=\"60%\">{account_type}</td>\n										</tr>\n										<tr>\n											<td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\"\n												width=\"40%\">سبب</td>\n											<td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\"\n												width=\"60%\">{deletion_reason}</td>\n										</tr>\n									</tbody>\n								</table>\n							</td>\n						</tr>\n					</tbody>\n				</table>\n			</td>\n		</tr>\n	</tbody>\n</table>' WHERE `etpl_code` = 'delete_account_request_email' AND `etpl_lang_id` = 2;

UPDATE `tbl_email_templates` SET `etpl_body` = '<table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">\n    <tbody>\n        <tr>\n            <td\n                style=\"background:#fff;padding:0 40px; text-align:center; color:#999;vertical-align:top; border-bottom:1px solid #eee;\">\n                <table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">\n                    <tbody>\n                        <tr>\n                            <td style=\"padding:20px 0\">\n                                <h5\n                                    style=\"margin: 0;padding: 0; text-transform: uppercase; font-size: 16px;font-weight: 500;color: #333;\">\n                                </h5>\n                                <h2\n                                    style=\"margin:8px 0 0;padding: 0; font-size:30px;font-weight: 700;color: {primary-color};text-align:center;background-color: rgb(255, 255, 255); margin: 8px 0px 0px; padding: 0px; font-size: 30px;\">\n                                    Solicitud de eliminación de cuenta </h2>\n                            </td>\n                        </tr>\n                    </tbody>\n                </table>\n            </td>\n        </tr>\n        <tr>\n            <td\n                style=\"background:#fff;padding:0 40px; text-align:left; color:#999;vertical-align:top; border-bottom:1px solid #eee; \">\n                <table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" align=\"center\">\n                    <tbody>\n                        <tr>\n                            <td style=\"padding:40px 0 60px;\">\n                                <h3\n                                    style=\"margin: 0 0 10px;font-size: 24px; font-weight: 500; padding: 0;color: #333;text-align:center;\">\n                                    Estimado administrador</h3>\n                                <p style=\"font-size: 14px; line-height: 20px;color: #676767;\">Ha recibido un\n                                    Solicitud de eliminación de cuenta de un usuario. Tenga en cuenta los detalles a\n                                    continuación para obtener más información.\n                                    Tratamiento:</p>\n                                <table style=\"border:1px solid #ddd; border-collapse:collapse; width:100%\"\n                                    cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                                    <tbody>\n                                        <tr>\n                                            <td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\"\n                                                width=\"40%\">Nombre de usuario</td>\n                                            <td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\"\n                                                width=\"60%\">{username}\n                                            </td>\n                                        </tr>\n                                        <tr>\n                                            <td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\"\n                                                width=\"40%\">Correo electrónico</td>\n                                            <td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\"\n                                                width=\"60%\">{email}\n                                            </td>\n                                        </tr>\n                                        <tr>\n                                            <td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\"\n                                                width=\"40%\">Tipo de cuenta</td>\n                                            <td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\"\n                                                width=\"60%\">{account_type}</td>\n                                        </tr>\n                                        <tr>\n                                            <td style=\"padding:10px;font-size:13px;border:1px solid #ddd; color:#333; font-weight:bold;\"\n                                                width=\"40%\">Razón</td>\n                                            <td style=\"padding:10px;font-size:13px; color:#333;border:1px solid #ddd;\"\n                                                width=\"60%\">{deletion_reason}</td>\n                                        </tr>\n                                    </tbody>\n                                </table>\n                            </td>\n                        </tr>\n                    </tbody>\n                </table>\n            </td>\n        </tr>\n    </tbody>\n</table>' WHERE `etpl_code` = 'delete_account_request_email' AND `etpl_lang_id` = 3;

